window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0125", [{"word":"natural disaster","ipa_uk":"/ˌnætʃrəl dɪˈzɑːstə/","ipa_us":"/ˌnætʃərəl dɪˈzæstər/","definition_zh":"自然灾害；由自然力量造成、并非人为引发的破坏性事件","definition_en":"a damaging event caused by natural forces rather than by deliberate human action","core_image":"泥水漫过村口石桥，屋顶只剩一角露在浑黄的洪水里","scene":"连日暴雨冲垮山体，泥流埋住半个村庄，救援队称这是当地十年未遇的自然灾害。After days of rain a hillside collapsed and buried half the village, a natural disaster the region had not seen in ten years.","sceneCN":"这里 natural disaster 指「由自然力量造成、并非人为引发的破坏性事件」（第 1 个义项：自然因素主导的成灾事件）；句意为连日暴雨导致山体崩塌、埋没半个村庄，是当地十年未遇的自然灾害。可辨识物件：浑黄泥流、被埋屋顶、断裂石桥、救援绳。","pos":[{"tag":"n.","zh":"自然灾害（可数；指一次具体事件）"}],"collocations":[{"phrase":"natural disaster area","zh":"自然灾害灾区"},{"phrase":"natural disaster relief","zh":"自然灾害救助"},{"phrase":"natural disaster risk","zh":"自然灾害风险"},{"phrase":"natural disaster insurance","zh":"自然灾害保险"},{"phrase":"declare a natural disaster","zh":"宣布进入自然灾害状态"},{"phrase":"natural disaster management","zh":"自然灾害管理"}],"forms":[{"label":"复数","form":"natural disasters"},{"label":"相关形容词（自然的）","form":"natural（自然的；天生的）"},{"label":"相关名词（灾害）","form":"disaster（灾害；灾难）"},{"label":"相关形容词（灾难性的）","form":"disastrous（灾难性的）"},{"label":"反义说法（人为灾害）","form":"man-made disaster（人为灾害）"},{"label":"相关术语（自然致灾因子）","form":"natural hazard（自然致灾因子）"}],"derivatives":[{"word":"natural","pos":"adj.","zh":"自然的；天生的；正常的"},{"word":"naturally","pos":"adv.","zh":"自然地；天然地"},{"word":"disaster","pos":"n.","zh":"灾害；灾难；彻底的失败"},{"word":"disastrous","pos":"adj.","zh":"灾难性的；极糟的"},{"word":"disastrously","pos":"adv.","zh":"灾难性地"}],"senses":[{"no":"01","title":"A damaging event driven by natural forces","titleCN":"由自然力量主导的成灾事件","definition":"a sudden event such as an earthquake, flood or storm that harms people, property or land and is not caused by human intent","definitionCN":"地震、洪水或风暴等突发事件，损害人、财产或土地，并非出于人的意图","example":"The flood that swept the valley was a natural disaster, not a construction failure.","exampleCN":"冲过山谷的那场洪水是自然灾害，而不是施工失误。","why":"disaster names the harm to people, while natural removes human intent, so the phrase marks an event whose cause lies outside human control.","whyCN":"disaster 说的是对人造成的损害，natural 则排除人的意图，因此这个短语标记的是原因不在人掌控之内的事件。"},{"no":"02","title":"A formal category in law and aid","titleCN":"法律与救援体系中的正式类别","definition":"a legally declared category that unlocks emergency funds, relief and insurance payments","definitionCN":"依法宣布的类别，用以启动应急资金、救助与保险赔付","example":"Only after the governor declared a natural disaster could federal funds be released.","exampleCN":"直到州长宣布进入自然灾害状态，联邦资金才得以拨付。","why":"once money and duties depend on the label, the phrase becomes a legal switch rather than a description.","whyCN":"一旦资金与责任取决于这个名目，短语就从描述变成了法律上的开关。"},{"no":"03","title":"A hazard that turns into loss","titleCN":"自然致灾因子转化为损失","definition":"a natural hazard that meets exposed people and property, turning a physical event into measurable loss","definitionCN":"自然致灾因子遇上暴露的人与财产，把物理事件变成可计量的损失","example":"A drought becomes a natural disaster only where farms depend on rain.","exampleCN":"干旱只有在农场依赖降雨的地方才会成为自然灾害。","why":"the same hazard may pass without harm where nobody and nothing is exposed, so disaster is a meeting of event and vulnerability.","whyCN":"同样的致灾因子在无人无物暴露的地方可能无害而过，所以灾害是事件与脆弱性的相遇。"},{"no":"04","title":"A slow-onset disaster","titleCN":"缓慢累积型灾害","definition":"a disaster that builds over years, such as drought or desertification, rather than striking in a single hour","definitionCN":"在数年间逐步累积的灾害，如干旱或荒漠化，而非一小时内的突袭","example":"Drought is a slow-onset natural disaster that rarely makes the evening news.","exampleCN":"干旱是一种缓慢累积的自然灾害，很少登上晚间新闻。","why":"the phrase was extended from sudden shocks to creeping losses once researchers needed to count years of failing rain as one event.","whyCN":"研究者需要把连续数年缺雨算作一次事件之后，这个短语便从突发冲击扩展到缓慢累积的损失。"},{"no":"05","title":"A compound or cascading disaster","titleCN":"复合与连锁灾害","definition":"a disaster in which one natural event triggers others, such as an earthquake that causes a tsunami and a fire","definitionCN":"一种自然事件引发另一些的灾害，如地震引发海啸与火灾","example":"The earthquake, tsunami and nuclear accident formed a compound natural disaster.","exampleCN":"地震、海啸与核事故构成了一场复合自然灾害。","why":"modern risk studies added the compound reading because single-hazard labels hid how one event amplifies the next.","whyCN":"现代风险研究补上复合义，是因为单一灾种标签掩盖了一件事放大另一件事的过程。"},{"no":"06","title":"A disaster risk reduction target","titleCN":"减灾政策中的治理对象","definition":"the object of prevention, preparedness and land-use rules rather than only of rescue","definitionCN":"预防、备灾与土地利用规则的治理对象，而不只是救援对象","example":"Zoning rules turned the coastal storm from a recurring natural disaster into a manageable risk.","exampleCN":"分区规则使沿海风暴从反复发生的自然灾害变成可管理的风险。","why":"if the harm depends on exposure, then the phrase can name something to be reduced before it happens.","whyCN":"既然损害取决于暴露程度，这个短语就可以指一件能在发生之前被削减的事。"},{"no":"07","title":"Hardship blamed on nature","titleCN":"把困苦归因于自然的说法","definition":"an everyday use in which personal or social misfortune is loosely attributed to natural causes","definitionCN":"日常用法，把个人或社会的不幸宽泛地归因于自然原因","example":"Losing the harvest to hail felt like a natural disaster for the small farm.","exampleCN":"收成被冰雹毁掉，对这家小农场来说就像一场自然灾害。","why":"the phrase leaks out of technical writing because blaming nature is an old human habit for explaining sudden loss.","whyCN":"这个短语会溢出技术文本，因为把突发损失归因于自然，是人类由来已久的解释习惯。"},{"no":"08","title":"Abstract: an unavoidable collective shock","titleCN":"抽象义：难以避免的集体冲击","definition":"a metaphor for any overwhelming collective shock that seems to arrive from outside human control","definitionCN":"隐喻任何仿佛来自人力之外、压倒性的集体冲击","example":"The collapse of the local mill was an economic natural disaster for the town.","exampleCN":"本地磨坊倒闭，对小镇来说是一场经济上的自然灾害。","why":"the metaphor works by borrowing the phrase's core claim, that the cause is beyond the victims' control.","whyCN":"这个隐喻借用了短语的核心主张：原因超出受害者的掌控。"}],"etymology":{"intro":{"en":"The phrase joins two borrowings. Natural comes from Latin natura 'birth, the course of things', and disaster from Greek astron 'star' through the idea of a bad star. Dates are approximate.","cn":"这个短语由两个借词组成：natural 来自拉丁 natura「出生、事物的进程」，disaster 则经「凶星」的观念来自希腊 astron「星」。年代均为约数。"},"items":[{"era":"LATIN NATURA","en":"Natura meant 'birth, character, the ordinary course of things', formed from nasci 'to be born'; its pre-Latin origin is not established.","cn":"natura 意为「出生、本性、事物的常轨」，由 nasci「出生」构成；它在拉丁语之前的来源未得到证明。"},{"era":"GREEK ASTRON","en":"Greek astron 'star' plus the turning idea in strephein produced katastrophē 'an overturning', later applied to a sudden ruin.","cn":"希腊 astron「星」加上 strephein 的「翻转」之意，构成 katastrophē「倾覆」，后来用于指突然的毁灭。"},{"era":"MIDDLE FRENCH DESASTRE","en":"Old French desastre, from des- 'ill' plus astre 'star', first meant misfortune blamed on an unlucky planet; English took it in the sixteenth century.","cn":"古法语 desastre 由 des-「不吉」加 astre「星」构成，最初指归咎于凶星的不幸；英语于 16 世纪借入。"},{"era":"FIXED PHRASE","en":"Natural disaster is a modern fixed combination; it spread with nineteenth-century insurance and twentieth-century emergency agencies.","cn":"natural disaster 是近代固定搭配，随 19 世纪保险业与 20 世纪应急机构而普及。"},{"era":"HAZARD VERSUS DISASTER","en":"Twentieth-century risk research drew the line: a hazard is the physical event, a disaster is the loss that follows where people and property are exposed.","cn":"20 世纪风险研究划出界线：致灾因子是物理事件，灾害则是人与财产暴露之后随之而来的损失。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest citation of the exact phrase is not fixed, and the deeper origin of nasci is unsettled, so any Indo-European form offered for it is a reconstruction.","cn":"来源不确定（首见年代）：这一确切短语的最早书证尚无定论；nasci 的更深来源亦未确定，凡为其给出的印欧形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds hazard words often mistaken for the disaster itself; group two holds terms for the human side of the same event.","cn":"第一组是常被误当作灾害本身的致灾词；第二组是同一事件中属于人的一面所用的术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"natural hazard","ipa":"/ˌnætʃrəl ˈhæzəd/","tag":"the event, not the loss","definition":"The physical event itself, such as a fault rupture or a storm; it becomes a disaster only where it meets exposed people.","definitionCN":"指物理事件本身，如断层错动或风暴；只有在遇到暴露的人群时才成为灾害。"},{"word":"catastrophe","ipa":"/kəˈtæstrəfi/","tag":"wider and often man-made","definition":"Any ruinous end event, including wars and crashes; natural disaster is narrower because it names the cause.","definitionCN":"泛指任何毁灭性的结局事件，包括战争与撞车；natural disaster 更窄，因为它标明成因是自然。"},{"word":"calamity","ipa":"/kəˈlæməti/","tag":"older word for deep distress","definition":"An archaic-sounding word for grave misfortune, stressing suffering rather than physical mechanism.","definitionCN":"一个显得古旧的词，指严重不幸，强调苦难而非物理机制。"},{"word":"emergency","ipa":"/ɪˈmɜːdʒənsi/","tag":"the response window","definition":"A sudden situation demanding immediate action; an emergency is the period of response, not the event's cause.","definitionCN":"指需要立即行动的突发状况；它说的是响应时段，而不是事件的成因。"}]},{"heading":"NEAR MEANING","entries":[{"word":"disaster risk","ipa":"/dɪˈzɑːstə rɪsk/","tag":"probability, not event","definition":"The likelihood and scale of future loss, used in planning; it is a probability, whereas the disaster is the realised loss.","definitionCN":"指未来损失的可能性与规模，用于规划；它是概率，而灾害是已经实现的损失。"},{"word":"vulnerability","ipa":"/ˌvʌlnərəˈbɪləti/","tag":"why harm happens","definition":"The conditions that make people or property likely to be harmed; it explains why one hazard becomes a disaster.","definitionCN":"指使人或财产容易受损的条件；它解释了同一致灾因子为何会变成灾害。"},{"word":"resilience","ipa":"/rɪˈzɪliəns/","tag":"capacity to recover","definition":"The ability to absorb a shock and recover; it is the opposite side of the same ledger from disaster loss.","definitionCN":"指承受冲击并恢复的能力；它与灾害损失是同一本账的两面。"},{"word":"relief operation","ipa":"/rɪˈliːf ˌɒpəˈreɪʃn/","tag":"the response, not the cause","definition":"The organised delivery of aid after a disaster; it follows the event and does not name it.","definitionCN":"指灾后组织化的援助行动；它发生在事件之后，并不指事件本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real set phrases and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"natural carries Latin natura 'birth, course of things', from nasci 'to be born'.","cn":"natural 含拉丁 natura「出生、事物的进程」，出自 nasci「出生」。"},{"en":"disaster carries Greek astron 'star': a bad star once explained sudden ruin.","cn":"disaster 含希腊 astron「星」：凶星曾经用来解释突如其来的毁灭。"},{"en":"Fixed phrases mark the policy sense: natural disaster area, relief, risk, insurance.","cn":"固定搭配标出政策义：灾区、救助、风险、保险。"},{"en":"The contrast pair is natural hazard for the event and natural disaster for the loss.","cn":"对照组合是：natural hazard 指事件，natural disaster 指损失。"},{"en":"The adjective disastrous is the everyday relative, as in a disastrous harvest.","cn":"形容词 disastrous 是它的日常同族词，如收成极糟。"}],"abstract":[{"en":"Picture a river that keeps its level until a village is built on the floodplain.","cn":"想象一条河水位不变，直到有人在泛滥平原上建起村庄。"},{"en":"Picture a star marked in red on an old map, blamed for a broken harvest.","cn":"想象旧地图上一颗被标红的星，被指认为歉收的祸首。"},{"en":"Picture one crack in the ground growing into a chain of falling walls.","cn":"想象地面上一道裂缝，长成一串接连倒塌的墙。"}]},"examples":[{"en":"The insurance policy pays out only when the government declares a natural disaster.","cn":"只有政府宣布进入自然灾害状态，这份保单才赔付。"},{"en":"Drought is the slowest natural disaster and the hardest to photograph.","cn":"干旱是最缓慢的自然灾害，也最难拍成画面。"},{"en":"Land-use rules decide whether a coastal storm becomes a natural disaster.","cn":"土地利用规则决定一场沿海风暴是否成为自然灾害。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「natural（自然的）+ disaster（灾星降临）」——天灾星落，村毁人伤 → 自然灾害","word":"natural disaster"},"root":"natural 来自拉丁 natura「出生、事物的进程」，出自 nasci「出生」；disaster 来自希腊 astron「星」，经「凶星」观念进入拉丁与法语。两词的更深来源均不确定。英语短语 natural disaster。","sensesIntro":{"en":"Eight meanings follow one event from the physical cause to the legal label, then to the slow, compound and metaphorical uses that the phrase now covers.","cn":"八个义项沿同一事件展开：从物理成因到法律名目，再到缓慢型、复合型与隐喻用法，覆盖该短语如今所指的全部范围。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hillside gives way and a village is left half buried.","cn":"核心意象：山坡垮塌，村庄被埋掉一半。"},"chain":["NATURAL FORCE","SUDDEN HARM","EXPOSED PEOPLE","DECLARED STATUS","AID AND INSURANCE","REDUCED RISK"],"branches":[{"senses":"S1 · S2","en":"CAUSE TO LABEL: the physical event becomes an official category once funds depend on it.","cn":"从成因到名目：一旦资金取决于它，物理事件就变成官方类别。"},{"senses":"S3 · S4","en":"EXPOSURE AND TIME: loss needs someone in the way, and slow losses count as one event.","cn":"暴露与时间：损失需要有人恰在其地，缓慢累积的损失也算一次事件。"},{"senses":"S5","en":"CHAINS: one hazard can set off the next, so the phrase covers the whole cascade.","cn":"连锁：一种致灾因子能引发下一种，故短语覆盖整条连锁。"},{"senses":"S6","en":"GOVERNANCE: if harm is exposure-dependent, it can be planned down before it happens.","cn":"治理：既然损害取决于暴露，就能在发生之前通过规划削减。"},{"senses":"S7 · S8","en":"METAPHOR: any shock blamed on outside forces borrows the phrase's core claim.","cn":"隐喻：任何被归因于外部力量的冲击，都借用了该短语的核心主张。"}]},"affixes":{"intro":{"en":"The phrase is built from a Latin adjective and a Greek-derived noun, and both halves bring their own small families of English words.","cn":"这个短语由一个拉丁形容词与一个源自希腊语的名词构成，两半都带来了各自的英语词族。"},"latinIntro":{"en":"Latin natura and nasci build nature, native and innate; Greek astron passes through disaster into disastrous, while the prefix dis- marks separation.","cn":"拉丁 natura 与 nasci 构成 nature、native 与 innate；希腊 astron 经 disaster 进入 disastrous，前缀 dis- 表示分离。"},"items":[{"word":"natural","structure":"natura + -al (relating to)","meaning":"belonging to nature","meaningCN":"属于自然的","example":"The reservoir stores natural water.","exampleCN":"水库储存天然的水。"},{"word":"nature","structure":"natura (Latin noun)","meaning":"the physical world and its course","meaningCN":"自然界及其进程","example":"Nature sets the pace of the flood.","exampleCN":"自然决定洪水的节奏。"},{"word":"native","structure":"nasci + -ivus (tending to)","meaning":"born in a place","meaningCN":"本地出生的","example":"The native grass holds the soil.","exampleCN":"本地草种固定土壤。"},{"word":"innate","structure":"in- + nasci + -ate","meaning":"present from birth","meaningCN":"与生俱来的","example":"The response is innate, not learned.","exampleCN":"这种反应是与生俱来的，不是学来的。"},{"word":"disaster","structure":"dis- + astro (ill star)","meaning":"a ruinous event","meaningCN":"毁灭性事件","example":"The village never recovered from the disaster.","exampleCN":"村庄再也没能从这场灾害中恢复。"},{"word":"disastrous","structure":"disaster + -ous (full of)","meaning":"causing ruin","meaningCN":"造成毁灭的","example":"The harvest was disastrous.","exampleCN":"收成极糟。"},{"word":"-al","structure":"-alis (Latin adjective suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"natural is natura plus -al.","exampleCN":"natural 就是 natura 加 -al。"},{"word":"dis-","structure":"dis- (Latin prefix, 'apart, ill')","meaning":"apart; badly","meaningCN":"分离；不吉","example":"dis- turns aster into a bad star.","exampleCN":"dis- 把 aster 变成凶星。"}],"latinEntries":[{"word":"natura","structure":"natura, naturae (f., first declension)","meaning":"birth, nature, the course of things","meaningCN":"出生；本性；事物的进程"},{"word":"nasci","structure":"nasci, natus sum (deponent verb)","meaning":"to be born, to arise","meaningCN":"出生；产生"},{"word":"astrum","structure":"astrum, astri (n., second declension)","meaning":"star, heavenly body","meaningCN":"星；天体"},{"word":"disastrum","structure":"disastrum, disastri (n., second declension, Medieval Latin)","meaning":"ill fortune under an unlucky star","meaningCN":"凶星之下的厄运"}]}},{"word":"catastrophe","ipa_uk":"/kəˈtæstrəfi/","ipa_us":"/kəˈtæstrəfi/","definition_zh":"大灾难；毁灭性结局；悲剧的收场；彻底失败","definition_en":"a sudden, widespread and ruinous event, or the disastrous end of a process","core_image":"舞台上的幕布在一个转身之间砸落，台上所有布景一次全毁","scene":"地震后的港口只剩扭曲的吊车与倾覆的货轮，经济学家称这场连锁崩塌为大灾难。The harbour after the earthquake held only twisted cranes and a capsized freighter, a catastrophe that economists traced through every linked industry.","sceneCN":"这里 catastrophe 指「范围广、破坏彻底且带有终结意味的灾难」（第 1 个义项：造成全面毁灭的重大灾变）；句意为地震后的港口只剩扭曲吊车与倾覆货轮，经济学家称这场连锁崩塌为大灾难。可辨识物件：扭曲吊车、倾覆船体、断裂栈桥、漂浮货柜。","pos":[{"tag":"n.","zh":"大灾难；毁灭性结局（可数）"}],"collocations":[{"phrase":"a catastrophe for","zh":"对……是一场大灾难"},{"phrase":"end in catastrophe","zh":"以惨败收场"},{"phrase":"avert a catastrophe","zh":"避免一场大灾难"},{"phrase":"environmental catastrophe","zh":"环境大灾难"},{"phrase":"humanitarian catastrophe","zh":"人道主义灾难"},{"phrase":"catastrophe theory","zh":"突变理论"}],"forms":[{"label":"复数","form":"catastrophes"},{"label":"形容词（灾难性的）","form":"catastrophic（灾难性的）"},{"label":"副词（灾难性地）","form":"catastrophically（灾难性地）"},{"label":"形容词（悲剧结局的）","form":"catastrophic（结局性的）"},{"label":"相关形容词（戏剧结局的）","form":"catastrophal（结局的，罕用）"},{"label":"相关名词（灾难化思维）","form":"catastrophism（灾变论）"}],"derivatives":[{"word":"catastrophic","pos":"adj.","zh":"灾难性的；毁灭性的"},{"word":"catastrophically","pos":"adv.","zh":"灾难性地；以毁灭方式"},{"word":"catastrophism","pos":"n.","zh":"灾变论（地质学假说）"},{"word":"catastrophist","pos":"n.","zh":"灾变论者"},{"word":"catastrophize","pos":"v.","zh":"把小事想成灾难；灾难化"}],"senses":[{"no":"01","title":"A ruinous event on a wide scale","titleCN":"范围广泛的毁灭性事件","definition":"a sudden event that destroys lives, property or systems on a large scale","definitionCN":"突然发生、大规模摧毁生命、财产或体系的事件","example":"The dam failure was a catastrophe for four downstream towns.","exampleCN":"大坝失事对下游四个城镇是一场大灾难。","why":"the Greek original meant an overturning, so the word's core is a whole order turned over at once.","whyCN":"希腊原义是「翻转」，因此这个词的核心是一整套秩序被一次掀翻。"},{"no":"02","title":"The final ruin of a drama","titleCN":"戏剧的悲剧收场","definition":"the closing turn of a tragedy in which the hero's fortune is destroyed","definitionCN":"悲剧的收场转折，主人公的命运在此被彻底毁掉","example":"In the last scene the catastrophe arrives not as death but as recognition.","exampleCN":"在最后一幕，灾难性的收场不是死亡，而是认出真相。","why":"Aristotle used the word for the final change of fortune, and English drama criticism kept that technical sense.","whyCN":"亚里士多德用这个词指命运的最终转变，英语戏剧评论保留了这个专门义。"},{"no":"03","title":"A total failure of a plan","titleCN":"计划或尝试的彻底失败","definition":"an attempt or arrangement that ends in complete failure","definitionCN":"以彻底失败告终的尝试或安排","example":"The launch was a catastrophe: the rocket never left the pad.","exampleCN":"这次发射是一场彻底的失败：火箭根本没离开发射台。","why":"the ruin is no longer physical; what is overturned is the expectation built around the plan.","whyCN":"毁灭不再是物理上的，被掀翻的是围绕计划建立起来的期待。"},{"no":"04","title":"A sudden change in a system","titleCN":"系统中的突变","definition":"an abrupt, discontinuous change in a mathematical or physical system","definitionCN":"数学或物理系统中突然、不连续的变化","example":"Catastrophe theory models how a bridge's curve jumps from one shape to another.","exampleCN":"突变理论研究桥面曲线如何从一个形状跳到另一个。","why":"mathematics borrowed the overturning image for a fold in a surface where a small push causes a large jump.","whyCN":"数学借用了「翻转」意象，指曲面上某一折处：轻推一下，结果却大幅跳变。"},{"no":"05","title":"An ecological collapse","titleCN":"生态系统的崩溃","definition":"the collapse of an ecosystem past a threshold from which it cannot return","definitionCN":"生态系统越过阈值、无法回到原状的崩溃","example":"Once the reef bleached, the fishery slid toward catastrophe.","exampleCN":"珊瑚礁一旦白化，渔业便滑向崩溃。","why":"ecologists use the word for a threshold crossing because the old state really is overturned, not merely damaged.","whyCN":"生态学家用它指越过阈值，因为旧状态是真的被掀翻了，而不只是受损。"},{"no":"06","title":"A humanitarian emergency","titleCN":"人道主义危机","definition":"a crisis in which a large population loses shelter, food or medical care at once","definitionCN":"大量人口同时失去住所、食物或医疗的危机","example":"Aid agencies warned of a humanitarian catastrophe if the border stayed closed.","exampleCN":"援助机构警告，若边界持续关闭，将出现人道主义灾难。","why":"the word scales the harm to a population, which is why agencies pair it with humanitarian.","whyCN":"这个词把损害放大到一个群体，因此机构常把它与人道主义一词搭配。"},{"no":"07","title":"The catastrophic ending of a story","titleCN":"故事或局势的灾难性结局","definition":"the irreversible disastrous outcome toward which a story or situation is moving","definitionCN":"故事或局势正走向的、不可逆的灾难性结局","example":"Every negotiation that ignored the debt was heading for the same catastrophe.","exampleCN":"每一场无视债务的谈判都走向同一个灾难结局。","why":"the dramatic sense spread to ordinary narrative: a plot's final overturning can be economic or political.","whyCN":"戏剧义扩展到日常叙事：情节的最终翻转可以是经济的，也可以是政治的。"},{"no":"08","title":"Abstract: any overwhelming ruin","titleCN":"抽象义：压倒性的毁灭","definition":"a metaphorical label for any overwhelming ruin that feels final and total","definitionCN":"隐喻标签，指任何显得彻底且终结性的压倒性毁灭","example":"The review called the film a catastrophe, and the box office agreed.","exampleCN":"评论把这部电影称为一场灾难，票房也印证了这一点。","why":"the metaphor keeps only the core of total overturning, dropping every physical detail.","whyCN":"隐喻只保留「彻底翻转」这一核心，丢掉了所有物理细节。"}],"etymology":{"intro":{"en":"Catastrophe comes from Greek katastrophē 'an overturning', built on kata- 'down' and strephein 'to turn'. It entered English through Latin and French, first as a term of drama. Dates are approximate.","cn":"catastrophe 来自希腊 katastrophē「翻转」，由 kata-「向下」与 strephein「转」构成。它经拉丁语与法语进入英语，最初是戏剧术语。年代均为约数。"},"items":[{"era":"GREEK STREPHEIN","en":"Strephein meant 'to turn, twist'; its further origin is not established, so any reconstructed root is a hypothesis.","cn":"strephein 意为「转、扭」；其更远来源未得到证明，任何重构词根都只是假说。"},{"era":"GREEK KATASTROPHE","en":"Kata- 'down' plus strephein gave katastrophē, 'an overturning, a sudden end', used of a turning point in a play.","cn":"kata-「向下」加 strephein 构成 katastrophē「翻转、突然的终结」，用于指戏剧中的转折。"},{"era":"LATIN CATASTROPHA","en":"Latin took the word as catastrophа, keeping the dramatic sense of a final reversal of fortune.","cn":"拉丁语借作 catastrophа，保留了「命运最终逆转」的戏剧义。"},{"era":"FRENCH AND ENGLISH","en":"French catastrophe reached English in the sixteenth century as a stage term, then widened to any great disaster by the eighteenth.","cn":"法语 catastrophe 于 16 世纪进入英语，先作舞台术语，到 18 世纪扩展到泛指一切大灾难。"},{"era":"MODERN SCIENCES","en":"Geology used catastrophe for sudden global change in the debate over catastrophism, and mathematics later named catastrophe theory after the same image.","cn":"地质学在灾变论之争中用 catastrophe 指突然的全球变化，数学后来的突变理论也沿用同一意象。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Greek history of strephein is unsettled, and the exact date when the general 'disaster' sense displaced the stage sense is unknown.","cn":"来源不确定（更深词源）：strephein 在希腊语之前的历史未定，泛指「灾难」的义项取代舞台义的确切年代亦不可考。"}]},"similar":{"note":{"en":"Group one holds ruin words that differ in reach and cause; group two holds words for the human response or the study of such events.","cn":"第一组是范围与成因不同的毁灭类词；第二组指人的应对反应或对此类事件的研究。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"disaster","ipa":"/dɪˈzɑːstə/","tag":"blames a bad star","definition":"From Greek astron through 'ill star': a disaster may be local, and its cause may be human or natural, so it is wider in origin but often smaller in scale.","definitionCN":"经「凶星」来自希腊 astron：disaster 可大可小，成因可人为可自然，因此来源更宽而规模常更小。"},{"word":"calamity","ipa":"/kəˈlæməti/","tag":"suffering, not overturning","definition":"From Latin calamitas 'loss, damage': it stresses the distress people feel rather than a whole order overturned.","definitionCN":"来自拉丁 calamitas「损失、损害」：强调人们承受的苦难，而非整套秩序的翻转。"},{"word":"cataclysm","ipa":"/ˈkætəklɪzəm/","tag":"flood image","definition":"Greek kataklysmos 'a deluge': it stresses an overwhelming physical rush, especially water or upheaval.","definitionCN":"希腊 kataklysmos「洪水」：强调压倒性的物理冲击，尤其是水或地壳剧变。"},{"word":"debacle","ipa":"/dɪˈbɑːkl/","tag":"a rout, often political","definition":"From French débâcle, a breaking up of ice in a river: a spectacular collapse or rout, usually of a plan or an army.","definitionCN":"来自法语 débâcle「河中冰层崩解」：指壮观的崩溃或溃败，多用于计划或军队。"}]},{"heading":"NEAR MEANING","entries":[{"word":"tragedy","ipa":"/ˈtrædʒədi/","tag":"the dramatic frame","definition":"A serious drama with a sorrowful end; as a general noun it stresses grief and pity, while catastrophe stresses the ruin itself.","definitionCN":"以悲伤结局收场的严肃戏剧；作一般名词时强调悲痛与怜悯，而 catastrophe 强调毁灭本身。"},{"word":"crisis","ipa":"/ˈkraɪsɪs/","tag":"the turning point","definition":"From Greek krisis 'decision': the decisive moment that may end well or badly, so it precedes the catastrophe rather than naming it.","definitionCN":"来自希腊 krisis「决断」：可能好也可能坏的决胜时刻，因此在灾难之前，而不是灾难本身。"},{"word":"emergency","ipa":"/ɪˈmɜːdʒənsi/","tag":"the response window","definition":"A sudden situation calling for immediate action; it names the period of response, not the scale of the ruin.","definitionCN":"指需要立即行动的突发状况；它指响应时段，而非毁灭的规模。"},{"word":"catastrophism","ipa":"/kəˈtæstrəfɪzəm/","tag":"the theory, not the event","definition":"The geological view that Earth's history was shaped by sudden global upheavals; it is a doctrine about catastrophes, not one itself.","definitionCN":"地质学观点，认为地球历史由突然的全球剧变塑造；它是关于灾变的学说，本身不是灾变。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real set phrases and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"kata- means down and strephein means turn, so catastrophe is a turning down, an overturning.","cn":"kata- 表示「向下」，strephein 表示「转」，catastrophe 就是「向下翻转」，即倾覆。"},{"en":"The stage sense came first: the catastrophe is the final reversal of a tragedy.","cn":"舞台义最先出现：catastrophe 是悲剧中命运的最终逆转。"},{"en":"The adjective is catastrophic, as in catastrophic flooding or a catastrophic failure.","cn":"形容词是 catastrophic，如灾难性洪水或灾难性故障。"},{"en":"Fixed phrases mark the scale: environmental catastrophe, humanitarian catastrophe.","cn":"固定搭配标出规模：环境大灾难、人道主义灾难。"},{"en":"Geology and mathematics keep technical uses: catastrophism and catastrophe theory.","cn":"地质学与数学保留专业用法：灾变论与突变理论。"}],"abstract":[{"en":"Picture a stage curtain falling in the middle of the play and taking the set with it.","cn":"想象幕布在戏演到一半时落下，把布景一起带倒。"},{"en":"Picture a sheet of ice on a river breaking all at once with a sound like a shot.","cn":"想象河面冰层轰然一次崩裂，响声如同枪响。"},{"en":"Picture a folded map where one crease, once pressed, flips the whole sheet.","cn":"想象一张折过的地图，按下其中一道折痕，整张纸便翻面。"}]},"examples":[{"en":"The failure of the levee was a catastrophe that reshaped the city for a generation.","cn":"堤坝失事是一场大灾难，重塑了这座城市整整一代人。"},{"en":"Ignoring the early warnings turned a manageable flood into a catastrophe.","cn":"无视早期预警，把一场可控的洪水变成了大灾难。"},{"en":"In the final act the catastrophe is a recognition, not a death.","cn":"在最后一幕，悲剧的收场是一次认出，而非一死。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「cat（猫）+ astro（星）+ phe」——猫盯着灾星，一次翻身全毁 → 大灾难","word":"catastrophe"},"root":"希腊 katastrophē「翻转」= kata-「向下」+ strephein「转」，经拉丁 catastrophа 与法语进入英语；strephein 的更深来源不确定。英语 catastrophe。","sensesIntro":{"en":"Eight meanings follow one overturning: first a whole order destroyed, then the stage reversal, then any plan or system that flips, and finally the metaphor for total ruin.","cn":"八个义项沿同一次「翻转」展开：先是整套秩序被毁，再是舞台上的逆转，接着是计划或系统的翻转，最后是对彻底毁灭的隐喻。"},"semanticMap":{"core":{"en":"CORE IMAGE: a whole set is overturned in a single movement.","cn":"核心意象：整套布景在一次动作中被掀翻。"},"chain":["TURN DOWN","WHOLE ORDER","FINAL REVERSAL","PLAN COLLAPSE","SYSTEM JUMP","TOTAL RUIN"],"branches":[{"senses":"S1 · S6","en":"SCALE OF HARM: the overturning is measured by how many lives and systems go down with it.","cn":"损害规模：翻转的轻重，取决于多少生命与体系随之倒下。"},{"senses":"S2 · S7","en":"DRAMATIC ARC: the stage reversal and the story's ending share one final turn.","cn":"戏剧弧线：舞台逆转与故事结局共用同一次最终转折。"},{"senses":"S3","en":"PLAN FAILURE: nothing physical breaks, but the expectation is overturned.","cn":"计划失败：没有实物破碎，被掀翻的是期待。"},{"senses":"S4 · S5","en":"SYSTEM THRESHOLD: mathematics and ecology both describe a small push that flips a state.","cn":"系统阈值：数学与生态学都描述「轻推一下、状态翻面」。"},{"senses":"S8","en":"METAPHOR: only the claim of total finality survives when the word is used loosely.","cn":"隐喻：宽泛使用这个词时，只剩「彻底且终结」这一主张。"}]},"affixes":{"intro":{"en":"Catastrophe is a Greek compound whose two parts also build a small family of English technical words, so it can be read morpheme by morpheme.","cn":"catastrophe 是一个希腊复合词，两部分还构成一小族英语技术词，因此可以按语素逐个读出。"},"latinIntro":{"en":"The Greek prefix kata- appears in cataclysm and catalog; the root strephein appears in strophe and in the technical adjective catastrophic.","cn":"希腊前缀 kata- 出现在 cataclysm 与 catalog 中；词根 strephein 出现在 strophe 与形容词 catastrophic 中。"},"items":[{"word":"kata-","structure":"kata- (Greek prefix, 'down, against')","meaning":"down; against","meaningCN":"向下；反对","example":"The prefix turns the movement downward.","exampleCN":"这个前缀把动作转向下方。"},{"word":"strophe","structure":"strophē (Greek noun, 'a turn')","meaning":"a turn, a stanza","meaningCN":"转折；诗节","example":"The chorus sang the strophe.","exampleCN":"合唱队唱了那一节。"},{"word":"catastrophe","structure":"kata- + strophe","meaning":"an overturning","meaningCN":"翻转；倾覆","example":"The flood was a catastrophe.","exampleCN":"那场洪水是一场大灾难。"},{"word":"catastrophic","structure":"catastrophe + -ic (relating to)","meaning":"of the nature of ruin","meaningCN":"具毁灭性质的","example":"The failure was catastrophic.","exampleCN":"这次故障是灾难性的。"},{"word":"cataclysm","structure":"kata- + klyzein (to wash)","meaning":"a deluge, an upheaval","meaningCN":"洪水；剧变","example":"The cataclysm reshaped the coast.","exampleCN":"那场剧变重塑了海岸。"},{"word":"apostrophe","structure":"apo- + strephein","meaning":"a turning away to address someone","meaningCN":"转开身去呼告","example":"The poem opens with an apostrophe to the night.","exampleCN":"这首诗以对夜的呼告开篇。"},{"word":"catastrophism","structure":"catastrophe + -ism (doctrine)","meaning":"the doctrine of sudden global change","meaningCN":"灾变论","example":"Catastrophism once rivalled uniformitarianism.","exampleCN":"灾变论曾与均变论相抗衡。"},{"word":"catastrophize","structure":"catastrophe + -ize (make)","meaning":"to treat a small trouble as ruin","meaningCN":"把小事灾难化","example":"She tends to catastrophize a single mistake.","exampleCN":"她容易把一次错误想成灾难。"}],"latinEntries":[{"word":"catastrophа","structure":"catastrophа, catastrophae (f., first declension, Latinized Greek)","meaning":"an overturning; the final turn of a play","meaningCN":"翻转；戏剧的最终转折"},{"word":"strophe","structure":"strophē, strophēs (f., first declension, Greek)","meaning":"a turn, a stanza sung while turning","meaningCN":"转折；转身时唱的诗节"}]}},{"word":"catastrophic","ipa_uk":"/ˌkætəˈstrɒfɪk/","ipa_us":"/ˌkætəˈstrɑːfɪk/","definition_zh":"灾难性的；毁灭性的；造成彻底失败的","definition_en":"causing or involving ruin on a very large scale","core_image":"一排多米诺骨牌从第一张开始连锁倒下，最后一张砸穿了地板","scene":"洪水退去后，粮仓只剩空架，农会估计损失足以让全镇破产，形容为灾难性后果。When the floodwater withdrew, only the empty frame of the granary remained, and the farm board called the losses catastrophic enough to bankrupt the whole town.","sceneCN":"这里 catastrophic 指「造成大范围、近乎不可挽回的破坏」（第 1 个义项：后果具毁灭性）；句意为洪水退去后粮仓只剩空架，农会称损失之大足以让全镇破产。可辨识物件：空粮仓骨架、倒伏的骨牌、泡水的账册、破堤口。","pos":[{"tag":"adj.","zh":"灾难性的；毁灭性的（多作定语，也可作表语）"}],"collocations":[{"phrase":"catastrophic failure","zh":"灾难性故障；彻底失败"},{"phrase":"catastrophic flooding","zh":"灾难性洪水"},{"phrase":"catastrophic consequences","zh":"灾难性后果"},{"phrase":"catastrophic loss","zh":"灾难性损失"},{"phrase":"catastrophic illness","zh":"重大疾病（保险术语）"},{"phrase":"catastrophic event","zh":"灾难性事件"}],"forms":[{"label":"原级","form":"catastrophic"},{"label":"比较级","form":"more catastrophic"},{"label":"最高级","form":"most catastrophic"},{"label":"副词（灾难性地）","form":"catastrophically（灾难性地）"},{"label":"名词（大灾难）","form":"catastrophe（大灾难）"},{"label":"名词（灾变论）","form":"catastrophism（灾变论）"}],"derivatives":[{"word":"catastrophe","pos":"n.","zh":"大灾难；毁灭性结局"},{"word":"catastrophically","pos":"adv.","zh":"灾难性地"},{"word":"catastrophism","pos":"n.","zh":"灾变论"},{"word":"catastrophist","pos":"n.","zh":"灾变论者"},{"word":"catastrophize","pos":"v.","zh":"把小事灾难化"}],"senses":[{"no":"01","title":"Causing ruin on a large scale","titleCN":"造成大范围毁灭","definition":"causing destruction that is widespread and hard to reverse","definitionCN":"造成广泛且难以逆转的破坏","example":"The storm surge had a catastrophic effect on the low-lying districts.","exampleCN":"风暴潮对低洼城区造成了灾难性影响。","why":"the adjective simply carries the noun's overturning into a modifier: whatever it touches is turned over.","whyCN":"这个形容词只是把名词的「翻转」带进修饰位置：它触到的东西都被掀翻。"},{"no":"02","title":"Disastrous as an outcome","titleCN":"结果上的彻底失败","definition":"ending in complete and damaging failure","definitionCN":"以彻底且有害的失败告终","example":"The decision to ignore the engineers proved catastrophic.","exampleCN":"无视工程师意见的决定被证明是灾难性的。","why":"nothing physical is destroyed here; what collapses is the plan and the trust behind it.","whyCN":"这里没有实物被毁，崩塌的是计划以及支撑计划的信任。"},{"no":"03","title":"Involving enormous financial loss","titleCN":"涉及巨额财务损失","definition":"producing losses so large that they threaten the survival of the organisation","definitionCN":"造成的损失之大，危及组织本身的存续","example":"Insurers class a single storm as catastrophic once claims pass a fixed threshold.","exampleCN":"一旦赔款超过固定门槛，保险公司就把单场风暴列为灾难性事件。","why":"the insurance industry turned the adjective into a threshold label for losses that break a balance sheet.","whyCN":"保险业把这个形容词变成门槛标签，专指足以击穿资产负债表的损失。"},{"no":"04","title":"Of a drama's final reversal","titleCN":"戏剧最终逆转的","definition":"belonging to the closing reversal in which a tragedy's fortunes are destroyed","definitionCN":"属于悲剧命运被彻底毁掉的收场转折","example":"The playwright keeps the catastrophic scene off stage and reports it in a messenger's speech.","exampleCN":"剧作家把这一灾难性的场面留在幕后，由传信人的台词转述。","why":"drama criticism kept the technical sense, using the adjective for the moment when the reversal lands.","whyCN":"戏剧评论保留了这一专门义，用该形容词指逆转落地的那一刻。"},{"no":"05","title":"Of a sudden geological upheaval","titleCN":"地质突变的","definition":"describing a sudden worldwide change in the earth's crust or climate","definitionCN":"描述地壳或气候的突然全球性变化","example":"Catastrophic eruptions can cool the whole planet for a year.","exampleCN":"灾难性的火山喷发能让整个行星降温一年。","why":"geology needed a word for change by sudden event rather than slow accumulation, and borrowed this one.","whyCN":"地质学需要一个词指「由突发事件造成的变化」而非缓慢累积，于是借用了它。"},{"no":"06","title":"Severe and irreversible in medicine","titleCN":"医学上严重且不可逆的","definition":"describing an illness or injury that is severe, sudden and permanently damaging","definitionCN":"描述严重、突发且造成永久损害的疾病或损伤","example":"The policy covers catastrophic illness but not routine care.","exampleCN":"这份保单覆盖重大疾病，但不含日常诊疗。","why":"medicine borrowed the financial threshold label: the illness is catastrophic because of its cost and permanence, not its cause.","whyCN":"医学借用了财务门槛标签：疾病之所以「灾难性」，在于费用与不可逆，而非成因。"},{"no":"07","title":"Of an abrupt jump in a system","titleCN":"系统突然跳变的","definition":"describing a discontinuous change in which a small shift produces a large jump","definitionCN":"描述一种不连续变化：微小移动带来巨大跳变","example":"The model predicts a catastrophic jump once the load passes the fold point.","exampleCN":"模型预测，一旦荷载越过折点，就会出现灾难性跳变。","why":"catastrophe theory used the word for the fold in a surface, so the adjective marks the jump itself.","whyCN":"突变理论用这个词指曲面上的折处，因此形容词标记的是跳变本身。"},{"no":"08","title":"Abstract: overwhelmingly harmful","titleCN":"抽象义：极其有害","definition":"used loosely for anything felt to be overwhelmingly harmful or badly judged","definitionCN":"宽泛地用于任何被认为极其有害或判断极糟的事物","example":"Calling the merger catastrophic was an exaggeration, but the lost jobs were real.","exampleCN":"把这次合并称为灾难性有些夸张，但失去的工作岗位是真的。","why":"the loose use keeps only the intensity of the original: something is judged as if it had been overturned.","whyCN":"宽泛用法只保留原词的强度：某事物被判定得仿佛被掀翻过一样。"}],"etymology":{"intro":{"en":"Catastrophic is the adjective of catastrophe, the Greek katastrophē 'overturning', plus the Greek adjectival ending -ikos. It reached English through Latin and French. Dates are approximate.","cn":"catastrophic 是大灾难 catastrophe 的形容词，由希腊 katastrophē「翻转」加希腊形容词词尾 -ikos 构成，经拉丁语与法语进入英语。年代均为约数。"},"items":[{"era":"GREEK KATASTROPHE","en":"Katastrophē 'an overturning' came from kata- 'down' plus strephein 'to turn'; the deeper origin of strephein is not established.","cn":"katastrophē「翻转」由 kata-「向下」加 strephein「转」构成；strephein 的更远来源未得到证明。"},{"era":"GREEK -IKOS","en":"-ikos was the ordinary Greek ending for 'belonging to, of the nature of', so katastrophikos meant 'of an overturning'.","cn":"-ikos 是希腊语中表示「属于、具有……性质」的常用词尾，因此 katastrophikos 意为「翻转性质的」。"},{"era":"LATIN -ICUS","en":"Latin -icus and French -ique carried the ending into English -ic, which by the seventeenth century attached freely to nouns of Greek origin.","cn":"拉丁 -icus 与法语 -ique 把这个词尾带入英语 -ic，到 17 世纪它已能自由附着于希腊来源的名词。"},{"era":"ENGLISH ADJECTIVE","en":"Catastrophic appears in English drama criticism before it spreads to ordinary description of floods, wars and failures.","cn":"catastrophic 先出现在英语戏剧评论中，之后才扩展到对洪水、战争与失败的日常描述。"},{"era":"MODERN LABELS","en":"Insurance fixed catastrophic loss as a threshold term, and medicine followed with catastrophic illness; geology used it in the catastrophism debate.","cn":"保险业把 catastrophic loss 定为门槛术语，医学随后有 catastrophic illness；地质学在灾变论之争中也使用了它。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Greek history of strephein is unsettled, and no exact first citation is recorded for the insurance sense, so the dates given are approximations.","cn":"来源不确定（更深词源）：strephein 在希腊语之前的历史未定，保险义也没有确切的最早书证，所给年代均为约数。"}]},"similar":{"note":{"en":"Group one holds adjectives that differ in what they blame or how final the harm is; group two holds the nouns and adverbs that share the same root.","cn":"第一组是归因或终结程度不同的形容词；第二组是同根的名词与副词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"cataclysmic","ipa":"/ˌkætəˈklɪzmɪk/","tag":"deluge image","definition":"Built on Greek klyzein 'to wash', so it stresses a flood-like physical rush rather than a whole order overturned.","definitionCN":"由希腊 klyzein「冲洗」构成，强调洪水般的物理冲击，而非整套秩序被翻转。"},{"word":"apocalyptic","ipa":"/ˌæpəˈkælɪptɪk/","tag":"end-of-the-world frame","definition":"From Greek apokalypsis 'unveiling': it borrows the imagery of a final world-ending revelation, a much larger claim.","definitionCN":"来自希腊 apokalypsis「揭开」：借用世界终结式启示的意象，语气比 catastrophic 大得多。"},{"word":"catastrophal","ipa":"/kəˈtæstrəfəl/","tag":"rare synonym","definition":"A rare adjective built directly on catastrophe with -al; it exists but is far less common than catastrophic.","definitionCN":"直接由 catastrophe 加 -al 构成的罕用形容词，存在但远不如 catastrophic 常用。"},{"word":"fatal","ipa":"/ˈfeɪtl/","tag":"death, not scale","definition":"From Latin fatum 'fate': it means causing death or doom, and says nothing about the size of the loss.","definitionCN":"来自拉丁 fatum「命运」：指致死或注定失败，不涉及损失规模。"}]},{"heading":"NEAR MEANING","entries":[{"word":"disastrous","ipa":"/dɪˈzɑːstrəs/","tag":"everyday intensity","definition":"The plainer adjective from disaster; it can describe a merely bad dinner, which catastrophic rarely does.","definitionCN":"由 disaster 来的更日常的形容词，可以形容一顿很糟的晚餐，而 catastrophic 很少这样用。"},{"word":"devastating","ipa":"/ˈdevəsteɪtɪŋ/","tag":"emotional and physical","definition":"From Latin devastare 'to lay waste': it stresses the sweeping destruction of an area or a person's feelings.","definitionCN":"来自拉丁 devastare「荒废」：强调对地区或人的情感造成的横扫式破坏。"},{"word":"ruinous","ipa":"/ˈruːɪnəs/","tag":"financial ruin","definition":"From Latin ruina 'a falling down': it points at collapse, especially of finances, and is more formal and literary.","definitionCN":"来自拉丁 ruina「倒塌」：指向崩塌，尤指财务，语气更正式、更书面。"},{"word":"calamitous","ipa":"/kəˈlæmɪtəs/","tag":"suffering tone","definition":"From Latin calamitas 'loss': it emphasises the distress borne by people rather than the mechanism of the disaster.","definitionCN":"来自拉丁 calamitas「损失」：强调人们承受的苦难，而非灾害的机制。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real set phrases and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The base is catastrophe, a turning down; -ic makes it an adjective of that overturning.","cn":"词基是 catastrophe「向下翻转」，-ic 使其成为表示该翻转的形容词。"},{"en":"The -ic ending is the same one in dramatic, poetic and historic.","cn":"这里的 -ic 与 dramatic、poetic、historic 中的 -ic 相同。"},{"en":"Fixed phrases mark the professional uses: catastrophic failure, catastrophic illness, catastrophic loss.","cn":"固定搭配标出专业用法：灾难性故障、重大疾病、灾难性损失。"},{"en":"The adverb is catastrophically, as in catastrophically wrong.","cn":"副词是 catastrophically，如错得灾难性地。"},{"en":"Geology pairs it with catastrophism, the doctrine of sudden upheaval.","cn":"地质学把它与灾变论配对，后者主张突然剧变。"}],"abstract":[{"en":"Picture a row of dominoes where the first tile is no bigger than a coin.","cn":"想象一排多米诺骨牌，第一张不过硬币大小。"},{"en":"Picture a bank statement where one line wipes out every column.","cn":"想象一张银行对账单，其中一行抹掉了所有栏目。"},{"en":"Picture a small crack that lets a whole reservoir through a wall.","cn":"想象一道小裂缝，让整座水库穿墙而过。"}]},"examples":[{"en":"A single missed inspection can be catastrophic for a dam.","cn":"一次漏检对一座大坝可能是灾难性的。"},{"en":"The company called the recall catastrophic but kept its factories open.","cn":"公司称这次召回是灾难性的，却仍让工厂开工。"},{"en":"Catastrophic eruptions are rare, which is why their traces are so clear.","cn":"灾难性的火山喷发很罕见，正因此留下的痕迹格外清晰。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「cat（猫）+ astro（星）+ phic」——灾星压顶，连锁全毁 → 灾难性的","word":"catastrophic"},"root":"希腊 katastrophē「翻转」（kata- 向下 + strephein 转）加希腊形容词词尾 -ikos，经拉丁 -icus 与法语 -ique 进入英语 -ic；strephein 更深来源不确定。英语 catastrophic。","sensesIntro":{"en":"Eight meanings follow one adjective: ruin by physical force, ruin by failed planning, ruin by cost, then the stage reversal, the sudden earth change, the medical threshold, the mathematical jump and finally ordinary exaggeration.","cn":"八个义项沿同一个形容词展开：物理力量的毁灭、谋划失败造成的毁灭、代价造成的毁灭，再到舞台逆转、地球突变、医学门槛、数学跳变，最后是日常的夸张用法。"},"semanticMap":{"core":{"en":"CORE IMAGE: one touch sends a whole row down and breaks the floor.","cn":"核心意象：轻轻一触，整排倒下，地板被砸穿。"},"chain":["OVERTURNED","SPREADING","IRREVERSIBLE","THRESHOLD","FINAL TURN","EXAGGERATION"],"branches":[{"senses":"S1 · S3","en":"SCALE AND COST: physical ruin and financial ruin are both measured by how much cannot be recovered.","cn":"规模与代价：物理毁灭与财务毁灭，都以「有多少无法挽回」来衡量。"},{"senses":"S2 · S8","en":"JUDGEMENT: when nothing physical breaks, the word becomes a verdict on a decision.","cn":"评判：没有实物破碎时，这个词就成了对某项决定的判词。"},{"senses":"S4 · S7","en":"FINAL JUMPS: the drama's last reversal and the model's fold are both irreversible jumps.","cn":"终结性跳变：戏剧的最后逆转与模型的折点，都是不可逆的跳变。"},{"senses":"S5","en":"EARTH SCALE: geology applies the adjective to change that arrives as an event, not a trend.","cn":"地球尺度：地质学把这个形容词用于「以事件形式到来」而非趋势性的变化。"},{"senses":"S6","en":"MEDICAL THRESHOLD: an illness becomes catastrophic when cost and permanence cross a line.","cn":"医学门槛：当费用与不可逆性越线，疾病便成为「灾难性」的。"}]},"affixes":{"intro":{"en":"The word is transparent: a Greek-derived noun plus the Greek-Latin adjective ending -ic, and both parts recur across English.","cn":"这个词很透明：一个源自希腊语的名词加希腊—拉丁形容词词尾 -ic，两部分在英语中都反复出现。"},"latinIntro":{"en":"Greek strophe and the prefix kata- build catastrophe and cataclysm; Latin -icus gives the English ending -ic, as in historic and dramatic.","cn":"希腊 strophe 与前缀 kata- 构成 catastrophe 与 cataclysm；拉丁 -icus 给出英语词尾 -ic，如 historic 与 dramatic。"},"items":[{"word":"catastrophe","structure":"kata- + strophe","meaning":"an overturning","meaningCN":"翻转；倾覆","example":"The flood was a catastrophe.","exampleCN":"那场洪水是一场大灾难。"},{"word":"-ic","structure":"-ikos (Greek) through -icus (Latin)","meaning":"of the nature of","meaningCN":"具有……性质的","example":"catastrophic is catastrophe plus -ic.","exampleCN":"catastrophic 就是 catastrophe 加 -ic。"},{"word":"catastrophically","structure":"catastrophic + -ally (adverb)","meaning":"in a ruinous way","meaningCN":"以毁灭性的方式","example":"The plan failed catastrophically.","exampleCN":"计划灾难性地失败了。"},{"word":"catastrophism","structure":"catastrophe + -ism (doctrine)","meaning":"the doctrine of sudden upheaval","meaningCN":"灾变论","example":"Catastrophism explained the fossils as flood deposits.","exampleCN":"灾变论把化石解释为洪水沉积。"},{"word":"catastrophist","structure":"catastrophism + -ist (person)","meaning":"a supporter of that doctrine","meaningCN":"灾变论者","example":"The catastrophist argued for a sudden flood.","exampleCN":"这位灾变论者主张发生过一场突发洪水。"},{"word":"catastrophize","structure":"catastrophe + -ize (make, treat as)","meaning":"to treat a small trouble as ruin","meaningCN":"把小事灾难化","example":"Do not catastrophize one bad result.","exampleCN":"不要把一次糟糕的结果灾难化。"},{"word":"cataclysm","structure":"kata- + klyzein (to wash)","meaning":"a deluge or upheaval","meaningCN":"洪水；剧变","example":"The cataclysm left a layer of silt.","exampleCN":"那场剧变留下一层淤泥。"},{"word":"strophe","structure":"strophē (Greek, 'a turn')","meaning":"a stanza","meaningCN":"诗节","example":"The ode has three strophes.","exampleCN":"这首颂诗有三节。"}],"latinEntries":[{"word":"catastrophа","structure":"catastrophа, catastrophae (f., first declension, Latinized Greek)","meaning":"an overturning; the final turn of a play","meaningCN":"翻转；戏剧的最终转折"},{"word":"catastrophicus","structure":"catastrophicus, catastrophica, catastrophicum (adj., Medieval Latin)","meaning":"of an overturning, ruinous","meaningCN":"翻转性质的；毁灭性的"}]}},{"word":"mitigation","ipa_uk":"/ˌmɪtɪˈɡeɪʃn/","ipa_us":"/ˌmɪtɪˈɡeɪʃn/","definition_zh":"缓解；减轻；减灾措施；（法律上）减轻情节或刑罚","definition_en":"the act of making something harmful, severe or painful less severe","core_image":"堤外洪水拍岸，堤内新植的红树林把浪一排排削平","scene":"沿海城镇在河口种下红树林，用层层植被削弱风暴潮的冲力，这类减灾工程被写进规划。The coastal town planted mangroves at the river mouth so that layer upon layer of vegetation would break the storm surge, and such mitigation works were written into the plan.","sceneCN":"这里 mitigation 指「削减灾害或风险的强度与后果」（第 1 个义项：使危害程度变轻）；句意为沿海城镇在河口种红树林，用层层植被削弱风暴潮，这类减灾工程被写进规划。可辨识物件：红树林带、拍岸浪、堤顶标志、规划图纸。","pos":[{"tag":"n.","zh":"缓解；减轻；减灾措施（不可数，指具体措施时可用复数）"}],"collocations":[{"phrase":"climate change mitigation","zh":"减缓气候变化"},{"phrase":"mitigation measures","zh":"缓解措施；减灾措施"},{"phrase":"mitigation strategy","zh":"缓解策略"},{"phrase":"risk mitigation","zh":"风险缓解"},{"phrase":"mitigation of damage","zh":"损害减轻"},{"phrase":"in mitigation","zh":"作为减轻情节（法律用语）"}],"forms":[{"label":"动词（缓解）","form":"mitigate（缓解；减轻）"},{"label":"三单（he/she/it）","form":"mitigates"},{"label":"过去式","form":"mitigated"},{"label":"过去分词","form":"mitigated"},{"label":"现在分词","form":"mitigating"},{"label":"形容词（可减轻的）","form":"mitigable（可缓解的）"}],"derivatives":[{"word":"mitigate","pos":"v.","zh":"缓解；减轻"},{"word":"mitigating","pos":"adj.","zh":"减轻的；可减轻罪责的"},{"word":"mitigator","pos":"n.","zh":"缓解者；缓解手段"},{"word":"unmitigated","pos":"adj.","zh":"未减轻的；十足的（多含贬义）"},{"word":"mitigable","pos":"adj.","zh":"可缓解的"}],"senses":[{"no":"01","title":"Making a harm less severe","titleCN":"使危害程度变轻","definition":"the act of reducing the severity, seriousness or painfulness of something","definitionCN":"降低某事物的严重性、严重程度或痛苦程度的行为","example":"Draining the field was a simple mitigation of the flood risk.","exampleCN":"给田地排水是对洪水风险的一种简单缓解。","why":"the Latin verb meant to soften, so mitigation is literally a softening of the blow.","whyCN":"拉丁动词本义是「使变软」，因此 mitigation 字面上就是把打击变软。"},{"no":"02","title":"Disaster risk reduction works","titleCN":"降低灾害风险的工程与措施","definition":"structural or planning measures that reduce the impact of a hazard before it strikes","definitionCN":"在致灾因子袭来之前削减其影响的结构性或规划性措施","example":"The levee and the wetland together count as mitigation under the grant.","exampleCN":"堤坝与湿地合起来才算作这笔拨款下的减灾措施。","why":"emergency management split the field in two, assigning mitigation to prevention and response to rescue.","whyCN":"应急管理把这一领域一分为二：减灾归预防，救援归响应。"},{"no":"03","title":"Reducing a legal penalty","titleCN":"法律上减轻罪责或刑罚","definition":"the lessening of a punishment or liability because of circumstances that excuse or soften the offence","definitionCN":"因情有可原或使过错变轻的情节而减轻刑罚或责任","example":"Her cooperation with the inquiry was offered in mitigation.","exampleCN":"她配合调查的情节被提出作为减刑理由。","why":"courts borrowed the everyday verb and made it a formal heading for reasons that soften a sentence.","whyCN":"法庭借用了日常动词，把它变成使量刑变轻的正式理由名目。"},{"no":"04","title":"Palliative care of symptoms","titleCN":"医学上的对症缓解","definition":"treatment that eases symptoms without curing the underlying disease","definitionCN":"减轻症状而不治愈根本疾病的治疗","example":"The team focused on mitigation of pain rather than on a cure.","exampleCN":"团队专注于缓解疼痛，而非治愈。","why":"medicine uses the word where cure is impossible, so the aim narrows to softening what the patient feels.","whyCN":"医学在无法治愈时使用这个词，目标因此收窄为减轻患者的感受。"},{"no":"05","title":"Mediation between parties","titleCN":"冲突中的调解与缓和","definition":"the reduction of conflict between people or groups through negotiation","definitionCN":"通过谈判削减人或群体之间的冲突","example":"The envoy's mitigation of the border dispute kept the talks alive.","exampleCN":"特使对边境争端的缓和使谈判得以延续。","why":"the metaphor treats conflict as a force that can be softened rather than defeated.","whyCN":"这个隐喻把冲突视为一种可以被软化、而非被击败的力量。"},{"no":"06","title":"Environmental offset measures","titleCN":"环境影响的补偿与减缓措施","definition":"measures required to reduce or offset the environmental damage of a project","definitionCN":"为削减或补偿项目造成的环境损害而要求采取的措施","example":"The permit lists wetland creation as mitigation for the lost marsh.","exampleCN":"许可证把新建湿地列为对消失沼泽的减缓措施。","why":"planning law made mitigation a condition of approval, so the word became a line item in permits.","whyCN":"规划法把 mitigation 变成批准的附加条件，于是它成了许可证上的一项条目。"},{"no":"07","title":"Cutting greenhouse gas emissions","titleCN":"削减温室气体排放","definition":"policies that reduce the sources of climate change rather than adapt to its effects","definitionCN":"削减气候变化源头、而非适应其影响的相关政策","example":"Climate mitigation and adaptation are budgeted separately.","exampleCN":"气候减缓与气候适应分开编列预算。","why":"climate policy needed a word for cutting causes, and adaptation already named coping with effects.","whyCN":"气候政策需要一个词指「削减成因」，因为 adaptation 已用于指「应对影响」。"},{"no":"08","title":"Abstract: softening a statement or blow","titleCN":"抽象义：缓和言辞或冲击","definition":"the act of making a statement, criticism or shock less harsh","definitionCN":"使陈述、批评或冲击不那么尖锐的行为","example":"A short apology served as mitigation for the blunt report.","exampleCN":"一句简短的道歉缓和了那份直白报告带来的冲击。","why":"the abstract use generalises the physical softening to words and feelings.","whyCN":"抽象用法把物理上的「变软」推广到言辞与感受。"}],"etymology":{"intro":{"en":"Mitigation comes from Latin mitigare 'to soften, make mild', built on mitis 'soft, mild' plus an element whose origin is disputed. It entered English through French. Dates are approximate.","cn":"mitigation 来自拉丁 mitigare「使变软、使温和」，由 mitis「柔软、温和」加一个来源有争议的成分构成，经法语进入英语。年代均为约数。"},"items":[{"era":"LATIN MITIS","en":"Mitis meant 'soft, ripe, mild', used of fruit, weather and temper; its own deeper origin is not established.","cn":"mitis 意为「柔软、成熟、温和」，用于水果、天气与性情；其更远来源未得到证明。"},{"era":"LATIN MITIGARE","en":"Mitis plus the element -igare formed mitigare 'to soften, to make gentle'; the -ig- part is of uncertain origin, and a link to agere is only a suggestion.","cn":"mitis 加 -igare 构成 mitigare「使变软、使温和」；-ig- 部分来源不确定，与 agere 的联系仅是一种推测。"},{"era":"FRENCH MITIGATION","en":"Old French mitigation carried the noun into English in the fourteenth century, first as a general softening of pain or severity.","cn":"古法语 mitigation 于 14 世纪把该名词带入英语，最初泛指对痛苦或严厉程度的缓和。"},{"era":"LEGAL SENSE","en":"By the seventeenth century English courts used 'in mitigation' for circumstances that lighten a sentence or a charge.","cn":"到 17 世纪，英格兰法庭用 in mitigation 指使量刑或指控变轻的情节。"},{"era":"RISK AND CLIMATE","en":"Twentieth-century emergency management made mitigation the prevention half of the field, and climate policy later split mitigation of causes from adaptation to effects.","cn":"20 世纪应急管理把 mitigation 定为该领域中「预防」的一半；气候政策后来又把减缓成因与适应影响分开。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (the -ig- element and the deeper origin of mitis): neither is settled, so any proposed Indo-European root is a reconstruction rather than a demonstrated form.","cn":"来源不确定（-ig- 成分与 mitis 的更深来源）：两者均无定论，任何提出的印欧词根都是重构形式，而非已证实的形态。"}]},"similar":{"note":{"en":"Group one holds the classic look-alike pairs that share letters but not roots; group two holds near synonyms with a different image of lessening.","cn":"第一组是字母相近而词根不同的经典易混对；第二组是「减轻」意象不同的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mitigate","ipa":"/ˈmɪtɪɡeɪt/","tag":"verb, soften","definition":"The verb behind the noun: to make a harm less severe; its root is mitis 'soft'.","definitionCN":"名词背后的动词：使危害变轻；词根是 mitis「柔软」。"},{"word":"militate","ipa":"/ˈmɪlɪteɪt/","tag":"different root, weigh against","definition":"From Latin miles 'soldier': to militate against something means to work against it, a common confusion with mitigate.","definitionCN":"来自拉丁 miles「士兵」：militate against 指对某事起阻碍作用，常被误当成 mitigate。"},{"word":"meditation","ipa":"/ˌmedɪˈteɪʃn/","tag":"different root, thinking","definition":"From Latin meditari 'to ponder'; the resemblance to mitigation is accidental.","definitionCN":"来自拉丁 meditari「沉思」；与 mitigation 的相似纯属偶然。"},{"word":"mediation","ipa":"/ˌmediˈeɪʃn/","tag":"third-party help","definition":"From Latin medius 'middle': the act of a neutral party standing between two sides, not the lessening of harm itself.","definitionCN":"来自拉丁 medius「中间」：中立第三方站在两方之间，而非减轻危害本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"alleviation","ipa":"/əˌliːviˈeɪʃn/","tag":"lightening a burden","definition":"From Latin allevare 'to lighten': it stresses lifting weight off someone, especially pain or poverty.","definitionCN":"来自拉丁 allevare「使轻」：强调把重担从某人身上抬起，尤指痛苦或贫困。"},{"word":"abatement","ipa":"/əˈbeɪtmənt/","tag":"reduction in amount","definition":"From Old French abatre 'to beat down': a reduction in amount or intensity, often of noise or pollution.","definitionCN":"来自古法语 abatre「击倒」：数量或强度的削减，常用于噪音或污染。"},{"word":"adaptation","ipa":"/ˌædæpˈteɪʃn/","tag":"the other climate half","definition":"Adjusting to effects already under way; climate policy pairs it with mitigation, which cuts the causes.","definitionCN":"指对已经发生的影响作出调整；气候政策把它与削减成因的 mitigation 配对。"},{"word":"prevention","ipa":"/prɪˈvenʃn/","tag":"stopping before","definition":"Stopping something from happening at all, while mitigation assumes it happens and reduces the blow.","definitionCN":"指阻止某事发生；mitigation 则假定它已发生，再去削减打击。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real set phrases and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin mitis 'soft' is the root: mitigation softens the blow rather than removing it.","cn":"词根是拉丁 mitis「柔软」：mitigation 是把打击变软，而不是取消打击。"},{"en":"Keep mitigate apart from militate: one softens, the other weighs against.","cn":"把 mitigate 与 militate 分开：一个使变软，一个起阻碍作用。"},{"en":"Fixed phrases mark the fields: climate change mitigation, risk mitigation, mitigation measures.","cn":"固定搭配标出领域：减缓气候变化、风险缓解、缓解措施。"},{"en":"The legal phrase is 'in mitigation', used when pleading for a lighter sentence.","cn":"法律短语是 in mitigation，用于请求从轻量刑。"},{"en":"Unmitigated keeps the same root and means not softened at all, as in unmitigated disaster.","cn":"unmitigated 同根，意为完全未减轻，如十足的灾难。"}],"abstract":[{"en":"Picture a thick row of trees taking the force out of a wave.","cn":"想象一排厚实的树，把浪的力量卸掉。"},{"en":"Picture a cushion slid under a falling glass a moment before it lands.","cn":"想象在玻璃落地前一瞬，塞进一只垫子。"},{"en":"Picture a judge's pen pressing lighter because of one honest sentence.","cn":"想象法官的笔因为一句诚实话而落得轻些。"}]},"examples":[{"en":"Coastal wetlands are the cheapest mitigation against storm surge.","cn":"沿海湿地是抵御风暴潮最便宜的减灾手段。"},{"en":"The report treats emission cuts as mitigation and flood defences as adaptation.","cn":"报告把减排视为减缓，把防洪设施视为适应。"},{"en":"He offered his full cooperation in mitigation of the charge.","cn":"他提出全力配合，以减轻指控。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「miti（米提）+ gation（减）」——把灾情削薄一层 → 缓解、减灾","word":"mitigation"},"root":"拉丁 mitigare「使变软、使温和」= mitis「柔软、温和」+ 来源有争议的 -igare；名词后缀 -tion 表动作。mitis 与 -ig- 的更深来源均不确定。英语 mitigation。","sensesIntro":{"en":"Eight meanings follow one gesture, softening: of a physical blow, of disaster impact, of a sentence, of symptoms, of conflict, of environmental damage, of emissions and finally of words.","cn":"八个义项沿同一个动作展开，即「使变软」：物理打击、灾害冲击、量刑、症状、冲突、环境损害、排放，最后是言辞。"},"semanticMap":{"core":{"en":"CORE IMAGE: a band of trees takes the force out of the wave before it reaches the wall.","cn":"核心意象：一带树木在浪抵达墙之前卸掉它的力量。"},"chain":["SOFTEN","LESS SEVERE","STRUCTURAL WORKS","LEGAL LENIENCY","SYMPTOM RELIEF","CAUSE REDUCTION"],"branches":[{"senses":"S1 · S8","en":"SOFTNESS ITSELF: whether the target is a blow or a sentence, the act is the same softening.","cn":"软化本身：无论对象是打击还是判词，动作都是同一种变软。"},{"senses":"S2 · S6","en":"BUILT DEFENCES: wetlands, levees and offsets are softening made into construction and permits.","cn":"筑起的防线：湿地、堤坝与补偿，是把「变软」做成工程与许可。"},{"senses":"S3","en":"LEGAL LEDGER: circumstances are weighed so that the penalty lands lighter.","cn":"法律账本：权衡情节，使刑罚落得更轻。"},{"senses":"S4 · S5","en":"PAIN AND CONFLICT: medicine and diplomacy both soften what cannot be removed.","cn":"痛苦与冲突：医学与外交都在软化无法消除之物。"},{"senses":"S7","en":"CUTTING CAUSES: climate mitigation removes the source instead of cushioning the impact.","cn":"削减成因：气候减缓去掉源头，而不是垫住冲击。"}]},"affixes":{"intro":{"en":"Mitigation is a Latin verb plus the action suffix -tion, and the root mitis also builds a small family of English words.","cn":"mitigation 是一个拉丁动词加动作后缀 -tion，词根 mitis 还构成一小族英语词。"},"latinIntro":{"en":"Latin mitis and mitigare give mitigate, mitigation, mitigable and unmitigated; the suffix -tion marks the act or result.","cn":"拉丁 mitis 与 mitigare 衍生 mitigate、mitigation、mitigable 与 unmitigated；后缀 -tion 标记动作或结果。"},"items":[{"word":"mitis","structure":"mitis, mite (adj., third declension)","meaning":"soft, mild, ripe","meaningCN":"柔软的；温和的；成熟的","example":"The root image is something soft.","exampleCN":"词根的意象是柔软之物。"},{"word":"mitigare","structure":"mitigare, mitigavi, mitigatum (verb, first conjugation)","meaning":"to soften, make mild","meaningCN":"使变软；使温和","example":"The levee mitigates the flood.","exampleCN":"堤坝减轻了洪水的影响。"},{"word":"mitigate","structure":"mitigare through French","meaning":"to make less severe","meaningCN":"减轻；缓解","example":"Trees mitigate the wind.","exampleCN":"树木减弱风力。"},{"word":"mitigating","structure":"mitigate + -ing (adjective)","meaning":"serving to lessen","meaningCN":"起减轻作用的","example":"The court heard mitigating facts.","exampleCN":"法庭听取了减轻情节。"},{"word":"mitigation","structure":"mitigate + -ion (action or result)","meaning":"the act of softening","meaningCN":"缓解（动作或结果）","example":"Mitigation of the risk came first.","exampleCN":"风险缓解被放在首位。"},{"word":"mitigable","structure":"mitigate + -able (can be)","meaning":"able to be lessened","meaningCN":"可缓解的","example":"The damage was mitigable.","exampleCN":"损害是可以缓解的。"},{"word":"unmitigated","structure":"un- + mitigated (not softened)","meaning":"complete, not lessened","meaningCN":"未减轻的；十足的","example":"It was an unmitigated failure.","exampleCN":"那是一次彻头彻尾的失败。"},{"word":"mitigator","structure":"mitigate + -or (one who acts)","meaning":"one that lessens","meaningCN":"减轻者；缓解手段","example":"The wetland is a natural mitigator.","exampleCN":"湿地是天然的缓解手段。"},{"word":"-tion","structure":"-tion (Latin action suffix)","meaning":"the act or result of","meaningCN":"……的动作或结果","example":"mitigation is the act of softening.","exampleCN":"mitigation 就是使变软的动作。"}],"latinEntries":[{"word":"mitis","structure":"mitis, mite (adj., third declension)","meaning":"soft, mild, gentle","meaningCN":"柔软的；温和的"},{"word":"mitigare","structure":"mitigare, mitigavi, mitigatum (verb, first conjugation)","meaning":"to soften, make mild","meaningCN":"使变软；使温和"},{"word":"mitigatio","structure":"mitigatio, mitigationis (f., third declension)","meaning":"a softening, alleviation","meaningCN":"缓和；减轻"},{"word":"mitigatus","structure":"mitigatus, mitigata, mitigatum (past participle)","meaning":"softened, made mild","meaningCN":"被使软的；被减轻的"}]}},{"word":"environmental policy","ipa_uk":"/ɪnˌvaɪrənˈmentl ˈpɒləsi/","ipa_us":"/ɪnˌvaɪrənˈmentl ˈpɑːləsi/","definition_zh":"环境政策；政府或组织为保护环境、管理自然资源而制定的方针、法规与目标","definition_en":"a set of official rules, targets and instruments that govern how people use and protect the natural environment","core_image":"一张被红笔圈满的地图，圈内是湿地、烟囱与输油管，旁边并列着许可与禁令","scene":"市政厅把排放上限、湿地保护线与垃圾回收目标写进同一份文件，这份环境政策将约束未来十年的建设。The city hall wrote emission caps, wetland protection lines and recycling targets into one document, an environmental policy that would bind construction for the next ten years.","sceneCN":"这里 environmental policy 指「政府就环境利用与保护设定的成文方针与约束」（第 1 个义项：官方环境方针与法规集合）；句意为市政厅把排放上限、湿地保护线与回收目标写进同一份文件，这份环境政策将约束未来十年的建设。可辨识物件：圈注地图、排放上限表、许可印章、禁令标牌。","pos":[{"tag":"n.","zh":"环境政策（可数指一套政策，不可数指该领域）"}],"collocations":[{"phrase":"national environmental policy","zh":"国家环境政策"},{"phrase":"environmental policy maker","zh":"环境政策制定者"},{"phrase":"environmental policy framework","zh":"环境政策框架"},{"phrase":"implement environmental policy","zh":"实施环境政策"},{"phrase":"environmental policy goals","zh":"环境政策目标"},{"phrase":"corporate environmental policy","zh":"企业环境政策"}],"forms":[{"label":"复数","form":"environmental policies"},{"label":"相关形容词（环境的）","form":"environmental（环境的）"},{"label":"相关名词（环境）","form":"environment（环境）"},{"label":"相关名词（政策）","form":"policy（政策）"},{"label":"相关名词（政策制定者）","form":"policy maker（政策制定者）"},{"label":"近义说法（环境法规）","form":"environmental regulation（环境法规）"}],"derivatives":[{"word":"environment","pos":"n.","zh":"环境；周围状况"},{"word":"environmental","pos":"adj.","zh":"环境的"},{"word":"environmentalist","pos":"n.","zh":"环境保护主义者"},{"word":"environmentalism","pos":"n.","zh":"环境保护主义"},{"word":"policy","pos":"n.","zh":"政策；方针；保险单"}],"senses":[{"no":"01","title":"A government package of environmental rules","titleCN":"政府的一套环境规制","definition":"the combined laws, targets and instruments by which a government steers behaviour toward environmental goals","definitionCN":"政府借以引导行为朝向环境目标的法律、目标与手段之总和","example":"The new environmental policy pairs a carbon cap with a wetland protection fund.","exampleCN":"新的环境政策把碳排放上限与湿地保护基金配在一起。","why":"policy names a chosen course rather than a single law, so the phrase covers a package rather than one statute.","whyCN":"policy 指选定的路线而非单条法律，因此这个短语覆盖的是一整套安排，而不是一条法规。"},{"no":"02","title":"The instruments that carry it out","titleCN":"落实政策的具体工具","definition":"the permits, standards, taxes and subsidies through which the stated goals are enforced","definitionCN":"用以执行既定目标的许可证、标准、税费与补贴","example":"Environmental policy works through discharge permits more often than through bans.","exampleCN":"环境政策更多通过排污许可、而非禁令来起作用。","why":"once the course is chosen, the phrase shifts from goals to the tools that make the goals bite.","whyCN":"路线一旦选定，这个短语就从目标转向让目标真正生效的工具。"},{"no":"03","title":"A cross-border agreement","titleCN":"跨国环境协定","definition":"coordinated commitments among states on shared problems such as air, rivers or climate","definitionCN":"各国就空气、河流或气候等共同问题作出的协调承诺","example":"The river basin's environmental policy is set by a commission of four states.","exampleCN":"该流域的环境政策由一个四国委员会制定。","why":"many environmental problems cross borders, so the phrase is used for agreements no single state can enforce alone.","whyCN":"许多环境问题跨越国界，因此该短语也用于任何单一国家都无法独自执行的协定。"},{"no":"04","title":"A company's environmental code","titleCN":"企业环境方针","definition":"a firm's stated commitments and internal rules on emissions, waste and sourcing","definitionCN":"企业在排放、废弃物与采购方面公开承诺与内部规则","example":"The supplier audit checks whether the factory follows its own environmental policy.","exampleCN":"供应商审核检查工厂是否遵守自家环境方针。","why":"the word policy also means an organisation's chosen line of action, so companies borrow the phrase for voluntary codes.","whyCN":"policy 也指组织选定的行动路线，因此企业用这个短语指自愿性守则。"},{"no":"05","title":"Local land-use and planning policy","titleCN":"地方土地利用与规划政策","definition":"municipal rules on zoning, green space and transport that shape the local environment","definitionCN":"影响本地环境的分区、绿地与交通方面的市政规则","example":"The town's environmental policy keeps the floodplain free of new housing.","exampleCN":"该镇的环境政策使泛滥平原不再新建住宅。","why":"much environmental policy is delivered through planning decisions, so the phrase often appears in local documents.","whyCN":"许多环境政策通过规划决策落地，因此该短语常出现在地方文件中。"},{"no":"06","title":"Conservation and protected-area policy","titleCN":"保护地与保育政策","definition":"rules on parks, reserves and species protection that set aside land from development","definitionCN":"关于公园、保护区与物种保护的规则，使土地不作开发之用","example":"Wildlife corridors became a central item of the province's environmental policy.","exampleCN":"野生动物廊道成为该省环境政策的核心条目。","why":"the oldest strand of the phrase is direct protection: some land is simply withdrawn from use.","whyCN":"这个短语最古老的一支是直接保护：把某些土地从用途中撤出。"},{"no":"07","title":"A field of study and analysis","titleCN":"作为研究与分析领域的环境政策","definition":"the academic subject that compares how governments design and evaluate environmental rules","definitionCN":"比较各国政府如何设计与评估环境规则的学术领域","example":"She teaches environmental policy and runs a clinic for local councils.","exampleCN":"她教授环境政策，并为地方议会开设咨询工作坊。","why":"as a discipline, the phrase no longer names a decision but the study of how decisions are made.","whyCN":"作为学科，这个短语不再指某项决定，而指对决定形成过程的研究。"},{"no":"08","title":"Abstract: an organisation's stance toward nature","titleCN":"抽象义：一个机构对自然的态度","definition":"any declared attitude or priority an institution takes toward the natural world","definitionCN":"任何机构对自然界公开表明的态度或优先次序","example":"The museum's environmental policy was simply to stop printing guides.","exampleCN":"这家博物馆的环境方针简单到只是停止印刷导览册。","why":"the abstract use keeps only the notion of a declared line, with no legal force behind it.","whyCN":"抽象用法只保留「公开宣告的路线」这一层，背后并没有法律强制力。"}],"etymology":{"intro":{"en":"The phrase joins environment, from Old French environ 'around', and policy, from Greek politeia 'citizenship, government' through Latin politia. The combination is a twentieth-century fixed term. Dates are approximate.","cn":"这个短语由 environment 与 policy 组成：前者来自古法语 environ「四周」，后者来自希腊 politeia「公民身份、治理」，经拉丁 politia 传入。整个组合是 20 世纪的固定术语。年代均为约数。"},"items":[{"era":"FRENCH ENVIRON","en":"Environ 'around' came from en 'in' plus viron 'circle'; the deeper origin of viron is not established.","cn":"environ「四周」由 en「在内」加 viron「圈」构成；viron 的更远来源未得到证明。"},{"era":"ENGLISH ENVIRONMENT","en":"Environment first meant 'the act of surrounding', then 'surrounding conditions'; its modern ecological sense is nineteenth-century.","cn":"environment 最初指「围绕的动作」，继而指「周围状况」；其现代生态义形成于 19 世纪。"},{"era":"GREEK POLITEIA","en":"Polis 'city' gave politeia 'citizenship, constitution, government', the abstract side of city life.","cn":"polis「城邦」构成 politeia「公民身份、政体、治理」，是城邦生活的抽象一面。"},{"era":"LATIN AND FRENCH POLICY","en":"Latin politia and French policie split into two English branches: policy, a chosen course of action, and police, the force that enforces order.","cn":"拉丁 politia 与法语 policie 分成英语的两支：policy 指选定的行动路线，police 指维持秩序的警力。"},{"era":"THE FIXED TERM","en":"Environmental policy became a standard term with the environmental legislation of the 1960s and 1970s, when agencies were created to enforce it.","cn":"随着 20 世纪六七十年代的环境立法与执法机构建立，environmental policy 成为标准术语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): no single earliest citation for the fixed phrase is agreed, and the pre-French origin of viron is unsettled, so any reconstructed form is a hypothesis.","cn":"来源不确定（首见年代与更深词源）：这一固定短语的最早书证没有公认答案，viron 在法语之前的来源亦未确定，任何重构形式都只是假说。"}]},"similar":{"note":{"en":"Group one holds words from the same root as policy that are constantly mixed up; group two holds neighbouring terms for the rules themselves.","cn":"第一组是与 policy 同根、极易混淆的词；第二组是指规则本身的相邻术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"politics","ipa":"/ˈpɒlətɪks/","tag":"the contest, not the course","definition":"The activity of competing for power, from the same Greek polis: politics is the struggle, policy is the chosen line that follows.","definitionCN":"争夺权力的活动，同出希腊 polis：politics 是争斗过程，policy 是争斗之后选定的路线。"},{"word":"polity","ipa":"/ˈpɒləti/","tag":"the organised community","definition":"A state or organised society seen as a political body; it names the community, not a rule.","definitionCN":"作为政治体看待的国家或有组织社会；它指共同体，而非某条规则。"},{"word":"police","ipa":"/pəˈliːs/","tag":"same root, other branch","definition":"The force that keeps order; it shares the Greek source with policy but split off as the enforcement branch.","definitionCN":"维持秩序的警力；与 policy 同出希腊语源，但分出去成为执法的一支。"},{"word":"politicize","ipa":"/pəˈlɪtɪsaɪz/","tag":"verb, make political","definition":"To make an issue a matter of political dispute; the opposite of settling it by a standing policy.","definitionCN":"使某个议题成为政治争端；与用既定政策解决它相反。"}]},{"heading":"NEAR MEANING","entries":[{"word":"environmental law","ipa":"/ɪnˌvaɪrənˈmentl lɔː/","tag":"the binding statute","definition":"The enacted statutes and court rules themselves; policy is the intention, law is the enforceable text.","definitionCN":"已颁行的法规与判例规则本身；policy 是意图，law 是可执行的文本。"},{"word":"regulation","ipa":"/ˌreɡjuˈleɪʃn/","tag":"one instrument","definition":"A specific binding rule issued under a statute; one policy usually contains many regulations.","definitionCN":"依法律发布的具体约束性规则；一项政策通常包含许多规章。"},{"word":"conservation policy","ipa":"/ˌkɒnsəˈveɪʃn ˈpɒləsi/","tag":"one strand","definition":"The part of environmental policy concerned with protected areas and species, narrower than the whole.","definitionCN":"环境政策中涉及保护地与物种的部分，范围比整体更窄。"},{"word":"environmental management","ipa":"/ɪnˌvaɪrənˈmentl ˈmænɪdʒmənt/","tag":"practice, not rule","definition":"The operational practice of running sites and audits to meet environmental goals, downstream of policy.","definitionCN":"为达成环境目标而运行场地与审核的实务操作，位于政策的下游。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real set phrases and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"environ means around, so environment is the ring of conditions around us.","cn":"environ 表示「四周」，所以 environment 就是我们周围那圈条件。"},{"en":"policy and police share polis but split: one is a chosen course, the other enforcement.","cn":"policy 与 police 同出 polis 却分成两支：一个是被选定的路线，一个是执法。"},{"en":"Fixed phrases mark the levels: national environmental policy, corporate environmental policy.","cn":"固定搭配标出层级：国家环境政策、企业环境政策。"},{"en":"The pair with law is useful: policy is intent, environmental law is enforceable text.","cn":"与 law 的对照很有用：policy 是意图，environmental law 是可执行的文本。"},{"en":"The relative environmentalist names the person who pushes for such policy.","cn":"同族词 environmentalist 指推动这类政策的人。"}],"abstract":[{"en":"Picture a map with a red circle drawn around a marsh and a chimney at once.","cn":"想象一张地图，红圈同时圈住一片沼泽和一根烟囱。"},{"en":"Picture a dial that caps a factory's output at a fixed mark.","cn":"想象一只旋钮，把工厂的产出卡在固定刻度。"},{"en":"Picture a treaty signed by four neighbours who share one river.","cn":"想象四个共享一条河的邻国签下同一份协定。"}]},"examples":[{"en":"Environmental policy shifted from cleaning rivers to preventing pollution at the source.","cn":"环境政策从清理河流转向从源头预防污染。"},{"en":"No single state can set environmental policy for a shared sea.","cn":"任何单一国家都无法为一片共享的海域制定环境政策。"},{"en":"The firm's environmental policy promised audits but funded none.","cn":"这家企业的环境方针承诺审核，却没有为此拨款。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「environment（周围）+ policy（政策）」——给周围环境立规矩 → 环境政策","word":"environmental policy"},"root":"environment 来自古法语 environ「四周」（en + viron），policy 来自希腊 politeia「治理」经拉丁 politia 与法语 policie；viron 与 politeia 的更深来源不确定。英语短语 environmental policy。","sensesIntro":{"en":"Eight meanings follow one phrase from the government's course of action to its instruments, its cross-border and corporate forms, its local and conservation strands, its academic study and finally any declared stance.","cn":"八个义项沿同一短语展开：从政府的行动路线到执行工具，再到跨国与企业形态、地方与保育分支、学术研究，最后是任何公开表明的态度。"},"semanticMap":{"core":{"en":"CORE IMAGE: one map circled in red, with rules written in the margin.","cn":"核心意象：一张被红笔圈注的地图，页边写着规则。"},"chain":["SURROUNDINGS","CHOSEN COURSE","LEGAL INSTRUMENTS","SHARED RIVER","FIRM CODE","STANCE"],"branches":[{"senses":"S1 · S2","en":"COURSE TO TOOLS: goals are written first, then permits and taxes make them bite.","cn":"从路线到工具：先写下目标，再用许可与税费让它生效。"},{"senses":"S3","en":"BORDERLESS PROBLEMS: air and rivers ignore frontiers, so policy must be agreed across them.","cn":"无界问题：空气与河流不顾边界，政策因此必须跨边界议定。"},{"senses":"S4","en":"VOLUNTARY CODE: a company borrows the phrase for promises it writes to itself.","cn":"自愿守则：企业借用这个短语，指它对自己写下的承诺。"},{"senses":"S5 · S6","en":"LAND AND LIFE: zoning and reserves are the oldest, most concrete strand.","cn":"土地与生命：分区与保护区是最古老、最具体的一支。"},{"senses":"S7 · S8","en":"FROM RULE TO STANCE: study and loose talk both drop the enforcement, keeping only the declared line.","cn":"从规则到态度：研究与宽泛用法都去掉强制力，只留公开宣告的路线。"}]},"affixes":{"intro":{"en":"Both halves are built from small pieces: environ plus -ment on one side, polis through politeia on the other.","cn":"两半都由小部件构成：一边是 environ 加 -ment，另一边是 polis 经 politeia 而来。"},"latinIntro":{"en":"Latin politia and politicus give policy, politics and political; the French element environ gives environment and environmental.","cn":"拉丁 politia 与 politicus 衍生 policy、politics 与 political；法语成分 environ 衍生 environment 与 environmental。"},"items":[{"word":"environ","structure":"en + viron (Old French, 'in a circle')","meaning":"around","meaningCN":"在四周","example":"Trees environ the field.","exampleCN":"树木环绕着田地。"},{"word":"-ment","structure":"-ment (French noun suffix)","meaning":"result or state of","meaningCN":"……的结果或状态","example":"environment is the state of being surrounded.","exampleCN":"environment 就是被环绕的状态。"},{"word":"environment","structure":"environ + -ment","meaning":"surrounding conditions","meaningCN":"周围状况；环境","example":"The environment shapes the species.","exampleCN":"环境塑造物种。"},{"word":"environmental","structure":"environment + -al (relating to)","meaning":"of the surroundings","meaningCN":"与周围环境有关的","example":"Environmental rules protect the marsh.","exampleCN":"环境规则保护沼泽。"},{"word":"polis","structure":"polis (Greek noun, 'city')","meaning":"city, community","meaningCN":"城邦；共同体","example":"The polis set its own rules.","exampleCN":"城邦自定规则。"},{"word":"policy","structure":"Greek politeia through Latin politia","meaning":"a chosen course of action","meaningCN":"选定的行动路线","example":"The policy caps emissions.","exampleCN":"该政策设定排放上限。"},{"word":"police","structure":"same Latin source, other branch","meaning":"the force that keeps order","meaningCN":"维持秩序的警力","example":"The police enforce the rule.","exampleCN":"警方执行该规则。"},{"word":"politics","structure":"policy + -ics (study or activity)","meaning":"the contest for power","meaningCN":"权力竞争","example":"Politics delayed the policy.","exampleCN":"政治争斗拖延了政策。"}],"latinEntries":[{"word":"politia","structure":"politia, politiae (f., first declension)","meaning":"citizenship, government, administration","meaningCN":"公民身份；治理；行政"},{"word":"politicus","structure":"politicus, politica, politicum (adj.)","meaning":"of citizens or the state","meaningCN":"公民或国家的"}]}},{"word":"environmental impact","ipa_uk":"/ɪnˌvaɪrənˈmentl ˈɪmpækt/","ipa_us":"/ɪnˌvaɪrənˈmentl ˈɪmpækt/","definition_zh":"环境影响；人类活动或项目对自然环境造成的改变与后果","definition_en":"the change in the natural environment caused by a project, product or human activity","core_image":"推土机刚铲开一道口子，浑水从缺口流进清亮的溪流，颜色在交汇处泾渭分明","scene":"环评报告用整章测算新公路会怎样改变溪流与筑巢的鸟，评估其环境影响。The assessment devoted a whole chapter to how the new road would alter the stream and the nesting birds, measuring its environmental impact.","sceneCN":"这里 environmental impact 指「人为活动对自然环境造成的可测改变」（第 1 个义项：项目引起的环境变化与后果）；句意为环评报告用整章测算新公路会如何改变溪流与筑巢鸟类，从而评估其环境影响。可辨识物件：推土缺口、浑水与清溪交汇线、巢中鸟、评估表格。","pos":[{"tag":"n.","zh":"环境影响（可数指一项具体影响，不可数指总体影响）"}],"collocations":[{"phrase":"environmental impact assessment","zh":"环境影响评价"},{"phrase":"adverse environmental impact","zh":"不利环境影响"},{"phrase":"reduce environmental impact","zh":"减少环境影响"},{"phrase":"environmental impact statement","zh":"环境影响报告书"},{"phrase":"cumulative environmental impact","zh":"累积环境影响"},{"phrase":"minimize environmental impact","zh":"尽量降低环境影响"}],"forms":[{"label":"复数","form":"environmental impacts"},{"label":"相关形容词（环境的）","form":"environmental（环境的）"},{"label":"相关名词（影响）","form":"impact（影响；冲击）"},{"label":"相关动词（影响）","form":"impact（对……产生影响）"},{"label":"相关术语（环境影响评价）","form":"environmental impact assessment（环境影响评价）"},{"label":"近义说法（生态足迹）","form":"ecological footprint（生态足迹）"}],"derivatives":[{"word":"impact","pos":"n./v.","zh":"影响；冲击；对……产生影响"},{"word":"impactful","pos":"adj.","zh":"有显著影响的"},{"word":"impinge","pos":"v.","zh":"撞击；侵犯（同根异形）"},{"word":"environment","pos":"n.","zh":"环境"},{"word":"environmentalist","pos":"n.","zh":"环境保护主义者"}],"senses":[{"no":"01","title":"A measurable change caused by human activity","titleCN":"人为活动造成的可测变化","definition":"the observable change in air, water, soil or living things produced by a project or activity","definitionCN":"项目或活动对空气、水、土壤或生物造成的可观察变化","example":"The road's environmental impact showed first in the silt load of the stream.","exampleCN":"这条公路的环境影响最先体现在溪水的含沙量上。","why":"impact began as a collision, so the phrase presents human activity as striking the environment and leaving a mark.","whyCN":"impact 本义是撞击，因此这个短语把人的活动呈现为撞上环境并留下痕迹。"},{"no":"02","title":"The formal assessment procedure","titleCN":"正式的环境影响评价程序","definition":"the regulated study predicting impacts before approval, usually shortened to EIA","definitionCN":"审批前预测影响的法定研究，通常简称 EIA","example":"No permit was issued until the environmental impact had been reviewed.","exampleCN":"在环境影响经过审查之前，没有发放许可。","why":"once law required a prediction before consent, the phrase came to name the document and the process.","whyCN":"一旦法律要求在批准前先作预测，这个短语便用来指那份文件与那套流程。"},{"no":"03","title":"A negative burden on ecosystems","titleCN":"对生态系统的负面负担","definition":"the damaging share of the change, measured as loss of habitat, pollution or emissions","definitionCN":"变化中有害的那部分，以栖息地丧失、污染或排放计量","example":"The report put the environmental impact of the spill at ten years of recovery.","exampleCN":"报告把泄漏的环境影响估为十年恢复期。","why":"in ordinary use the phrase almost always implies harm, even though impact itself is neutral.","whyCN":"日常使用中这个短语几乎总暗示损害，尽管 impact 本身是中性的。"},{"no":"04","title":"A positive or restorative impact","titleCN":"正面或修复性的环境影响","definition":"an improvement in environmental conditions produced by deliberate restoration or design","definitionCN":"通过有意的修复或设计带来的环境状况改善","example":"The wetland created downstream had a measurable positive environmental impact.","exampleCN":"在下游新建的湿地产生了可测的正面环境影响。","why":"modern assessment scores both signs, so the phrase had to admit improvement as well as damage.","whyCN":"现代评估正负都计分，因此这个短语也必须容纳改善，而不只是损害。"},{"no":"05","title":"A cumulative impact over time","titleCN":"随时间累积的影响","definition":"the combined effect of many small projects that no single assessment would have flagged","definitionCN":"许多小项目叠加的效果，任何单项评估都不会标出","example":"Each dock was minor, but their cumulative environmental impact closed the bay.","exampleCN":"每座码头都很小，但它们的累积环境影响封住了海湾。","why":"assessment had to add a time dimension once small repeated projects slipped past single-project reviews.","whyCN":"当反复的小项目绕过单项审查后，评估不得不加入时间维度。"},{"no":"06","title":"A life-cycle impact of a product","titleCN":"产品全生命周期的环境影响","definition":"the total impact of a product from extraction and manufacture through use and disposal","definitionCN":"产品从开采、制造、使用到处置的总影响","example":"The label reports the environmental impact of the shirt across its whole life.","exampleCN":"标签标出这件衬衫在整个生命周期中的环境影响。","why":"the phrase moved from sites to products, so impact is summed over stages rather than over a map.","whyCN":"这个短语从场地转向产品，影响因此按阶段相加，而不是按地图相加。"},{"no":"07","title":"Climate and carbon impact","titleCN":"气候与碳影响","definition":"the contribution of an activity to warming, expressed as emissions per unit of output","definitionCN":"某项活动对升温的贡献，以单位产出的排放量表示","example":"Beef has a far higher environmental impact per calorie than lentils.","exampleCN":"按每卡路里计，牛肉的环境影响远高于扁豆。","why":"climate accounting turned impact into a number per unit, which made comparisons across products possible.","whyCN":"气候核算把影响变成单位数值，使产品之间的比较成为可能。"},{"no":"08","title":"Abstract: the mark left on a place","titleCN":"抽象义：留给地方的痕迹","definition":"the lasting trace an activity leaves on a landscape or community, whether or not it is measurable","definitionCN":"某项活动在景观或社区留下的持久痕迹，无论是否可计量","example":"The quarry's environmental impact outlasted the company by forty years.","exampleCN":"采石场的环境影响到公司消失之后还持续了四十年。","why":"the abstract use keeps the image of a struck surface and lets the trace stand for the whole effect.","whyCN":"抽象用法保留「被击中的表面」这一意象，用痕迹代表整体效果。"}],"etymology":{"intro":{"en":"Environmental comes from French environ 'around'; impact comes from Latin impingere 'to drive against', built on in- and pangere 'to fasten'. The fixed phrase belongs to twentieth-century assessment law. Dates are approximate.","cn":"environmental 来自法语 environ「四周」；impact 来自拉丁 impingere「撞向」，由 in- 与 pangere「钉入」构成。这个固定短语属于 20 世纪的环境评估法。年代均为约数。"},"items":[{"era":"LATIN PANGERE","en":"Pangere meant 'to fasten, drive in', as a stake is driven into ground; its deeper origin is not established, and a link to pax 'peace' is only a hypothesis.","cn":"pangere 意为「钉入、固定」，如把桩子钉进地里；其更远来源未得到证明，与 pax「和平」的联系仅是假说。"},{"era":"LATIN IMPINGERE","en":"In- 'against' plus pangere produced impingere 'to strike against, to collide with'.","cn":"in-「对着」加 pangere 构成 impingere「撞上、碰撞」。"},{"era":"ENGLISH IMPACT","en":"English impact first named a collision, then the force of a collision; the sense of a forceful effect appears later.","cn":"英语 impact 先指碰撞，继而指碰撞的力量；「强烈影响」义出现得更晚。"},{"era":"EFFECT SENSE","en":"By the nineteenth and twentieth centuries impact was used for any strong effect, which made the word available to policy language.","cn":"到 19 至 20 世纪，impact 已用于指任何强烈效果，这使它能进入政策语言。"},{"era":"ASSESSMENT LAW","en":"Environmental impact assessment was written into United States law at the end of the 1960s and spread to other countries within a decade.","cn":"环境影响评价在 20 世纪 60 年代末写入美国法律，并在十年内传播到其他国家。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): the exact first citation of the fixed phrase is not settled, and the pre-Latin origin of pangere is uncertain, so any proposed root is a reconstruction.","cn":"来源不确定（首见年代与更深词源）：这一固定短语的最早书证尚无定论，pangere 在拉丁语之前的来源亦不确定，任何提出的词根都是重构形式。"}]},"similar":{"note":{"en":"Group one holds words that look like impact but carry a different root or a different literal image; group two holds the measures used when impact is counted.","cn":"第一组是外形像 impact、却词根不同或字面意象不同的词；第二组是计量影响时使用的指标。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"impinge","ipa":"/ɪmˈpɪndʒ/","tag":"same root, contact","definition":"From the same Latin pangere: to strike or encroach on something, stressing physical contact rather than the resulting change.","definitionCN":"同出拉丁 pangere：撞击或侵犯某物，强调物理接触，而非由此产生的变化。"},{"word":"compact","ipa":"/kəmˈpækt/","tag":"same root, pressed together","definition":"Com- plus pangere 'fasten': pressed firmly together, which is why the word is also a small case.","definitionCN":"com- 加 pangere「固定」：被紧紧压在一起，因此也指小粉盒。"},{"word":"affect","ipa":"/əˈfekt/","tag":"different root, verb","definition":"From Latin afficere 'to do to': a verb meaning to act on something, unrelated at the root to impact.","definitionCN":"来自拉丁 afficere「对……施加」：动词，意为作用于某物，词根与 impact 无关。"},{"word":"impractical","ipa":"/ɪmˈpræktɪkl/","tag":"looks alike, no relation","definition":"In- plus practical: not workable. The similar opening letters are coincidence, not shared ancestry.","definitionCN":"in- 加 practical：不可行。开头字母相似纯属巧合，并无共同来源。"}]},{"heading":"NEAR MEANING","entries":[{"word":"footprint","ipa":"/ˈfʊtprɪnt/","tag":"the summed measure","definition":"The total area or quantity of resources an activity consumes, expressed as one comparable number.","definitionCN":"某项活动消耗的总面积或资源量，以单个可比较的数字表示。"},{"word":"external effect","ipa":"/ɪkˈstɜːnl ɪˈfekt/","tag":"economics term","definition":"A cost or benefit falling on third parties; economists use it when the harm is not priced into the project.","definitionCN":"落在第三方身上的成本或收益；当损害未计入项目价格时，经济学使用这一说法。"},{"word":"ecological damage","ipa":"/ˌiːkəˈlɒdʒɪkl ˈdæmɪdʒ/","tag":"harm only","definition":"Loss or injury to living systems; it names only the negative side that environmental impact as a technical term keeps neutral.","definitionCN":"对生命系统的损失或伤害；它只指负面一面，而作为技术术语的 environmental impact 保持中性。"},{"word":"pollution load","ipa":"/pəˈluːʃn ləʊd/","tag":"measured input","definition":"The quantity of a pollutant released into a medium, a single component of a wider impact.","definitionCN":"排入某种介质中的污染物数量，是更广影响中的单一成分。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real set phrases and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Impact comes from in- plus pangere 'drive in', so the original picture is something struck and marked.","cn":"impact 来自 in- 加 pangere「钉入」，原初画面是被撞上并留下痕迹。"},{"en":"The abbreviation EIA stands for environmental impact assessment, the standard procedure.","cn":"缩写 EIA 就是 environmental impact assessment，即标准评价程序。"},{"en":"Fixed phrases mark the scale: adverse, cumulative, positive environmental impact.","cn":"固定搭配标出性质与规模：不利的、累积的、正面的环境影响。"},{"en":"Keep impact and affect apart: impact is a noun or a transitive verb of effect, affect is the everyday verb.","cn":"把 impact 与 affect 分开：impact 是名词或表效果及物动词，affect 是日常动词。"},{"en":"Footprint is the summed version; impact is the change itself.","cn":"footprint 是汇总后的度量；impact 是改变本身。"}],"abstract":[{"en":"Picture a clear stream with one brown tributary joining it.","cn":"想象一条清溪，一条褐色支流汇入其中。"},{"en":"Picture a footprint pressed into mud that stays after the walker is gone.","cn":"想象泥地上的一枚脚印，走路的人离开后仍在。"},{"en":"Picture a ledger where each small purchase is added to one total.","cn":"想象一本账，每笔小额支出都累加到同一个总数。"}]},"examples":[{"en":"The pipeline's environmental impact was judged against the whole river basin.","cn":"这条管道的环境影响是以整个流域为基准来评判的。"},{"en":"Fewer flights would cut the environmental impact of the conference sharply.","cn":"减少航班会大幅削减这次会议的环境影响。"},{"en":"Each small dam looked harmless, but their cumulative environmental impact was severe.","cn":"每座小坝看似无害，其累积环境影响却很严重。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「environment（环境）+ impact（撞击）」——人的活动撞在环境上留下的痕 → 环境影响","word":"environmental impact"},"root":"environmental 来自法语 environ「四周」；impact 来自拉丁 impingere「撞向」= in- + pangere「钉入」。pangere 的更深来源不确定，与 pax 的联系仅为假说。英语短语 environmental impact。","sensesIntro":{"en":"Eight meanings follow one phrase from the measured change to the legal procedure, then to negative, positive and cumulative readings, to products and carbon, and finally to the mark left on a place.","cn":"八个义项沿同一短语展开：从可测变化到法定程序，再到负面、正面与累积读法，进而到产品与碳，最后是留在地方上的痕迹。"},"semanticMap":{"core":{"en":"CORE IMAGE: a machine cuts into a bank and muddy water meets clear water.","cn":"核心意象：机器切开河岸，浑水与清水相遇。"},"chain":["STRIKE","OBSERVED CHANGE","ASSESSED BEFORE","HARM WEIGHED","SUMMED OVER TIME","TRACE LEFT"],"branches":[{"senses":"S1 · S2","en":"FROM MARK TO METHOD: a change must be predicted and written down before consent is given.","cn":"从痕迹到方法：变化必须在批准之前被预测并写下。"},{"senses":"S3 · S4","en":"SIGN OF THE CHANGE: the same measure can report damage or restoration.","cn":"变化的正负：同一度量既能报告损害，也能报告修复。"},{"senses":"S5","en":"ADDED SMALLNESS: many minor marks add up to one large one.","cn":"小处的累加：许多轻微痕迹相加成为一个大痕迹。"},{"senses":"S6 · S7","en":"ACROSS A LIFE: counting by product and by calorie turns impact into a comparable number.","cn":"跨越一生：按产品与按卡路里计算，把影响变成可比较的数字。"},{"senses":"S8","en":"AFTERWARD: the trace can outlast the activity that made it.","cn":"事后：痕迹能比造成它的活动存在得更久。"}]},"affixes":{"intro":{"en":"The phrase pairs a French-derived adjective with a Latin verb-derived noun, and each half still builds its own English words.","cn":"这个短语把法语来源的形容词与拉丁动词来源的名词配在一起，两半各自仍在构成英语词。"},"latinIntro":{"en":"Latin pangere and impingere build impact, impinge and compact; French environ builds environment and environmental.","cn":"拉丁 pangere 与 impingere 构成 impact、impinge 与 compact；法语 environ 构成 environment 与 environmental。"},"items":[{"word":"in-","structure":"in- (Latin prefix, 'against, into')","meaning":"against; into","meaningCN":"对着；进入","example":"The prefix turns fastening into striking against.","exampleCN":"这个前缀把「固定」变成「撞向」。"},{"word":"pangere","structure":"pangere, pepigi, pactum (verb, third conjugation)","meaning":"to fasten, drive in","meaningCN":"钉入；固定","example":"A stake is driven into the ground.","exampleCN":"桩子被钉进地里。"},{"word":"impingere","structure":"in- + pangere","meaning":"to strike against","meaningCN":"撞上；碰撞","example":"The wave struck the wall.","exampleCN":"浪撞上了墙。"},{"word":"impact","structure":"impingere through Latin impactus","meaning":"a collision; a strong effect","meaningCN":"碰撞；强烈影响","example":"The spill had a lasting impact.","exampleCN":"泄漏留下了持久影响。"},{"word":"impinge","structure":"in- + pangere, English verb","meaning":"to strike or encroach","meaningCN":"撞击；侵犯","example":"The rule impinges on local habits.","exampleCN":"这条规则侵犯了当地习惯。"},{"word":"environment","structure":"environ + -ment","meaning":"surrounding conditions","meaningCN":"周围状况；环境","example":"The environment absorbs the waste.","exampleCN":"环境吸纳了这些废物。"},{"word":"environmental","structure":"environment + -al","meaning":"of the surroundings","meaningCN":"环境的","example":"Environmental data were collected.","exampleCN":"环境数据已被收集。"},{"word":"assessment","structure":"assess + -ment (result of judging)","meaning":"a judgement of value or risk","meaningCN":"评估；评定","example":"The assessment took a year.","exampleCN":"评估花了一年。"}],"latinEntries":[{"word":"pangere","structure":"pangere, pepigi, pactum (verb, third conjugation)","meaning":"to fasten, drive in, fix","meaningCN":"钉入；固定"},{"word":"impingere","structure":"impingere, impingi, impactum (verb, third conjugation)","meaning":"to strike against, collide","meaningCN":"撞上；碰撞"},{"word":"impactus","structure":"impactus, impacta, impactum (past participle)","meaning":"struck against","meaningCN":"被撞上的"}]}},{"word":"impact assessment","ipa_uk":"/ˈɪmpækt əˌsesmənt/","ipa_us":"/ˈɪmpækt əˌsesmənt/","definition_zh":"影响评估；（尤指）环境影响评价；对项目、政策或事件后果的系统评估","definition_en":"a systematic study that predicts the effects a project, policy or event will have before a decision is made","core_image":"一张摊开的表格：左边列项目工序，右边按空气、水、土壤、生物逐格打分","scene":"在开工之前，顾问用一年时间走访河段、测算噪声与泥沙，提交了完整的影响评估。Before ground was broken, consultants spent a year surveying the river reach and modelling noise and sediment, then filed a full impact assessment.","sceneCN":"这里 impact assessment 指「决策前对后果所作的系统性预测研究」（第 1 个义项：对影响的事先评估）；句意为开工之前，顾问用一年时间走访河段、测算噪声与泥沙，提交了完整的影响评估。可辨识物件：摊开的表格、河段测绘图、噪声仪、泥沙采样瓶。","pos":[{"tag":"n.","zh":"影响评估（可数指一次评估，不可数指该程序）"}],"collocations":[{"phrase":"environmental impact assessment","zh":"环境影响评价"},{"phrase":"carry out an impact assessment","zh":"开展影响评估"},{"phrase":"impact assessment report","zh":"影响评估报告"},{"phrase":"social impact assessment","zh":"社会影响评估"},{"phrase":"regulatory impact assessment","zh":"监管影响评估"},{"phrase":"prior impact assessment","zh":"事前影响评估"}],"forms":[{"label":"复数","form":"impact assessments"},{"label":"相关名词（影响）","form":"impact（影响；冲击）"},{"label":"相关名词（评估）","form":"assessment（评估）"},{"label":"相关动词（评估）","form":"assess（评估；评定）"},{"label":"相关名词（评估者）","form":"assessor（评估人）"},{"label":"相关术语（环境影响评价）","form":"environmental impact assessment（环境影响评价）"}],"derivatives":[{"word":"assess","pos":"v.","zh":"评估；评定；核定（税额）"},{"word":"assessment","pos":"n.","zh":"评估；评定"},{"word":"assessor","pos":"n.","zh":"评估人；估税员"},{"word":"impact","pos":"n./v.","zh":"影响；冲击"},{"word":"impactful","pos":"adj.","zh":"有显著影响的"}],"senses":[{"no":"01","title":"A systematic prediction of effects","titleCN":"对后果的系统性预测","definition":"a structured study that forecasts what a proposed action will change and how much","definitionCN":"结构化研究，预测拟议行动将改变什么、改变多少","example":"The impact assessment forecast a tenfold rise in traffic noise.","exampleCN":"影响评估预测交通噪声将上升十倍。","why":"assessment comes from a judge sitting beside a case, so the phrase is a weighing done before the verdict.","whyCN":"assessment 源自法官坐在案件旁边审理，因此这个短语是在判决之前完成的权衡。"},{"no":"02","title":"The environmental procedure","titleCN":"环境影响评价程序","definition":"the legally required environmental study, usually shortened to EIA, filed before consent","definitionCN":"法律要求的环境研究，通常简称 EIA，在批准之前提交","example":"The dam was halted because its impact assessment had ignored downstream farms.","exampleCN":"大坝被叫停，因为其影响评估忽略了下游农场。","why":"the procedure gave the phrase its public meaning, tied to permits rather than to academic forecasting.","whyCN":"这套程序赋予该短语公共含义，使其与许可相连，而非与学术预测相连。"},{"no":"03","title":"A social impact study","titleCN":"社会影响评估","definition":"a study of how a project changes employment, housing, health and community life","definitionCN":"研究项目如何改变就业、住房、健康与社区生活","example":"The social impact assessment found that resettlement would split three villages.","exampleCN":"社会影响评估发现，移民安置会拆散三个村庄。","why":"once the method proved useful for land, it was applied to people, so the phrase gained a social branch.","whyCN":"方法在土地上奏效后又被用于人，这个短语因此多出社会一支。"},{"no":"04","title":"A health impact study","titleCN":"健康影响评估","definition":"a study estimating changes in illness, injury or exposure caused by a policy or project","definitionCN":"估算政策或项目引起的疾病、伤害或暴露变化的评估","example":"The health impact assessment linked the new road to childhood asthma.","exampleCN":"健康影响评估把新公路与儿童哮喘联系起来。","why":"public health borrowed the format to put health on the same table as cost and environment.","whyCN":"公共卫生借用了这一格式，把健康与成本、环境并列在同一张桌上。"},{"no":"05","title":"A regulatory cost-benefit review","titleCN":"监管影响评估（成本收益审查）","definition":"a review of the costs and benefits a proposed regulation would impose before it is adopted","definitionCN":"在通过之前审查拟议规章会带来的成本与收益","example":"The regulatory impact assessment delayed the ban by eighteen months.","exampleCN":"监管影响评估使该禁令推迟了十八个月。","why":"governments extended the method from projects to rules, asking what a rule itself would change.","whyCN":"政府把方法从项目扩展到规章，追问规章本身会改变什么。"},{"no":"06","title":"A strategic assessment of plans","titleCN":"规划层面的战略评估","definition":"an assessment of a whole plan or programme rather than of a single project","definitionCN":"针对整个规划或计划而非单个项目的评估","example":"The strategic impact assessment examined the transport plan before any road was designed.","exampleCN":"战略影响评估在尚未设计任何道路时就审查了交通规划。","why":"project-level review came too late for decisions already fixed upstream, so the method moved up a level.","whyCN":"项目层面的审查对已在源头定下的事太迟，方法因此上移一级。"},{"no":"07","title":"A technology impact study","titleCN":"技术影响评估","definition":"a study of the social and environmental consequences of a new technology before it spreads","definitionCN":"在新技术扩散之前研究其社会与环境后果","example":"An impact assessment of the new crop predicted resistance within five seasons.","exampleCN":"对新作物的影响评估预测，抗性会在五个生长季内出现。","why":"technology assessment borrowed the phrase because the object of prediction had become an innovation rather than a site.","whyCN":"技术评估借用这个短语，因为预测对象已从场地变成了创新本身。"},{"no":"08","title":"Abstract: any weighing of consequences","titleCN":"抽象义：对后果的任何权衡","definition":"any deliberate attempt to weigh consequences before acting, however informal","definitionCN":"任何在行动之前有意权衡后果的尝试，无论是否正式","example":"Her move abroad came with a private impact assessment of the family's finances.","exampleCN":"她移居海外之前，私下对家庭财务做了一番影响权衡。","why":"the abstract use drops the procedure and keeps only the gesture of weighing before acting.","whyCN":"抽象用法去掉程序，只保留「行动之前先权衡」这一姿态。"}],"etymology":{"intro":{"en":"Impact comes from Latin impingere 'to strike against'; assessment comes from Latin assidere, 'to sit beside', originally of a judge beside a case. The fixed phrase is a twentieth-century administrative term. Dates are approximate.","cn":"impact 来自拉丁 impingere「撞向」；assessment 来自拉丁 assidere「坐在旁边」，原指法官坐在案件旁审理。这个固定短语是 20 世纪的行政术语。年代均为约数。"},"items":[{"era":"LATIN SEDERE","en":"Sedere 'to sit' is generally taken to continue an Indo-European root for sitting; the connection is broadly accepted rather than disputed.","cn":"sedere「坐」一般被认为延续了印欧语中表示「坐」的词根；这一联系被广泛接受，而非有争议。"},{"era":"LATIN ASSIDERE","en":"Ad- 'beside' plus sedere gave assidere 'to sit beside', used of an assistant or a judge sitting by a case.","cn":"ad-「在旁边」加 sedere 构成 assidere「坐在旁边」，用于坐在案件旁的助手或法官。"},{"era":"MEDIEVAL ASSESS","en":"Medieval Latin turned the verb toward fixing an amount, especially a tax, and English assess kept that fiscal sense.","cn":"中世纪拉丁语把这个动词转向「确定数额」，尤其是税额，英语 assess 保留了这一财政义。"},{"era":"ENGLISH ASSESSMENT","en":"Assessment first meant the fixing of a tax or a value, then any judgement of worth or risk.","cn":"assessment 最初指确定税额或价值，后来泛指对价值或风险的判断。"},{"era":"ADMINISTRATIVE PROCEDURE","en":"Environmental impact assessment entered United States law at the end of the 1960s; regulatory and strategic forms followed in the 1980s and 1990s.","cn":"环境影响评价在 20 世纪 60 年代末进入美国法律；监管型与战略型评估在 80、90 年代相继出现。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest citation of the exact phrase is not fixed, and the pre-Latin origin of pangere in impact is unsettled, so any offered root is a reconstruction.","cn":"来源不确定（首见年代）：这一确切短语的最早书证尚无定论；impact 中 pangere 在拉丁语之前的来源亦未确定，任何提出的词根都是重构形式。"}]},"similar":{"note":{"en":"Group one holds documents and procedures often mistaken for the assessment; group two holds the general words for judging something.","cn":"第一组是常被误当作评估本身的文件与程序；第二组是表示「判断某物」的通用词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"impact statement","ipa":"/ˈɪmpækt ˈsteɪtmənt/","tag":"the document","definition":"The written report produced by the assessment; the assessment is the study, the statement is the paper filed.","definitionCN":"评估所产生的书面报告；assessment 是研究，statement 是提交的那份文件。"},{"word":"environmental audit","ipa":"/ɪnˌvaɪrənˈmentl ˈɔːdɪt/","tag":"checks the present","definition":"An inspection of existing performance against rules; an audit looks backward, an impact assessment looks forward.","definitionCN":"对现有表现是否符合规则的检查；审计向后看，影响评估向前看。"},{"word":"risk assessment","ipa":"/rɪsk əˈsesmənt/","tag":"hazard probability","definition":"A study of how likely and how severe a harm is; impact assessment asks what will change, risk assessment asks how likely the change is.","definitionCN":"研究危害发生的可能性与严重度；影响评估问「会改变什么」，风险评估问「改变有多可能」。"},{"word":"impact analysis","ipa":"/ˈɪmpækt əˈnæləsɪs/","tag":"method, not filing","definition":"The analytic work of tracing effects; it stresses the modelling, while assessment stresses the formal judgement.","definitionCN":"追踪效果的分析工作；强调建模，而 assessment 强调正式判断。"}]},{"heading":"NEAR MEANING","entries":[{"word":"appraisal","ipa":"/əˈpreɪzl/","tag":"value judgement","definition":"From Old French apriser 'to set a price': an estimate of worth, often of a person or a property.","definitionCN":"来自古法语 apriser「定价」：对价值作出估计，常用于人或房产。"},{"word":"evaluation","ipa":"/ˌiːvæljuˈeɪʃn/","tag":"judging results","definition":"From Latin valere 'to be worth': judging the value of something already done, rather than predicting.","definitionCN":"来自拉丁 valere「有价值」：对已完成之事评定价值，而非预测。"},{"word":"review","ipa":"/rɪˈvjuː/","tag":"looking again","definition":"A second look at a proposal or a record; it may be less quantitative and less predictive than an assessment.","definitionCN":"对提案或记录的再次查看；量化与预测程度通常低于 assessment。"},{"word":"cost-benefit analysis","ipa":"/ˌkɒst ˈbenɪfɪt əˈnæləsɪs/","tag":"money frame","definition":"A comparison of monetised gains and losses; it is one method an assessment may use, not a synonym.","definitionCN":"对货币化收益与损失作比较；它是评估可采用的一种方法，并非同义词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real set phrases and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Assess is 'to sit beside' a case as a judge does, so an assessment is a weighing before a verdict.","cn":"assess 是像法官一样「坐在案件旁」，所以 assessment 是判决前的权衡。"},{"en":"The abbreviation EIA stands for environmental impact assessment.","cn":"缩写 EIA 就是 environmental impact assessment。"},{"en":"Fixed phrases mark the branches: social, health, regulatory, strategic impact assessment.","cn":"固定搭配标出分支：社会、健康、监管、战略影响评估。"},{"en":"An impact statement is the document; the assessment is the study behind it.","cn":"impact statement 是文件；assessment 是背后的研究。"},{"en":"Impact keeps its collision image from Latin impingere, to strike against.","cn":"impact 保留了拉丁 impingere「撞向」的碰撞意象。"}],"abstract":[{"en":"Picture a judicial bench placed beside a map, not in front of it.","cn":"想象审判席被摆在图旁，而不是图的前方。"},{"en":"Picture a spreadsheet where each work step is scored in a separate column.","cn":"想象一张表格，每道工序在各自一列里被打分。"},{"en":"Picture a weather forecast written before the journey begins.","cn":"想象旅程开始前写好的天气预测。"}]},"examples":[{"en":"The impact assessment ran to four volumes and changed the route.","cn":"影响评估长达四卷，并改变了路线。"},{"en":"Without a social impact assessment, resettlement plans rarely survive contact with villagers.","cn":"没有社会影响评估，移民安置计划很少经得起与村民的接触。"},{"en":"A strategic impact assessment can rule out a plan before any project is designed.","cn":"战略影响评估能在任何项目设计之前否掉一份规划。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「impact（撞击）+ assessment（坐在旁边评判）」——先算清后果再开工 → 影响评估","word":"impact assessment"},"root":"impact 来自拉丁 impingere「撞向」（in- + pangere 钉入）；assessment 来自拉丁 assidere「坐在旁边」（ad- + sedere 坐），中世纪转为「核定税额」。pangere 更深来源不确定。英语短语 impact assessment。","sensesIntro":{"en":"Eight meanings follow one method from the general forecast to the environmental procedure, then to its social, health, regulatory, strategic and technological branches, and finally to informal weighing.","cn":"八个义项沿同一方法展开：从一般预测到环境程序，再到社会、健康、监管、战略、技术各分支，最后是非正式的权衡。"},"semanticMap":{"core":{"en":"CORE IMAGE: a judge's bench set beside a project map, scoring every column before work starts.","cn":"核心意象：审判席摆在项目图旁，开工前逐栏打分。"},"chain":["SIT BESIDE","WEIGH AHEAD","ENVIRONMENTAL FILING","SOCIAL AND HEALTH","RULES AND PLANS","INFORMAL TEST"],"branches":[{"senses":"S1 · S8","en":"WEIGHING ITSELF: formal or private, the act is a look at consequences before acting.","cn":"权衡本身：正式或私下，动作都是在行动之前先看后果。"},{"senses":"S2 · S3","en":"TWO DIRECTIONS: the same method runs from land to people.","cn":"两个方向：同一方法从土地延伸到人。"},{"senses":"S4","en":"BODY ON THE TABLE: health is scored in the same grid as water and soil.","cn":"把身体放上桌面：健康与水、土壤在同一张格子里被打分。"},{"senses":"S5 · S6","en":"LEVELS UP: rules and plans need review before individual projects exist.","cn":"层级上移：规章与规划需要在单个项目出现之前就接受审查。"},{"senses":"S7","en":"NEW OBJECTS: when the thing predicted is a technology, the phrase follows the innovation.","cn":"新对象：当预测对象是技术时，这个短语便跟着创新走。"}]},"affixes":{"intro":{"en":"Both halves are Latin-derived and still productive: assessment from assidere, impact from impingere.","cn":"两半都是拉丁来源且仍有构词力：assessment 出自 assidere，impact 出自 impingere。"},"latinIntro":{"en":"Latin sedere builds assess, assessment, session and sediment; Latin pangere builds impact, impinge and compact.","cn":"拉丁 sedere 构成 assess、assessment、session 与 sediment；拉丁 pangere 构成 impact、impinge 与 compact。"},"items":[{"word":"ad-","structure":"ad- (Latin prefix, 'to, beside')","meaning":"to; beside","meaningCN":"朝向；在旁边","example":"The prefix places the judge beside the case.","exampleCN":"前缀把法官置于案件旁。"},{"word":"sedere","structure":"sedere, sedi, sessum (verb, second conjugation)","meaning":"to sit","meaningCN":"坐","example":"The court sits in the morning.","exampleCN":"法庭上午开庭。"},{"word":"assidere","structure":"ad- + sedere","meaning":"to sit beside, assist as a judge","meaningCN":"坐在旁边；作为法官审理","example":"The assessor sat beside the sheriff.","exampleCN":"估税员坐在郡长身旁。"},{"word":"assess","structure":"assidere through Old French","meaning":"to fix a value or tax","meaningCN":"评估价值；核定税额","example":"They assessed the land at a lower value.","exampleCN":"他们把这块地估得更低。"},{"word":"assessment","structure":"assess + -ment (result)","meaning":"a judgement or valuation","meaningCN":"评估；评定","example":"The assessment was published in June.","exampleCN":"评估报告于六月公布。"},{"word":"impact","structure":"impingere through impactus","meaning":"a collision or strong effect","meaningCN":"碰撞；强烈影响","example":"The impact was felt downstream.","exampleCN":"影响在下游被感受到。"},{"word":"session","structure":"sedere + -ion (a sitting)","meaning":"a period of sitting","meaningCN":"会期；开庭期","example":"The session lasted two hours.","exampleCN":"会期持续两小时。"},{"word":"sediment","structure":"sedere + -ment (that which settles)","meaning":"material that sits at the bottom","meaningCN":"沉积物","example":"The sediment buried the gravel.","exampleCN":"泥沙埋住了砾石。"}],"latinEntries":[{"word":"sedere","structure":"sedere, sedi, sessum (verb, second conjugation)","meaning":"to sit, to remain seated","meaningCN":"坐；就座"},{"word":"assidere","structure":"assidere, assedi, assessum (verb, third conjugation)","meaning":"to sit beside, assist in judging","meaningCN":"坐在旁边；协助审理"},{"word":"impingere","structure":"impingere, impingi, impactum (verb, third conjugation)","meaning":"to strike against","meaningCN":"撞上"}]}},{"word":"ecosystem management","ipa_uk":"/ˈiːkəsɪstəm məˈnædʒmənt/","ipa_us":"/ˈiːkoʊsɪstəm məˈnædʒmənt/","definition_zh":"生态系统管理；以整个生态系统为对象、兼顾生态过程与人类利用的长期管理","definition_en":"the long-term management of a whole ecosystem, balancing ecological processes with human use","core_image":"一只手在流域图上同时按住三条线：水位、鱼群与采伐计划，让它们留在同一张图上","scene":"林务局不再按单块林地排产，而是把河流、鱼群与采伐年限放进同一份计划，转向生态系统管理。The forestry bureau stopped scheduling one stand at a time and put the river, the fish runs and the cutting cycle into a single plan, shifting to ecosystem management.","sceneCN":"这里 ecosystem management 指「以整个生态系统为单位、兼顾过程与利用的管理方式」（第 1 个义项：整体系统管理）；句意为林务局不再按单块林地排产，而是把河流、鱼群与采伐年限放进同一份计划，转向生态系统管理。可辨识物件：流域图、三条并置的曲线、采伐标记、鱼群计数。","pos":[{"tag":"n.","zh":"生态系统管理（不可数，作为管理领域使用）"}],"collocations":[{"phrase":"ecosystem management plan","zh":"生态系统管理计划"},{"phrase":"ecosystem management approach","zh":"生态系统管理方法"},{"phrase":"ecosystem management strategy","zh":"生态系统管理策略"},{"phrase":"forest ecosystem management","zh":"森林生态系统管理"},{"phrase":"adaptive ecosystem management","zh":"适应性生态系统管理"},{"phrase":"ecosystem management goals","zh":"生态系统管理目标"}],"forms":[{"label":"通常无复数（不可数）","form":"ecosystem management"},{"label":"相关名词（生态系统）","form":"ecosystem（生态系统）"},{"label":"相关名词（管理）","form":"management（管理）"},{"label":"相关动词（管理）","form":"manage（管理；经营）"},{"label":"相关名词（管理者）","form":"manager（管理者）"},{"label":"近义说法（基于生态系统的管理）","form":"ecosystem-based management（基于生态系统的管理）"}],"derivatives":[{"word":"ecosystem","pos":"n.","zh":"生态系统"},{"word":"ecological","pos":"adj.","zh":"生态的；生态学的"},{"word":"ecology","pos":"n.","zh":"生态学；生态"},{"word":"manage","pos":"v.","zh":"管理；经营；勉力做到"},{"word":"management","pos":"n.","zh":"管理；管理层"}],"senses":[{"no":"01","title":"Managing a whole system, not a yield","titleCN":"管理整个系统而非单一产出","definition":"planning for the whole ecosystem, including soils, water, plants, animals and people, instead of maximising one harvest","definitionCN":"以整个生态系统为对象作规划，包括土壤、水、植物、动物与人，而非最大化单一收获","example":"Ecosystem management replaced the old policy of harvesting one species at a time.","exampleCN":"生态系统管理取代了逐种采伐的旧政策。","why":"the phrase was coined to correct single-species or single-use management, so its core is the scale of the object.","whyCN":"这个短语是为纠正单物种、单用途管理而造的，所以核心在于对象尺度。"},{"no":"02","title":"Adaptive management with monitoring","titleCN":"带监测回路的适应性管理","definition":"a cycling practice in which actions are monitored and revised as the system responds","definitionCN":"对行动加以监测、并随系统反应而修正的循环式做法","example":"Adaptive ecosystem management treats each burn as an experiment with a measured result.","exampleCN":"适应性生态系统管理把每次计划烧除当作有测量结果的实验。","why":"ecosystems cannot be predicted exactly, so the method had to build learning into the management loop.","whyCN":"生态系统无法被精确预测，方法因此必须把学习装进管理回路。"},{"no":"03","title":"Managing a protected area","titleCN":"管理保护地","definition":"day-to-day stewardship of a reserve's habitats, visitors and boundaries","definitionCN":"对保护区栖息地、访客与边界的日常管护","example":"The reserve's ecosystem management plan closes the dunes during nesting season.","exampleCN":"保护区的生态系统管理计划在筑巢季封闭沙丘。","why":"the abstract approach becomes concrete in a plan with zones, seasons and staff duties.","whyCN":"抽象方法在一份含分区、季节与岗位职责的计划中变得具体。"},{"no":"04","title":"Watershed-scale planning","titleCN":"流域尺度的规划","definition":"management organised around a drainage basin so that upstream actions are judged by downstream effects","definitionCN":"以流域为单位组织管理，使上游行动按下游效果来评判","example":"Watershed ecosystem management linked the turbine release to the spawning beds below.","exampleCN":"流域生态系统管理把水轮机放水量与下游产卵床联系起来。","why":"water crosses boundaries, so the watershed became the natural unit for judging consequences.","whyCN":"水会跨越边界，流域因此成为评判后果的天然单位。"},{"no":"05","title":"Forest ecosystem management","titleCN":"森林生态系统管理","definition":"managing a forest for structure, age classes and wildlife rather than only for timber volume","definitionCN":"按结构、龄级与野生动物管理森林，而非只看木材蓄积","example":"Forest ecosystem management left snags standing for nesting owls.","exampleCN":"森林生态系统管理留下枯立木供猫头鹰筑巢。","why":"forestry was the first field to adopt the phrase at scale, because timber alone had simplified whole landscapes.","whyCN":"林业是最先大规模采用该短语的领域，因为只看木材曾把整片景观简化。"},{"no":"06","title":"Fisheries management by ecosystem","titleCN":"基于生态系统的渔业管理","definition":"setting catch rules by the food web and habitat rather than by a single stock's maximum yield","definitionCN":"按食物网与栖息地设定捕捞规则，而非按单一种群的最大产量","example":"Ecosystem management for the bay protects the seagrass that the fry depend on.","exampleCN":"海湾的生态系统管理保护幼鱼赖以生存的海草。","why":"fisheries learned that a stock collapses when its habitat and prey are ignored, so the unit widened.","whyCN":"渔业发现，忽视栖息地与猎物，种群就会崩溃，管理单位因此扩大。"},{"no":"07","title":"Ecosystem-based climate adaptation","titleCN":"基于生态系统的气候适应","definition":"using ecosystem processes, such as mangroves or floodplain storage, to buffer climate impacts","definitionCN":"利用红树林或泛滥平原蓄水等生态过程缓冲气候影响","example":"Ecosystem management of the delta doubled as storm protection.","exampleCN":"三角洲的生态系统管理同时起到了风暴防护作用。","why":"climate policy borrowed the approach once intact systems proved cheaper than built defences.","whyCN":"当完整生态系统被证明比人工防御更便宜时，气候政策借用了这一做法。"},{"no":"08","title":"Abstract: holistic governance of complexity","titleCN":"抽象义：对复杂系统的整体治理","definition":"any effort to govern a complex system as a whole rather than in separate pieces","definitionCN":"任何把复杂系统作为整体、而非分片治理的努力","example":"The agency applied ecosystem management to its own overlapping programmes.","exampleCN":"该机构把生态系统管理的思路用到了自家相互重叠的项目上。","why":"the abstraction keeps the shape of the approach, whole system and feedback, while dropping the biology.","whyCN":"抽象用法保留方法的形状，即整体系统与反馈，却丢掉了生物学内容。"}],"etymology":{"intro":{"en":"Ecosystem is a twentieth-century coinage from Greek oikos 'house' and systema 'organised whole'; management comes from Latin manus 'hand' through Italian horse-handling. The fixed phrase dates from late twentieth-century conservation. Dates are approximate.","cn":"ecosystem 是 20 世纪的新造词，由希腊 oikos「家宅」与 systema「有组织的整体」构成；management 则经意大利语驯马用语来自拉丁 manus「手」。这个固定短语形成于 20 世纪后期的保育实践。年代均为约数。"},"items":[{"era":"GREEK OIKOS","en":"Oikos meant 'house, household'; its deeper origin is not established, and the usual link to a root meaning 'to inhabit' is a hypothesis.","cn":"oikos 意为「家宅、家户」；其更远来源未得到证明，通常把它与表示「居住」的词根相联系，那只是假说。"},{"era":"GREEK SYSTEMA","en":"Syn- 'together' plus histanai 'to stand' gave systema, a whole composed of parts standing together.","cn":"syn-「一起」加 histanai「站立」构成 systema，即由各个部分共同立起而成的整体。"},{"era":"ENGLISH ECOSYSTEM","en":"Ecosystem was coined in the 1930s for the physical system of organisms together with their surroundings; it was formed by analogy with terms already in use.","cn":"ecosystem 在 20 世纪 30 年代被造出，指生物与其周围环境的物理系统，构词方式仿照当时已有的类似术语。"},{"era":"LATIN MANUS TO ITALIAN","en":"Latin manus 'hand' gave Italian maneggiare 'to handle, to train a horse', and French manège carried the horse-training image into English.","cn":"拉丁 manus「手」构成意大利语 maneggiare「操作、驯马」，法语 manège 又把驯马意象带入英语。"},{"era":"MANAGEMENT","en":"Management first meant the handling and control of horses, then of households and enterprises, and finally of natural resources.","cn":"management 先指对马匹的操控，继而指对家户与企业的经营，最后用于自然资源。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): no single earliest citation for the fixed phrase ecosystem management is agreed, and the deeper origin of oikos is unsettled, so any reconstructed root is a hypothesis.","cn":"来源不确定（首见年代）：ecosystem management 这一固定短语的最早书证没有公认答案；oikos 的更深来源亦未定，任何重构词根都是假说。"}]},"similar":{"note":{"en":"Group one holds ecology words often confused with ecosystem; group two holds neighbouring management approaches.","cn":"第一组是常与 ecosystem 混淆的生态类词；第二组是相邻的管理思路。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ecosystem","ipa":"/ˈiːkəsɪstəm/","tag":"the object, not the practice","definition":"The community of organisms plus their physical setting; ecosystem management is what people do to it.","definitionCN":"生物群落加其物理环境；ecosystem management 则是人对它做的事。"},{"word":"ecology","ipa":"/iˈkɒlədʒi/","tag":"the science","definition":"The study of those relationships; it names a discipline, not an area or a practice.","definitionCN":"研究这些关系的学科；它指一门学问，而非一片区域或一套做法。"},{"word":"habitat","ipa":"/ˈhæbɪtæt/","tag":"one species' setting","definition":"The place where a particular species lives; it is narrower than the whole ecosystem.","definitionCN":"某一特定物种生活的地方；范围比整个生态系统窄。"},{"word":"biome","ipa":"/ˈbaɪəʊm/","tag":"climate-scale zone","definition":"A large region defined by climate and vegetation, larger in scale than a managed ecosystem.","definitionCN":"按气候与植被划分的大区域，尺度大于被管理的生态系统。"}]},{"heading":"NEAR MEANING","entries":[{"word":"conservation","ipa":"/ˌkɒnsəˈveɪʃn/","tag":"protect from loss","definition":"Keeping species and places from being lost; it stresses protection, while ecosystem management also plans use.","definitionCN":"使物种与地点免于消失；强调保护，而生态系统管理还规划利用。"},{"word":"stewardship","ipa":"/ˈstjuːədʃɪp/","tag":"moral care","definition":"The responsible care of something entrusted to you; it adds an ethical tone that the technical phrase lacks.","definitionCN":"对所托付之物的负责照管；带有技术短语所缺的伦理色彩。"},{"word":"ecosystem-based management","ipa":"/ˈiːkəsɪstəm beɪst məˈnædʒmənt/","tag":"the narrower label","definition":"A near-synonym stressing that boundaries and rules follow ecological units; it is common in fisheries and oceans.","definitionCN":"近义说法，强调边界与规则依生态单元划定，常用于渔业与海洋领域。"},{"word":"resource management","ipa":"/rɪˈsɔːs məˈnædʒmənt/","tag":"use-oriented","definition":"Managing a resource for sustained yield; it starts from human demand, whereas ecosystem management starts from the system.","definitionCN":"为持续产出而管理资源；它从人的需求出发，生态系统管理则从系统出发。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real set phrases and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Oikos means house, so ecology is the study of the household of nature.","cn":"oikos 意为家宅，所以 ecology 是研究自然这个大家庭的学问。"},{"en":"Systema is parts standing together, which is why ecosystem stresses the whole.","cn":"systema 是各部分共同立起，因此 ecosystem 强调整体。"},{"en":"Management came from handling horses, so the phrase keeps the image of guiding something alive.","cn":"management 源自驯马，因此这个短语保留了「引导活物」的意象。"},{"en":"Fixed phrases mark the fields: forest, watershed, fisheries ecosystem management.","cn":"固定搭配标出领域：森林、流域、渔业生态系统管理。"},{"en":"Keep ecosystem and ecology apart: one is the object, the other the science.","cn":"把 ecosystem 与 ecology 分开：一个是对象，一个是学科。"}],"abstract":[{"en":"Picture one hand holding three reins at once.","cn":"想象一只手同时握住三条缰绳。"},{"en":"Picture a map where the river, the fish and the saw are drawn on one sheet.","cn":"想象一张图，河流、鱼与锯子画在同一页上。"},{"en":"Picture a gauge that adjusts itself after each reading.","cn":"想象一只表，每次读数之后自行调整。"}]},"examples":[{"en":"Ecosystem management moved forestry from cutting cycles to habitat structure.","cn":"生态系统管理把林业从采伐周期转向栖息地结构。"},{"en":"The delta's ecosystem management was cheaper than raising the seawall.","cn":"三角洲的生态系统管理比加高海堤更便宜。"},{"en":"Adaptive ecosystem management treats every intervention as a test with a result.","cn":"适应性生态系统管理把每次干预当作有结果的检验。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「eco（家）+ system（系统）+ management（管理）」——把整个自然之家一起管 → 生态系统管理","word":"ecosystem management"},"root":"ecosystem = 希腊 oikos「家宅」+ systema「有组织的整体」；management 经意大利语 maneggiare「操作、驯马」来自拉丁 manus「手」。oikos 与 manus 的更深来源均不确定。英语短语 ecosystem management。","sensesIntro":{"en":"Eight meanings follow one approach from whole-system planning to adaptive loops, reserves, watersheds, forests, fisheries, climate use and finally to any holistic governance.","cn":"八个义项沿同一思路展开：从整体规划到适应回路、保护地、流域、森林、渔业、气候用途，最后是任何整体治理。"},"semanticMap":{"core":{"en":"CORE IMAGE: one hand holds three reins on a single map.","cn":"核心意象：一只手在同一张图上握住三条缰绳。"},"chain":["WHOLE HOUSE","PARTS STANDING","HANDLING","MONITORING LOOP","BOUNDARY UNIT","HOLISTIC RULE"],"branches":[{"senses":"S1 · S4","en":"UNIT OF CARE: the object is a system with a boundary, whether a reserve or a watershed.","cn":"管护单位：对象是带边界的系统，无论是保护地还是流域。"},{"senses":"S2","en":"LEARNING LOOP: monitoring turns each action into an experiment.","cn":"学习回路：监测把每次行动变成一次实验。"},{"senses":"S3 · S5","en":"LAND AND TREES: concrete plans assign zones, seasons and snags.","cn":"土地与树木：具体计划分配分区、季节与枯立木。"},{"senses":"S6 · S7","en":"WATER AND CLIMATE: food webs and storm buffers extend the same logic.","cn":"水与气候：食物网与风暴缓冲延续同一逻辑。"},{"senses":"S8","en":"BEYOND BIOLOGY: the approach survives as a way to govern any complex system.","cn":"超越生物学：这一思路存续为治理任何复杂系统的方式。"}]},"affixes":{"intro":{"en":"The phrase is a modern compound of a Greek-derived noun and a Latin-derived one, and both halves remain productive.","cn":"这个短语是希腊来源名词与拉丁来源名词的现代复合，两半都仍有构词力。"},"latinIntro":{"en":"Greek oikos builds ecology, ecologist and economy; Latin manus builds manage, manual and manipulate.","cn":"希腊 oikos 构成 ecology、ecologist 与 economy；拉丁 manus 构成 manage、manual 与 manipulate。"},"items":[{"word":"oikos","structure":"oikos (Greek noun, 'house, household')","meaning":"house; household","meaningCN":"家宅；家户","example":"The root image is a household.","exampleCN":"词根意象是一个家户。"},{"word":"systema","structure":"syn- + histanai (Greek, 'stand together')","meaning":"an organised whole","meaningCN":"有组织的整体","example":"The parts form one systema.","exampleCN":"各部分构成一个整体。"},{"word":"ecosystem","structure":"oikos + systema (coined term)","meaning":"organisms plus their setting","meaningCN":"生物及其环境","example":"The marsh is a young ecosystem.","exampleCN":"这片沼泽是一个年轻的生态系统。"},{"word":"ecology","structure":"oikos + -logia (study of)","meaning":"the study of such systems","meaningCN":"研究此类系统的学科","example":"Ecology began with plant surveys.","exampleCN":"生态学始于植物调查。"},{"word":"manus","structure":"manus, manus (f., fourth declension)","meaning":"hand","meaningCN":"手","example":"The root image is a hand on the reins.","exampleCN":"词根意象是手握缰绳。"},{"word":"maneggiare","structure":"Italian, 'to handle, train a horse'","meaning":"to handle","meaningCN":"操作；驯练","example":"The rider handled the horse.","exampleCN":"骑手驯练这匹马。"},{"word":"manage","structure":"maneggiare through French","meaning":"to guide and control","meaningCN":"引导并控制","example":"They manage the reserve.","exampleCN":"他们管理这片保护区。"},{"word":"management","structure":"manage + -ment (action)","meaning":"the act of guiding","meaningCN":"管理（动作）","example":"Management took a decade to show results.","exampleCN":"管理花了十年才见效。"},{"word":"economy","structure":"oikos + nomos (household rule)","meaning":"the management of a household","meaningCN":"家户的经营","example":"Economy began as household rule.","exampleCN":"economy 最初指家户管理。"}],"latinEntries":[{"word":"manus","structure":"manus, manus (f., fourth declension)","meaning":"hand","meaningCN":"手"},{"word":"maneggiare","structure":"maneggiare (Italian verb, from manus)","meaning":"to handle, to train a horse","meaningCN":"操作；驯马"}]}},{"word":"history","ipa_uk":"/ˈhɪstri/","ipa_us":"/ˈhɪstri/","definition_zh":"历史；历史学；一段过往经历；病史；（事物的）沿革记录","definition_en":"the study, record or remembered account of past events, especially of human affairs","core_image":"一间档案室里，纸页按年份排成长排，窗外的街景却在不断变化","scene":"考古队在城墙下挖出层叠的灶台与钱币，这些遗存让这座城的记载提前了三百年，改写本地历史。The excavation team found stacked hearths and coins beneath the city wall, remains that pushed the town's written record back three centuries and rewrote its history.","sceneCN":"这里 history 指「关于过去事件的记载与叙述」（第 1 个义项：对过往的系统记录）；句意为考古队在城墙下挖出层叠灶台与钱币，这些遗存让该城记载提前三百年，改写了本地历史。可辨识物件：层叠灶台、古钱币、城墙剖面、年份标签。","pos":[{"tag":"n.","zh":"历史；历史学；经历；病史（可数指一段经历或一部史书）"}],"collocations":[{"phrase":"in history","zh":"在历史上"},{"phrase":"the history of","zh":"……的历史"},{"phrase":"oral history","zh":"口述史"},{"phrase":"medical history","zh":"病史"},{"phrase":"natural history","zh":"博物学；自然史"},{"phrase":"make history","zh":"创造历史；载入史册"}],"forms":[{"label":"复数","form":"histories"},{"label":"形容词（有历史意义的）","form":"historic（有历史意义的）"},{"label":"形容词（历史的；史学的）","form":"historical（历史的）"},{"label":"名词（历史学家）","form":"historian（历史学家）"},{"label":"副词（历史上地）","form":"historically（历史上地）"},{"label":"名词（史学史；编史学）","form":"historiography（编史学）"}],"derivatives":[{"word":"historian","pos":"n.","zh":"历史学家"},{"word":"historic","pos":"adj.","zh":"有历史意义的；历史性的"},{"word":"historical","pos":"adj.","zh":"历史的；史学的"},{"word":"historically","pos":"adv.","zh":"历史上；从历史角度"},{"word":"historiography","pos":"n.","zh":"编史学；史学史"}],"senses":[{"no":"01","title":"The recorded past of human affairs","titleCN":"对人类过往的系统记录","definition":"the whole body of past events as recorded, especially those of people and societies","definitionCN":"被记录下来的全部过往事件，尤其是人与社会的经历","example":"The town's history begins with a ferry crossing and a salt tax.","exampleCN":"这座城的历史始于一处渡口和一笔盐税。","why":"the Greek word meant inquiry, so history is first the result of asking, then the record that answers.","whyCN":"希腊原词意为「探究」，因此 history 先是提问的结果，再是回答这问题的记录。"},{"no":"02","title":"The discipline that studies the past","titleCN":"研究过去的学科","definition":"the academic discipline that selects, checks and interprets evidence about the past","definitionCN":"选择、核验并解释过去证据的学术学科","example":"History became a university subject with its own methods in the nineteenth century.","exampleCN":"历史学在 19 世纪成为拥有自身方法的大学学科。","why":"once inquiry acquired rules of evidence and training, the word named a profession as well as a record.","whyCN":"当探究有了证据规则与训练体系，这个词就既指记录，也指一门专业。"},{"no":"03","title":"A written narrative of events","titleCN":"成文的史书或叙述","definition":"a book or account that arranges past events into an ordered narrative","definitionCN":"把过往事件编排为有序叙述的书或记述","example":"She wrote a history of the harbour that reads like a novel.","exampleCN":"她写了一部读起来像小说的港口史。","why":"the oldest English sense was simply 'a story', and a written history is still a shaped narrative.","whyCN":"英语中最早的义项就是「故事」，而一部史书至今仍是被塑形的叙述。"},{"no":"04","title":"A person's or thing's past course","titleCN":"人或事物的过往经历","definition":"the sequence of events that led to someone's or something's present condition","definitionCN":"导致某人或某物当前状况的一系列过往事件","example":"The building has a history of leaks and repairs.","exampleCN":"这栋楼有一连串漏水和修补的经历。","why":"the word scales down from whole societies to a single object, because any object also has a course of events.","whyCN":"这个词从整个社会缩小到单个物件，因为任何物件也都有自己的事件序列。"},{"no":"05","title":"A patient's medical record","titleCN":"患者的病史","definition":"the record of a person's past illnesses, treatments and family conditions","definitionCN":"某人既往疾病、治疗与家族情况的记录","example":"The doctor asked about his family history of heart disease.","exampleCN":"医生询问他家族的心脏病史。","why":"medicine borrowed the word for the case narrative a doctor takes down, in the same sense of an ordered past.","whyCN":"医学借用这个词指医生记下的病例叙述，仍是「有序的过去」这一层意思。"},{"no":"06","title":"Natural history","titleCN":"自然史与博物学","definition":"the study and record of plants, animals and minerals, including their deep past","definitionCN":"对植物、动物与矿物的研究与记录，包括其深远过去","example":"Natural history museums preserve specimens that document extinct species.","exampleCN":"自然史博物馆保存着记录已灭绝物种的标本。","why":"the phrase was extended from human affairs to living things once naturalists began recording change over time.","whyCN":"当博物学者开始记录随时间发生的变化，这个短语便从人类事务扩展到生物。"},{"no":"07","title":"A track record of performance","titleCN":"表现记录；往绩","definition":"the known record of how something has performed, used to judge what it will do next","definitionCN":"某事物以往表现的已知记录，用以判断其下一步表现","example":"The fund has a history of steady returns in bad years.","exampleCN":"这只基金在坏年份里有着稳定回报的往绩。","why":"the commercial use treats the past as evidence for the future, which is the same logic as historical inference.","whyCN":"商业用法把过去当作未来的证据，这与史学推论是同一套逻辑。"},{"no":"08","title":"Abstract: the remembered past itself","titleCN":"抽象义：被记忆的过去本身","definition":"the past as it is remembered, contested and used by a community in the present","definitionCN":"被当下群体记忆、争夺与使用的那个过去","example":"The two villages tell different histories of the same flood.","exampleCN":"两个村庄对同一场洪水讲述着不同的历史。","why":"the abstract use stresses that history is carried and argued over, not merely stored.","whyCN":"抽象用法强调历史是被携带、被争辩的，而不只是被存放的。"}],"etymology":{"intro":{"en":"History comes from Greek historia 'inquiry, knowledge gained by inquiry', from histor 'one who knows, witness', generally linked to idein 'to see'. It entered English through Latin and French, first meaning 'story'. Dates are approximate.","cn":"history 来自希腊 historia「探究、经由探究所得的知识」，其词源 histor 意为「知情者、见证人」，一般与 idein「看见」相联系。它经拉丁语与法语进入英语，最初意为「故事」。年代均为约数。"},"items":[{"era":"GREEK HISTOR","en":"Histor meant 'witness, one who knows'; it is generally taken to continue a root meaning 'to see, to know', the same root behind English wit.","cn":"histor 意为「见证人、知情者」；一般被认为延续了表示「看见、知道」的词根，英语 wit 也出于同一词根。"},{"era":"GREEK HISTORIA","en":"Historia was 'inquiry, investigation, the knowledge so gained', the word Herodotus used for his own research.","cn":"historia 意为「探究、调查及由此获得的知识」，希罗多德就用这个词称呼自己的研究。"},{"era":"LATIN HISTORIA","en":"Latin historia kept both the inquiry and the written account, and the account sense grew stronger in later use.","cn":"拉丁 historia 同时保留「探究」与「成文记述」，在后世用法中记述义渐强。"},{"era":"FRENCH AND ENGLISH","en":"Old French historie brought the word into English in the thirteenth century as 'a story, a narrative', whether true or not.","cn":"古法语 historie 于 13 世纪把词带入英语，意为「故事、叙述」，无论真假。"},{"era":"MODERN DISCIPLINE","en":"By the nineteenth century history meant the professional study of past societies, with archives, seminars and source criticism.","cn":"到 19 世纪，history 指对过往社会的专业研究，配有档案、研讨课与史料批判。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the exact date when 'the past events themselves' replaced 'a story' as the dominant sense is not fixed, so the chronology given here is approximate.","cn":"来源不确定（首见年代）：泛指「过去事件本身」取代「故事」成为主要义项的确切年代尚无定论，此处给出的时间线为约数。"}]},"similar":{"note":{"en":"Group one holds words that look like history but name a different thing; group two holds the forms in which the past is written down.","cn":"第一组是外形像 history、却指别的事物的词；第二组是过去被书写下来的形态。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"story","ipa":"/ˈstɔːri/","tag":"the oldest sense","definition":"From Old French estorie, the same source as history: a narrative that may be true or invented, which is exactly what history once meant.","definitionCN":"来自古法语 estorie，与 history 同源：可真可虚构的叙述，而这正是 history 最初的义项。"},{"word":"historic","ipa":"/hɪˈstɒrɪk/","tag":"momentous, not past","definition":"An adjective for an event important enough to enter history, not for anything old or past.","definitionCN":"形容词，指重要到足以载入史册的事件，而非任何古老或过去之物。"},{"word":"historical","ipa":"/hɪˈstɒrɪkl/","tag":"relating to the past","definition":"An adjective meaning connected with past events or with the study of them, the neutral partner of history.","definitionCN":"形容词，意为与过去事件或史学研究有关，是 history 的中性搭配词。"},{"word":"historiography","ipa":"/hɪˌstɒriˈɒɡrəfi/","tag":"writing of history","definition":"The study of how histories are written, not the events themselves.","definitionCN":"研究历史如何被书写，而不是研究事件本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"chronicle","ipa":"/ˈkrɒnɪkl/","tag":"year-by-year record","definition":"From Greek chronos 'time': a record arranged strictly by date, with less interpretation than a history.","definitionCN":"来自希腊 chronos「时间」：严格按日期排列的记录，解释成分少于 history。"},{"word":"record","ipa":"/ˈrekɔːd/","tag":"the stored evidence","definition":"The raw stored evidence, such as files and registers; history is the interpretation built on such records.","definitionCN":"被保存的原始证据，如档案与登记册；history 是在这些记录之上建立的解释。"},{"word":"the past","ipa":"/ðə pɑːst/","tag":"everything before now","definition":"All that has happened; history is the part that has been selected, recorded and interpreted.","definitionCN":"一切已发生之事；history 只是其中被选择、记录与解释的部分。"},{"word":"archives","ipa":"/ˈɑːkaɪvz/","tag":"the place and papers","definition":"The stored documents and the place holding them; they are the raw material, not the account.","definitionCN":"被保存的文件与存放它们的场所；它们是原料，不是叙述。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real set phrases and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Greek historia means inquiry, so history is knowledge obtained by asking questions of evidence.","cn":"希腊 historia 意为探究，所以 history 是通过追问证据获得的知识。"},{"en":"Histor is the witness, one who knows, linked to the root for seeing.","cn":"histor 是见证人、知情者，与表示「看见」的词根相联系。"},{"en":"The oldest English sense was story, which is why a history can still be told as a narrative.","cn":"英语最早义项是 story，所以一部历史至今仍可作为叙述来讲。"},{"en":"Keep historic and historical apart: one means momentous, the other means relating to the past.","cn":"把 historic 与 historical 分开：一个指重大，一个指与过去有关。"},{"en":"Fixed phrases mark the branches: oral history, medical history, natural history.","cn":"固定搭配标出分支：口述史、病史、自然史。"}],"abstract":[{"en":"Picture shelves of paper ordered by year while the street outside keeps changing.","cn":"想象一排按年份排好的纸页，而窗外的街道不断变化。"},{"en":"Picture two villages telling the same flood in two different ways.","cn":"想象两个村庄用两种说法讲述同一场洪水。"},{"en":"Picture a ledger whose columns are evidence and whose margin is argument.","cn":"想象一本账簿，栏目是证据，页边是争论。"}]},"examples":[{"en":"The excavation rewrote the town's history and doubled its recorded age.","cn":"这次发掘改写了这座城的历史，使其有记载的年代翻了一倍。"},{"en":"History is taught as a set of arguments about evidence, not as a list of dates.","cn":"历史被作为一组关于证据的论证来教授，而不是一串日期。"},{"en":"The fund's history of steady returns attracted cautious investors.","cn":"这只基金稳定回报的往绩吸引了谨慎的投资者。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「his（他的）+ story（故事）」——他的故事写成书 → 历史","word":"history"},"root":"希腊 historia「探究、探究所得的知识」，出自 histor「见证人、知情者」，一般与 idein「看见」同根，再往上与印欧词根「看见、知道」相联系；英语 history 经拉丁 historia 与古法语 historie。更深来源不确定。","sensesIntro":{"en":"Eight meanings follow one word from the recorded past to the discipline, the written book, a personal course, a medical file, the natural world, a track record and finally the past as memory.","cn":"八个义项沿同一个词展开：从被记录的过去，到学科、史书、个人经历、病历、自然界、往绩，最后是作为记忆的过去。"},"semanticMap":{"core":{"en":"CORE IMAGE: papers ordered by year in a room while the street outside changes.","cn":"核心意象：一室之内纸页按年排好，窗外街景却在变化。"},"chain":["INQUIRY","WITNESS","RECORDED PAST","DISCIPLINE","WRITTEN ACCOUNT","REMEMBERED PAST"],"branches":[{"senses":"S1 · S3","en":"ASK AND WRITE: inquiry produces a record, and the record takes narrative shape.","cn":"追问与书写：探究产生记录，记录又成为叙述。"},{"senses":"S2","en":"PROFESSION: once evidence has rules, the word names a discipline and its training.","cn":"职业：证据一旦有了规则，这个词就指一门学科及其训练。"},{"senses":"S4 · S7","en":"SMALLER COURSES: a building or a fund also has a sequence that can be told and judged.","cn":"更小的历程：一栋楼或一只基金同样有可被讲述与评判的序列。"},{"senses":"S5 · S6","en":"BORROWED FIELDS: medicine and natural science keep the same ordered-past logic.","cn":"借用的领域：医学与自然科学保留了同一套「有序过去」逻辑。"},{"senses":"S8","en":"CONTESTED MEMORY: the past is carried and argued over, not merely shelved.","cn":"被争辩的记忆：过去是被携带与争论的，不只是被束之高阁。"}]},"affixes":{"intro":{"en":"History is a Greek noun in English dress; its root and endings also build historian, historic and historiography.","cn":"history 是披着英语外衣的希腊名词；其词根与词尾还构成 historian、historic 与 historiography。"},"latinIntro":{"en":"Latin historia gives history, historian and historiography; Greek histor and the ending -ia are the building blocks.","cn":"拉丁 historia 构成 history、historian 与 historiography；希腊 histor 与词尾 -ia 是构件。"},"items":[{"word":"histor","structure":"histor (Greek noun, 'witness, one who knows')","meaning":"witness; knower","meaningCN":"见证人；知情者","example":"The root names the one who was there.","exampleCN":"词根指在场的那个人。"},{"word":"historia","structure":"histor + -ia (abstract noun)","meaning":"inquiry; knowledge from inquiry","meaningCN":"探究；探究所得的知识","example":"Historia was the title of the first prose inquiry.","exampleCN":"historia 是第一部散文探究的标题。"},{"word":"-y","structure":"-ia through Latin and French -ie","meaning":"abstract noun ending","meaningCN":"抽象名词词尾","example":"history is historia in English form.","exampleCN":"history 就是 historia 的英语形态。"},{"word":"historian","structure":"history + -ian (person)","meaning":"one who writes history","meaningCN":"写历史的人","example":"The historian read the ledgers.","exampleCN":"历史学家读了账簿。"},{"word":"historic","structure":"historia + -ic (relating to)","meaning":"momentous, recorded","meaningCN":"重大的；载入史册的","example":"The signing was historic.","exampleCN":"那次签署具有历史意义。"},{"word":"historical","structure":"historic + -al (relating to)","meaning":"of the past or of history","meaningCN":"历史的；史学的","example":"Historical records are incomplete.","exampleCN":"历史记录并不完整。"},{"word":"historically","structure":"historical + -ly (adverb)","meaning":"in past times","meaningCN":"历史上地","example":"Historically, the river flooded each spring.","exampleCN":"历史上这条河每年春天泛滥。"},{"word":"historiography","structure":"history + -graphy (writing)","meaning":"the writing of history","meaningCN":"历史书写；编史学","example":"Historiography studies how accounts are made.","exampleCN":"编史学研究所史如何被写成。"},{"word":"prehistoric","structure":"pre- + historic","meaning":"before written records","meaningCN":"史前的","example":"Prehistoric tools lay in the cave.","exampleCN":"史前工具留在洞穴里。"}],"latinEntries":[{"word":"historia","structure":"historia, historiae (f., first declension)","meaning":"inquiry, narrative, history","meaningCN":"探究；叙述；历史"},{"word":"historicus","structure":"historicus, historica, historicum (adj.)","meaning":"of history, historical","meaningCN":"历史的"}]}},{"word":"historian","ipa_uk":"/hɪˈstɔːriən/","ipa_us":"/hɪˈstɔːriən/","definition_zh":"历史学家；史学研究者；编史者","definition_en":"a person who studies and writes about the past, especially by examining evidence","core_image":"一张堆满手稿的长桌，学者戴着薄手套比对两封字迹不同的信","scene":"为了弄清末代码头的归属，一位研究者花了十年翻阅港口账簿与地图，被同行称为严谨的历史学家。To settle who owned the old wharf, one researcher spent ten years reading port ledgers and maps, and colleagues called her a rigorous historian.","sceneCN":"这里 historian 指「以史料研究并书写过去的专业人员」（第 1 个义项：专业史学研究者）；句意为为了弄清末代码头归属，一位研究者花十年翻阅港口账簿与地图，被同行称为严谨的历史学家。可辨识物件：手稿长桌、薄手套、两封信、港口地图。","pos":[{"tag":"n.","zh":"历史学家；史学研究者（可数）"}],"collocations":[{"phrase":"a leading historian","zh":"一流历史学家"},{"phrase":"military historian","zh":"军事史学家"},{"phrase":"art historian","zh":"艺术史学家"},{"phrase":"official historian","zh":"官方史官；官方史学家"},{"phrase":"historian of science","zh":"科学史学家"},{"phrase":"local historian","zh":"地方史研究者"}],"forms":[{"label":"复数","form":"historians"},{"label":"名词（历史）","form":"history（历史）"},{"label":"形容词（历史的）","form":"historical（历史的）"},{"label":"形容词（有历史意义的）","form":"historic（有历史意义的）"},{"label":"名词（编史学）","form":"historiography（编史学）"},{"label":"副词（历史上地）","form":"historically（历史上地）"}],"derivatives":[{"word":"history","pos":"n.","zh":"历史；历史学"},{"word":"historical","pos":"adj.","zh":"历史的；史学的"},{"word":"historic","pos":"adj.","zh":"有历史意义的"},{"word":"historiography","pos":"n.","zh":"编史学；史学史"},{"word":"historiographer","pos":"n.","zh":"编史者；官方史官"}],"senses":[{"no":"01","title":"A professional student of the past","titleCN":"专业研究过去的学者","definition":"a scholar trained to find, check and interpret evidence about past events","definitionCN":"受过训练、能查找、核验并解释过去事件证据的学者","example":"The historian spent a decade in the port ledgers before writing a single chapter.","exampleCN":"这位历史学家在港口账簿里花了十年，才写下一章。","why":"the -ian ending marks a practitioner, so historian is the person behind the discipline of history.","whyCN":"-ian 词尾标记从业者，因此 historian 就是历史学科背后的人。"},{"no":"02","title":"A writer of narrative history","titleCN":"写叙事史的作家","definition":"an author who turns evidence into a readable account for a general audience","definitionCN":"把证据变成公众可读叙述的作者","example":"As a historian she writes for readers who have never opened an archive.","exampleCN":"作为历史写作者，她为从未进过档案馆的读者写作。","why":"history once meant story, so the person who shapes the narrative keeps the older role.","whyCN":"history 曾经意为故事，因此把材料塑造成叙述的人延续了更古老的角色。"},{"no":"03","title":"An archival researcher","titleCN":"档案考证者","definition":"a specialist who works mainly on documents, registers and provenance rather than on broad narrative","definitionCN":"主要处理文书、登记册与来源考证，而非宏大叙述的专家","example":"The provenance of the painting was settled by a historian of tax records.","exampleCN":"这幅画的来历由一位研究税收档案的历史学家厘清。","why":"the discipline's authority rests on evidence, so one identity of the historian is the person who follows paper trails.","whyCN":"这门学科权威来自证据，因此历史学家的一重身份就是顺着纸面线索追查的人。"},{"no":"04","title":"An official or court chronicler","titleCN":"官方或宫廷史官","definition":"a person appointed to record events for a ruler, a city or an institution","definitionCN":"受命为统治者、城市或机构记录事件的人","example":"The court historian recorded the campaign in a tone the general approved.","exampleCN":"宫廷史官以一种将军认可的语调记录了这场战役。","why":"the office predates the modern profession, and appointment shaped what could be written.","whyCN":"这一职位早于现代专业，任命本身决定了什么可以写。"},{"no":"05","title":"A historian of one field","titleCN":"某一领域的历史学家","definition":"a specialist in the past of a particular subject, such as science, art or medicine","definitionCN":"某一特定主题（如科学、艺术或医学）之过去的专家","example":"A historian of medicine traced the shift from bleeding to transfusion.","exampleCN":"一位医学史学家梳理了从放血到输血的转变。","why":"as disciplines multiplied, each needed its own reader of its records, so the word took a field complement.","whyCN":"学科不断增多，每一门都需要自己的档案解读者，于是这个词带上了领域补语。"},{"no":"06","title":"An institutional historian","titleCN":"机构史撰写者","definition":"a person who writes the history of a company, a school or a regiment, often from internal files","definitionCN":"依据内部档案撰写公司、学校或团队历史的人","example":"The firm's historian was given the whole correspondence of its founders.","exampleCN":"这家公司的史学家获准查阅创始人的全部通信。","why":"institutions need a usable past, so they hire someone to turn their files into a lineage.","whyCN":"机构需要一个可用的过去，于是雇人把档案变成一条传承线。"},{"no":"07","title":"An amateur or local historian","titleCN":"业余或地方史研究者","definition":"a non-professional who documents the past of a place or a family with care but without formal training","definitionCN":"非专业者，认真记录某地或某家族过去，但未受正式训练","example":"A local historian mapped every well that had disappeared from the village.","exampleCN":"一位地方史研究者标出了村里每一口消失的水井。","why":"the role is defined by the subject and the care, not by a degree, so the word admits amateurs.","whyCN":"这一角色由主题与用心程度界定，而非由学位界定，因此也容纳业余者。"},{"no":"08","title":"Abstract: anyone who explains the past","titleCN":"抽象义：任何解释过去的人","definition":"loosely, anyone who offers an account of how something came to be","definitionCN":"宽泛地指任何讲述某事物如何形成的人","example":"Every family has its own historian, usually the one who keeps the photographs.","exampleCN":"每个家庭都有自己的史学家，通常是保存照片的那位。","why":"the abstract use keeps only the act of accounting for the past, dropping the archive and the degree.","whyCN":"抽象用法只保留「为过去作说明」这一动作，去掉档案与学位。"}],"etymology":{"intro":{"en":"Historian is history plus the person-ending -ian, modelled on French historien. The root goes back to Greek histor 'witness, one who knows'. Dates are approximate.","cn":"historian 是 history 加表示人的词尾 -ian，仿法语 historien 构成。词根可追溯到希腊 histor「见证人、知情者」。年代均为约数。"},"items":[{"era":"GREEK HISTOR","en":"Histor meant 'witness, one who knows', generally linked to the root for seeing that also underlies English wit.","cn":"histor 意为「见证人、知情者」，一般与表示「看见」的词根相联系，英语 wit 亦出此根。"},{"era":"GREEK HISTORIA","en":"Historia was inquiry and the knowledge gained by it, the title word of early prose research.","cn":"historia 是探究及由此获得的知识，是早期散文研究的标题词。"},{"era":"LATIN HISTORIA","en":"Latin kept historia for both the inquiry and the written account, and the account sense became dominant.","cn":"拉丁语保留 historia 兼指探究与成文记述，后来记述义占主导。"},{"era":"FRENCH HISTORIEN","en":"French formed historien for the person, adding the agent ending to the noun; English borrowed the pattern in the sixteenth century.","cn":"法语在名词上加施事词尾，构成指人的 historien；英语于 16 世纪借用这一构词模式。"},{"era":"ENGLISH HISTORIAN","en":"Historian first meant a writer of histories, and only later a salaried academic researcher with methods and archives.","cn":"historian 最初指写史之人，后来才指领取薪俸、有方法与档案的学院研究者。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest English citation of historian is not firmly fixed, and the pre-Greek history of histor is unsettled, so any reconstructed root is a hypothesis.","cn":"来源不确定（首见年代）：historian 在英语中的最早书证并不确定；histor 在希腊语之前的历史亦未定，任何重构词根都是假说。"}]},"similar":{"note":{"en":"Group one holds the adjective and root forms most often confused with the person; group two holds neighbouring keepers of the past.","cn":"第一组是常与「人」混淆的形容词与同根形式；第二组是相邻的「过去守护者」。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"historic","ipa":"/hɪˈstɒrɪk/","tag":"adjective, momentous","definition":"Describes an event important enough to be remembered; it is not the person who studies events.","definitionCN":"形容重要到值得被记住的事件；不是研究事件的人。"},{"word":"historical","ipa":"/hɪˈstɒrɪkl/","tag":"adjective, relating to the past","definition":"Describes anything connected with the past or with the discipline; the person form is historian.","definitionCN":"形容与过去或该学科有关的任何事物；指人的形式是 historian。"},{"word":"history","ipa":"/ˈhɪstri/","tag":"the field, not the person","definition":"The record, discipline or account itself; historian is the practitioner of that field.","definitionCN":"指记录、学科或叙述本身；historian 是该领域的从业者。"},{"word":"historiography","ipa":"/hɪˌstɒriˈɒɡrəfi/","tag":"the study of writing","definition":"The analysis of how histories are written; a historian may practise historiography, but the words are not interchangeable.","definitionCN":"对历史如何被书写的分析；历史学家可以从事编史学研究，但两词不可互换。"}]},{"heading":"NEAR MEANING","entries":[{"word":"chronicler","ipa":"/ˈkrɒnɪklə/","tag":"recorder by date","definition":"One who writes a chronicle, an event-by-event record; the role is closer to listing than to interpreting.","definitionCN":"写编年史的人，逐事记录；其角色更接近罗列而非解释。"},{"word":"historiographer","ipa":"/ˌhɪstɒriˈɒɡrəfə/","tag":"official writer","definition":"A formal title for an appointed writer of history, especially of a state or institution.","definitionCN":"受任撰写历史者的正式头衔，尤指国家或机构的史官。"},{"word":"archivist","ipa":"/ˈɑːkɪvɪst/","tag":"keeper of records","definition":"A person who preserves and catalogues documents; the archivist keeps the evidence a historian reads.","definitionCN":"保存并编目文书的人；档案员保管历史学家所读的证据。"},{"word":"antiquarian","ipa":"/ˌæntɪˈkweəriən/","tag":"collector of relics","definition":"An older word for one who studies ancient objects and records, often as a collector rather than an analyst.","definitionCN":"旧称，指研究古物与古记录的人，常是收藏者而非分析者。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real set phrases and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"history plus -ian makes the person, as music makes musician and politics makes politician.","cn":"history 加 -ian 构成指人的词，正如 music 构成 musician、politics 构成 politician。"},{"en":"The root histor means witness, the one who was there and can tell.","cn":"词根 histor 意为见证人，即在场并能讲述的人。"},{"en":"Fixed phrases mark the specialisms: military historian, art historian, historian of science.","cn":"固定搭配标出专长：军事史学家、艺术史学家、科学史学家。"},{"en":"The adjective historic means momentous; historical means relating to the past.","cn":"形容词 historic 指重大，historical 指与过去有关。"},{"en":"An archivist keeps the papers; a historian reads them and argues.","cn":"档案员保管纸页，历史学家阅读并论证。"}],"abstract":[{"en":"Picture thin gloves lifting two letters written in different hands.","cn":"想象薄手套捧起两封字迹不同的信。"},{"en":"Picture a ledger trail that leads from a tax entry to a whole family.","cn":"想象一条账簿线索，从一条税目通向一整个家族。"},{"en":"Picture a family album kept by the one person who remembers every name.","cn":"想象一本家庭相册，由一个记得所有名字的人保管。"}]},"examples":[{"en":"Historians disagree about the cause of the fire, though they share the same files.","cn":"历史学家对这场火灾的成因意见不一，尽管他们看的是同一批档案。"},{"en":"A military historian reconstructed the march from supply receipts.","cn":"一位军事史学家依据补给收据重建了这次行军。"},{"en":"The local historian found the well under a car park.","cn":"地方史研究者在停车场下找到了那口井。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「history（历史）+ an（人）」——写历史的那个人 → 历史学家","word":"historian"},"root":"history + -ian（表人词尾），仿法语 historien；词根回溯希腊 histor「见证人、知情者」，一般与 idein「看见」同根。histor 的更深来源不确定。英语 historian。","sensesIntro":{"en":"Eight meanings follow one person from the professional scholar to the narrative writer, the archive specialist, the official chronicler, the field specialist, the institutional and amateur worker, and finally anyone who explains a past.","cn":"八个义项沿同一种人展开：专业学者、叙事作者、档案考证者、官方史官、领域专家、机构史撰写者与业余研究者，最后是任何解释过去的人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a long table of manuscripts and a pair of gloved hands comparing two letters.","cn":"核心意象：一张手稿长桌，戴手套的双手比对两封信。"},"chain":["WITNESS","INQUIRY","EVIDENCE","INTERPRETATION","NARRATIVE","MEMORY KEEPER"],"branches":[{"senses":"S1 · S3","en":"TRAINED READER: the professional identity rests on handling evidence correctly.","cn":"受过训练的读者：专业身份建立在正确处置证据之上。"},{"senses":"S2","en":"STORYTELLER: the narrative role keeps the oldest sense of history as story.","cn":"讲故事的人：叙事角色保留了 history 作为故事的最早义项。"},{"senses":"S4 · S6","en":"APPOINTED VOICE: rulers and institutions need a past written in their own files.","cn":"受命发声：统治者与机构需要一段依自家档案写成的过去。"},{"senses":"S5","en":"FIELD SPECIALIST: every discipline trains its own reader of its records.","cn":"领域专家：每门学科都训练自己的档案解读者。"},{"senses":"S7 · S8","en":"CARE WITHOUT A DEGREE: the role finally opens to anyone who keeps and explains the past.","cn":"无关学位的用心：这一角色最终向任何守护并解释过去的人开放。"}]},"affixes":{"intro":{"en":"Historian is a transparent construction: a Greek-derived noun plus the Latin-derived person ending -ian, the same ending as in musician.","cn":"historian 的结构很透明：希腊来源名词加拉丁来源的表人词尾 -ian，与 musician 中的词尾相同。"},"latinIntro":{"en":"Latin historia builds history and historiography; the ending -ianus, through French -ien, gives the English person suffix -ian.","cn":"拉丁 historia 构成 history 与 historiography；拉丁词尾 -ianus 经法语 -ien 给出英语表人词尾 -ian。"},"items":[{"word":"historia","structure":"historia (Latin noun)","meaning":"inquiry; history","meaningCN":"探究；历史","example":"Historia named the inquiry first.","exampleCN":"historia 最初指探究。"},{"word":"-ian","structure":"-ianus (Latin) through -ien (French)","meaning":"person concerned with","meaningCN":"从事……的人","example":"historian is the person of history.","exampleCN":"historian 就是从事历史的人。"},{"word":"history","structure":"historia + English noun ending","meaning":"the record of the past","meaningCN":"过去的记录","example":"History is the field itself.","exampleCN":"history 是领域本身。"},{"word":"historian","structure":"history + -ian","meaning":"one who studies history","meaningCN":"研究历史的人","example":"The historian read the port ledgers.","exampleCN":"这位历史学家读了港口账簿。"},{"word":"historic","structure":"historia + -ic","meaning":"momentous","meaningCN":"有历史意义的","example":"The ruling was historic.","exampleCN":"那项裁决具有历史意义。"},{"word":"historical","structure":"historic + -al","meaning":"relating to the past","meaningCN":"与过去有关的","example":"Historical sources conflict.","exampleCN":"史料彼此矛盾。"},{"word":"historiography","structure":"history + -graphy (writing)","meaning":"writing of history","meaningCN":"历史书写；编史学","example":"Historiography examines how accounts are built.","exampleCN":"编史学研究叙述如何被建构。"},{"word":"historiographer","structure":"historiography + -er (person)","meaning":"an official writer of history","meaningCN":"官方史官","example":"The city appointed a historiographer.","exampleCN":"该市任命了一位史官。"}],"latinEntries":[{"word":"historia","structure":"historia, historiae (f., first declension)","meaning":"inquiry, narrative, history","meaningCN":"探究；叙述；历史"},{"word":"historicus","structure":"historicus, historica, historicum (adj.)","meaning":"of history","meaningCN":"历史的"}]}},{"word":"historic","ipa_uk":"/hɪˈstɒrɪk/","ipa_us":"/hɪˈstɔːrɪk/","definition_zh":"有历史意义的；历史性的；历史上著名的；（语法）过去时的","definition_en":"important enough to be recorded in history, or existing as part of the recorded past","core_image":"一块新刻的铭牌刚被揭下红布，围观人群举起相机，街道从此多了一个日期","scene":"投票结果公布的那一夜，人群在广场上守到天亮，第二天报纸把这次表决称为历史性的一刻。The night the vote was announced, the crowd stayed in the square until dawn, and the next day's papers called the vote a historic moment.","sceneCN":"这里 historic 指「重要到足以载入史册」（第 1 个义项：具有历史意义的）；句意为投票结果公布的那一夜，人群在广场守到天亮，第二天报纸称这次表决为历史性的一刻。可辨识物件：揭下红布的铭牌、人群、相机、报纸头版。","pos":[{"tag":"adj.","zh":"有历史意义的；历史性的；历史上存在的；（语法）过去时的"}],"collocations":[{"phrase":"a historic moment","zh":"历史性时刻"},{"phrase":"historic buildings","zh":"历史建筑"},{"phrase":"a historic victory","zh":"历史性胜利"},{"phrase":"historic district","zh":"历史街区"},{"phrase":"a historic first","zh":"历史性的第一次"},{"phrase":"historic present","zh":"历史现在时（语法术语）"}],"forms":[{"label":"原级","form":"historic"},{"label":"比较级（较少用）","form":"more historic"},{"label":"最高级（较少用）","form":"most historic"},{"label":"副词（历史上地）","form":"historically（历史上地）"},{"label":"名词（历史）","form":"history（历史）"},{"label":"形容词（历史的；史学的）","form":"historical（历史的）"}],"derivatives":[{"word":"history","pos":"n.","zh":"历史；历史学"},{"word":"historical","pos":"adj.","zh":"历史的；史学的"},{"word":"historically","pos":"adv.","zh":"历史上；从历史角度"},{"word":"historian","pos":"n.","zh":"历史学家"},{"word":"historicity","pos":"n.","zh":"历史真实性"}],"senses":[{"no":"01","title":"Momentous enough to be remembered","titleCN":"重要到值得被记住","definition":"so important that later generations will record and remember it","definitionCN":"重要到后世会记录并记住它","example":"The first lunar landing was a historic achievement, not merely a technical one.","exampleCN":"首次登月是一项历史性成就，而不只是技术成就。","why":"historic is the adjective of history in its 'recorded' sense, so it marks events that enter the record.","whyCN":"historic 是 history「被记录」义的形容词，因此它标记那些进入史册的事件。"},{"no":"02","title":"A turning point in a field","titleCN":"某一领域中的转折点","definition":"marking a decisive change in a sport, science or institution","definitionCN":"标志某项运动、科学或机构发生决定性变化","example":"Her ruling was historic for the court, whatever later judges decided.","exampleCN":"无论后来的法官如何裁决，她的判决对该法院都是历史性的。","why":"the word can be applied to a narrow field because a record exists for that field too.","whyCN":"这个词也能用于窄小领域，因为那些领域同样有自己的记录。"},{"no":"03","title":"Belonging to the recorded past","titleCN":"属于有记载的过去","definition":"existing in or dating from the period for which records survive","definitionCN":"存在于有记录留存的时代，或自那时延续下来","example":"The historic core of the town still follows the medieval street plan.","exampleCN":"这座城的历史核心区仍沿用中世纪的街道格局。","why":"this sense simply applies the adjective to things, not events, that belong to the recorded past.","whyCN":"这一义项只是把形容词用于「属于有记载之过去」的事物，而不是事件。"},{"no":"04","title":"Old and worth preserving","titleCN":"古老而值得保护","definition":"recognised as old and culturally valuable enough to be protected","definitionCN":"被认定古老且具文化价值，因而值得保护","example":"The council listed the historic warehouse before the developer applied.","exampleCN":"在开发商申请之前，议会已把这座历史仓库列入保护名录。","why":"preservation law turned 'belonging to the past' into a legal status with duties.","whyCN":"保护法把「属于过去」变成一种带义务的法律身份。"},{"no":"05","title":"The first of its kind","titleCN":"同类中的第一次","definition":"marking the first recorded instance of an achievement or an event","definitionCN":"标记某项成就或事件首次被记录的发生","example":"The expedition was a historic first for the island's fishermen.","exampleCN":"这次远航是该岛渔民的历史性第一次。","why":"a first is historic because the record begins there; nothing earlier can be cited.","whyCN":"「第一次」之所以是历史性的，因为记录从那里开始，之前无可援引。"},{"no":"06","title":"Grammatically past","titleCN":"语法上的过去时","definition":"in grammar, relating to past time, as in the historic tense or the historic present","definitionCN":"语法上表示过去时间，如历史过去时或历史现在时","example":"The historic present makes a past event feel as if it is happening now.","exampleCN":"历史现在时使过去事件仿佛正在发生。","why":"grammar borrowed the adjective for forms that narrate past events, a technical sense most readers never meet.","whyCN":"语法学借用这个形容词指叙述过去事件的形式，这是多数读者不会遇到的专门义。"},{"no":"07","title":"Recorded in written history","titleCN":"见于成文史料的","definition":"known from written records rather than only from material remains","definitionCN":"由成文记录而非仅由实物遗存所知","example":"The site is historic rather than prehistoric because its name appears in a tax roll.","exampleCN":"该遗址属有史时期而非史前，因为它的名字出现在一份税册里。","why":"archaeology contrasts historic with prehistoric, using the adjective for the period with documents.","whyCN":"考古学把 historic 与 prehistoric 对照，用这个形容词指有文献的时期。"},{"no":"08","title":"Abstract: made significant by retelling","titleCN":"抽象义：因被讲述而显得重大","definition":"treated as significant because later telling has made it so","definitionCN":"因后来的讲述而显得重要","example":"The quarrel became historic only after three biographers described it.","exampleCN":"那场争吵在三位传记作家描写之后才变得历史性。","why":"significance is assigned by the record, so the adjective can describe a status produced by retelling.","whyCN":"重要性由记录赋予，因此这个形容词可以描述一种由反复讲述产生的地位。"}],"etymology":{"intro":{"en":"Historic is history plus the Greek-Latin adjective ending -ic. It entered English in the seventeenth century, first of things belonging to the recorded past. Dates are approximate.","cn":"historic 是 history 加希腊—拉丁形容词词尾 -ic 构成，17 世纪进入英语，最初指属于有记载之过去的事物。年代均为约数。"},"items":[{"era":"GREEK HISTORIA","en":"Historia meant inquiry and the knowledge gained by it; the root histor is 'witness, one who knows'.","cn":"historia 意为探究及由此获得的知识；词根 histor 是「见证人、知情者」。"},{"era":"LATIN HISTORICUS","en":"Latin formed historicus 'of history' from the Greek adjective, and used it of writers and of things recorded.","cn":"拉丁语依希腊形容词构成 historicus「历史的」，用于作家与有记载之事。"},{"era":"FRENCH HISTORIQUE","en":"French historique kept the sense 'belonging to history' and passed it to English.","cn":"法语 historique 保留「属于历史的」之义，并传入英语。"},{"era":"ENGLISH HISTORIC","en":"Historic first meant 'recorded in history', then narrowed to 'momentous' in the nineteenth century, while historical took over the neutral sense.","cn":"historic 最初指「见于史册」，19 世纪收窄为「重大」，而中性义由 historical 承担。"},{"era":"PRESERVATION AND GRAMMAR","en":"Listed buildings gave the word a legal sense, and grammar used it for past-tense narration, especially the historic present.","cn":"列入保护名录的建筑赋予这个词法律义，语法学则用它指过去时叙述，尤其是历史现在时。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the exact point when 'momentous' overtook 'recorded' as the main sense is not fixed, so the dating here is approximate.","cn":"来源不确定（首见年代）：「重大」义取代「有记载」义成为主要义项的确切时点尚无定论，此处年代为约数。"}]},"similar":{"note":{"en":"Group one holds the pair most often confused, historic and historical, plus two related nouns; group two holds words for events that change the record.","cn":"第一组是最常被混淆的一对 historic 与 historical，以及两个相关名词；第二组是表示「改变记录」的事件用词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"historical","ipa":"/hɪˈstɒrɪkl/","tag":"neutral, about the past","definition":"Means relating to the past or to the study of it, with no claim of importance: historical documents, historical research.","definitionCN":"意为与过去或史学研究有关，不含重要性判断：历史文献、历史研究。"},{"word":"history","ipa":"/ˈhɪstri/","tag":"the noun","definition":"The record or discipline itself; historic is the adjective for what deserves a place in it.","definitionCN":"指记录或学科本身；historic 是「值得进入其中」的形容词。"},{"word":"historian","ipa":"/hɪˈstɔːriən/","tag":"the person","definition":"The scholar who studies the past; the adjective never names a person.","definitionCN":"研究过去的学者；该形容词从不指人。"},{"word":"historicity","ipa":"/ˌhɪstəˈrɪsəti/","tag":"the authenticity","definition":"The quality of being historically real or verifiable, used of figures and events whose existence is debated.","definitionCN":"指历史上真实或可验证的性质，用于其存在尚有争议的人物与事件。"}]},{"heading":"NEAR MEANING","entries":[{"word":"momentous","ipa":"/məˈmentəs/","tag":"weight of consequence","definition":"From Latin momentum 'movement, weight': it stresses consequences rather than a place in the record.","definitionCN":"来自拉丁 momentum「运动、重量」：强调后果的分量，而非在史册中的位置。"},{"word":"landmark","ipa":"/ˈlændmɑːk/","tag":"a marker to navigate by","definition":"An event or decision used as a reference point, as a landmark is used in walking.","definitionCN":"被用作参照点的事件或决定，如同行走时借以辨认的地标。"},{"word":"epoch-making","ipa":"/ˈiːpɒk meɪkɪŋ/","tag":"opens a period","definition":"So significant that it begins a new period; a stronger, more literary claim than historic.","definitionCN":"重要到开启一个新时期；语气比 historic 更强、更书面。"},{"word":"unprecedented","ipa":"/ʌnˈpresɪdentɪd/","tag":"no earlier case","definition":"Having no earlier example; it stresses novelty, while historic stresses importance.","definitionCN":"指没有先例；强调新颖，而 historic 强调重要。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real set phrases and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Historic is the -ic adjective of history, so it marks what belongs in the record.","cn":"historic 是 history 的 -ic 形容词，因此标记「应入史册」之物。"},{"en":"The decisive contrast: historic means momentous, historical means merely relating to the past.","cn":"决定性对照：historic 指重大，historical 只指与过去有关。"},{"en":"Fixed phrases mark the uses: a historic moment, historic buildings, a historic first.","cn":"固定搭配标出用法：历史性时刻、历史建筑、历史性的第一次。"},{"en":"The noun historicity appears when scholars debate whether a figure really existed.","cn":"学者争论某人物是否真实存在时，会出现名词 historicity。"},{"en":"Grammar keeps a technical use in the phrase historic present.","cn":"语法学在 historic present 这一短语中保留专门用法。"}],"abstract":[{"en":"Picture a red cloth pulled off a plaque while cameras rise.","cn":"想象红布从铭牌上被拉下，相机同时举起。"},{"en":"Picture a ledger where the first entry is written in a different ink.","cn":"想象一本账簿，第一条记录用的是另一种墨水。"},{"en":"Picture a street that suddenly acquires a date it did not have yesterday.","cn":"想象一条街道忽然多出一个昨天还没有的日期。"}]},"examples":[{"en":"The treaty was historic, but its enforcement was left to later governments.","cn":"这份条约具有历史意义，但其执行留给了后来的政府。"},{"en":"The historic district survived because the council listed it in time.","cn":"由于议会及时将其列入名录，这片历史街区得以保存。"},{"en":"Historians still argue over which election was truly historic.","cn":"历史学家仍在争论哪一场选举才算真正具有历史意义。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「history（历史）+ ic（的）」——值得写进历史的 → 历史性的","word":"historic"},"root":"history + -ic（形容词词尾）；history 出自希腊 historia「探究」，词根 histor「见证人」，经拉丁 historicus 与法语 historique。histor 的更深来源不确定。英语 historic。","sensesIntro":{"en":"Eight meanings follow one adjective from an event worth recording to a field's turning point, to things of the recorded past, preserved old buildings, recorded firsts, grammar, written history and significance granted later.","cn":"八个义项沿同一个形容词展开：值得记录的事件、领域的转折点、属于有记载过去的事物、受保护的老建筑、有记录的第一、语法义、成文历史，以及后来赋予的重要性。"},"semanticMap":{"core":{"en":"CORE IMAGE: a plaque uncovered before cameras, and a street that gains a date.","cn":"核心意象：相机前揭开的铭牌，街道因此多了一个日期。"},"chain":["RECORDED","REMEMBERED","MOMENTOUS","PROTECTED","FIRST TIME","SIGNIFICANCE"],"branches":[{"senses":"S1 · S5","en":"ENTERING THE RECORD: importance and firstness both mean the record begins or turns here.","cn":"进入记录：重要与首次都意味着记录在此开始或转折。"},{"senses":"S2","en":"FIELD RECORD: a narrow discipline keeps its own ledger of turning points.","cn":"领域记录：窄小学科也有自己的转折点账本。"},{"senses":"S3 · S7","en":"THINGS OF THE PAST: objects and sites belong to the documented period, with or without drama.","cn":"过去之物：实物与遗址属于有文献的时期，无论是否有戏剧性。"},{"senses":"S4","en":"LAW OF PRESERVATION: belonging to the past becomes a protected status.","cn":"保护之法：属于过去变成一种受保护的身份。"},{"senses":"S6 · S8","en":"GRAMMAR AND RETROSPECT: significance can be encoded in tense or granted by later telling.","cn":"语法与回溯：重要性可被时态编码，也可由后来的讲述赋予。"}]},"affixes":{"intro":{"en":"Historic is a noun plus one adjective ending, and the same ending recurs in dozens of English words.","cn":"historic 是一个名词加一个形容词词尾，同一词尾在英语中反复出现在大量词里。"},"latinIntro":{"en":"Latin historicus gives historic and historical; the ending -icus yields English -ic, seen in dramatic, poetic and economic.","cn":"拉丁 historicus 构成 historic 与 historical；词尾 -icus 给出英语 -ic，见于 dramatic、poetic 与 economic。"},"items":[{"word":"historia","structure":"historia (Latin noun)","meaning":"inquiry; history","meaningCN":"探究；历史","example":"Historia is the base noun.","exampleCN":"historia 是基础名词。"},{"word":"-ic","structure":"-ikos (Greek) through -icus (Latin)","meaning":"of the nature of","meaningCN":"具有……性质的","example":"historic is history plus -ic.","exampleCN":"historic 就是 history 加 -ic。"},{"word":"historic","structure":"historia + -ic","meaning":"of history, momentous","meaningCN":"历史的；重大的","example":"The vote was historic.","exampleCN":"这次表决具有历史意义。"},{"word":"historical","structure":"historic + -al","meaning":"relating to the past","meaningCN":"与过去有关的","example":"Historical records survive.","exampleCN":"历史记录留存下来。"},{"word":"historically","structure":"historical + -ly","meaning":"in past times","meaningCN":"历史上","example":"Historically, the site was a marsh.","exampleCN":"历史上这里是沼泽。"},{"word":"historian","structure":"history + -ian (person)","meaning":"a student of history","meaningCN":"历史学家","example":"The historian checked the roll.","exampleCN":"历史学家查了名册。"},{"word":"historicity","structure":"historic + -ity (quality)","meaning":"historical authenticity","meaningCN":"历史真实性","example":"The historicity of the tale is disputed.","exampleCN":"这个传说的历史真实性有争议。"},{"word":"prehistoric","structure":"pre- + historic","meaning":"before written records","meaningCN":"史前的","example":"Prehistoric layers lie below the town.","exampleCN":"史前文化层位于城下。"}],"latinEntries":[{"word":"historia","structure":"historia, historiae (f., first declension)","meaning":"inquiry, narrative, history","meaningCN":"探究；叙述；历史"},{"word":"historicus","structure":"historicus, historica, historicum (adj.)","meaning":"of history, historical","meaningCN":"历史的"}]}},{"word":"chronological order","ipa_uk":"/ˌkrɒnəˈlɒdʒɪkl ˈɔːdə/","ipa_us":"/ˌkrɑːnəˈlɑːdʒɪkl ˈɔːrdər/","definition_zh":"时间顺序；按年代先后的排列顺序","definition_en":"an arrangement of events or items according to the order in which they occurred in time","core_image":"一串纸牌按年份从左到右摊开，最早的摆在最左端，年号依次递增","scene":"修复师把散落的信件按年份从最早排到最晚，再依时间顺序装订成册。The conservator laid the scattered letters out from the earliest year to the latest, then bound them into a volume in chronological order.","sceneCN":"这里 chronological order 指「按时间先后排列的次序」（第 1 个义项：依据发生时间的排列方式）；句意为修复师把散落的信件按年份从最早排到最晚，再依时间顺序装订成册。可辨识物件：按年摊开的纸牌、年份标签、装订线、信件堆。","pos":[{"tag":"n.","zh":"时间顺序；编年次序（不可数，指一种排列方式）"}],"collocations":[{"phrase":"in chronological order","zh":"按时间顺序"},{"phrase":"arrange in chronological order","zh":"按年代排列"},{"phrase":"reverse chronological order","zh":"倒序时间排列"},{"phrase":"chronological order of events","zh":"事件的时间顺序"},{"phrase":"strictly chronological order","zh":"严格的时间顺序"},{"phrase":"out of chronological order","zh":"不按时间顺序"}],"forms":[{"label":"通常无复数（不可数）","form":"chronological order"},{"label":"复数（少见，指多种排列）","form":"chronological orders"},{"label":"相关形容词（编年的）","form":"chronological（按年代的）"},{"label":"相关副词（按年代地）","form":"chronologically（按年代顺序地）"},{"label":"相关名词（年代学）","form":"chronology（年代学；年表）"},{"label":"反义说法（主题顺序）","form":"thematic order（主题顺序）"}],"derivatives":[{"word":"chronological","pos":"adj.","zh":"按年代顺序的"},{"word":"chronologically","pos":"adv.","zh":"按年代顺序地"},{"word":"chronology","pos":"n.","zh":"年代学；年表"},{"word":"chronologer","pos":"n.","zh":"年表编纂者（罕用）"},{"word":"chronometer","pos":"n.","zh":"精密计时器（同 chron- 词根）"}],"senses":[{"no":"01","title":"Arrangement by time of occurrence","titleCN":"按发生时间排列","definition":"the sequence in which items are placed from earliest to latest according to when they happened","definitionCN":"按发生时间由早到晚摆放各项的次序","example":"The archive keeps the letters in chronological order, not by sender.","exampleCN":"档案馆按时间顺序保存信件，而不按寄信人。","why":"chronological is built on Greek chronos 'time', so the phrase names time itself as the sorting rule.","whyCN":"chronological 由希腊 chronos「时间」构成，因此这个短语以时间本身为排序规则。"},{"no":"02","title":"A narrative told in sequence","titleCN":"按先后讲述的叙事","definition":"a story or account that follows events one after another rather than jumping about","definitionCN":"按事件先后推进、不作跳跃的故事或叙述","example":"The film tells the war in chronological order, from the first telegram to the armistice.","exampleCN":"影片按时间顺序讲这场战争，从第一封电报讲到停战。","why":"narrative can reorder time at will, so 'in chronological order' marks the choice not to.","whyCN":"叙事本可任意重排时间，因此「按时间顺序」标记的是「不重排」这一选择。"},{"no":"03","title":"A dating sequence in science","titleCN":"科学中的年代序列","definition":"the order of layers, specimens or events established by dating methods","definitionCN":"用测年方法确定的层位、标本或事件的先后","example":"The cores were logged in chronological order from the surface down.","exampleCN":"岩芯自表层向下按年代顺序记录。","why":"stratigraphy assumes that deeper layers are older, which makes time the backbone of the record.","whyCN":"地层学假定更深的层更古老，时间因此成为记录的骨架。"},{"no":"04","title":"A case record in sequence","titleCN":"案件或病历的时序记录","definition":"the ordered record of events in a case, a patient's file or an investigation","definitionCN":"案件、病历或调查中事件的按序记录","example":"The report sets out the accident in chronological order, minute by minute.","exampleCN":"报告按时间顺序逐分钟还原这起事故。","why":"courts and clinicians need to show that nothing was skipped, and sequence is the proof.","whyCN":"法庭与临床需要证明没有遗漏，而顺序就是证明。"},{"no":"05","title":"Reverse chronological order","titleCN":"倒序时间排列","definition":"the same ordering run backwards, newest first, standard in feeds and logs","definitionCN":"同一排序反向运行，最新在前，常见于信息流与日志","example":"The blog lists posts in reverse chronological order so the newest sits on top.","exampleCN":"博客按倒序时间排列文章，最新一篇在最上面。","why":"digital publishing made the reverse convention dominant, because readers want the latest first.","whyCN":"数字出版使倒序成为主流，因为读者想先看到最新的。"},{"no":"06","title":"Relative versus absolute chronology","titleCN":"相对年代与绝对年代","definition":"ordering by before-and-after relations, as opposed to fixed calendar dates","definitionCN":"按先后关系排序，与固定的日历年代相对","example":"The site has a relative chronological order but no absolute dates.","exampleCN":"该遗址有相对的时间顺序，却没有绝对年代。","why":"archaeology separates the two because sequence can be certain while dates remain unknown.","whyCN":"考古学把两者分开，因为先后可以确定，而年代仍可能未知。"},{"no":"07","title":"An order that is not chronological","titleCN":"非时间顺序的对照","definition":"the phrase used as a standard against which thematic, spatial or random orders are judged","definitionCN":"作为标准，用以衡量主题、空间或随机排列","example":"The exhibition groups the paintings by theme, deliberately ignoring chronological order.","exampleCN":"展览按主题分组画作，有意不按时间顺序。","why":"a contrast term gains meaning from what it excludes, and here it excludes every non-temporal arrangement.","whyCN":"对照性术语的意义来自它所排除的东西，这里它排除一切非时间的排列。"},{"no":"08","title":"Abstract: a logical sequence of steps","titleCN":"抽象义：步骤的先后次序","definition":"loosely, the necessary sequence of steps in a process, as if each step had a date","definitionCN":"宽泛指过程中必要的步骤次序，仿佛每一步都有日期","example":"The manual presents the repairs in chronological order, one after another.","exampleCN":"手册按先后顺序逐一介绍各项修理步骤。","why":"the abstraction borrows time's irreversibility to say that one step must come before another.","whyCN":"抽象用法借用了时间的不可逆性，来表达「一步必须先于另一步」。"}],"etymology":{"intro":{"en":"Chronological joins Greek chronos 'time' with logos 'word, reason, account' plus the adjective ending -ical. Order comes from Latin ordo 'row, series'. The phrase itself is a modern term. Dates are approximate.","cn":"chronological 把希腊 chronos「时间」与 logos「言词、理性、叙述」以及形容词词尾 -ical 结合在一起。order 来自拉丁 ordo「行列、次序」。短语本身是近代术语。年代均为约数。"},"items":[{"era":"GREEK CHRONOS","en":"Chronos meant 'time' as a span or a period; its deeper origin is not established, so any proposed root is a hypothesis.","cn":"chronos 意为作为跨度或时段的「时间」；其更远来源未得到证明，任何提出的词根都是假说。"},{"era":"GREEK LOGOS","en":"Logos meant 'word, account, reason', from legein 'to gather, to say'; the link is generally accepted.","cn":"logos 意为「言词、叙述、理性」，出自 legein「聚集、言说」；这一联系被普遍接受。"},{"era":"CHRONOLOGIA","en":"Latin chronologia, a Greek-Latin hybrid, named the science of dating events; it spread in sixteenth-century scholarship.","cn":"拉丁 chronologia 是希腊—拉丁混合词，指确定事件年代之学，在 16 世纪学术中流行。"},{"era":"LATIN ORDO","en":"Ordo meant 'row, line, rank, arrangement'; its own origin is disputed, possibly from a root for weaving a warp.","cn":"ordo 意为「行列、等级、安排」；其自身来源有争议，可能出自表示「织经线」的词根。"},{"era":"ENGLISH PHRASE","en":"Chronological order appears with the growth of archives, museums and scientific dating from the eighteenth century onward.","cn":"随着档案、博物馆与科学测年自 18 世纪起发展，chronological order 这一说法开始出现。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): no exact earliest citation of the fixed phrase is agreed, chronos and ordo both lack settled pre-histories, and the weaving link for ordo is a suggestion only.","cn":"来源不确定（首见年代与更深词源）：这一固定短语的最早书证没有公认答案；chronos 与 ordo 均无定论的前史，ordo 与「织」的联系仅是推测。"}]},"similar":{"note":{"en":"Group one holds the words built on chronos that are easily mixed with the phrase; group two holds other ordering principles.","cn":"第一组是同出 chronos、易与该短语混淆的词；第二组是其他排序原则。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"chronology","ipa":"/krəˈnɒlədʒi/","tag":"the table or science","definition":"A dated list or the science of dating; the order is the arrangement, the chronology is the list itself.","definitionCN":"指带日期的年表或测年之学；order 是排列方式，chronology 是那份年表本身。"},{"word":"chronological","ipa":"/ˌkrɒnəˈlɒdʒɪkl/","tag":"the adjective","definition":"The adjective meaning arranged by time; the phrase needs the noun order to name the arrangement.","definitionCN":"形容词，意为按时间排列；必须加名词 order 才指这种排列本身。"},{"word":"chronometer","ipa":"/krəˈnɒmɪtə/","tag":"the instrument","definition":"A precise clock used at sea; it shares the chron- root but measures time rather than arranging events.","definitionCN":"海上使用的精密时钟；同为 chron- 词根，却用于计量时间而非排列事件。"},{"word":"chronicle","ipa":"/ˈkrɒnɪkl/","tag":"year-by-year record","definition":"A record arranged by date, from the same root; a chronicle is a document, chronological order is its principle.","definitionCN":"按日期排列的记录，同出该词根；chronicle 是文献，chronological order 是其原则。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sequence","ipa":"/ˈsiːkwəns/","tag":"any order of succession","definition":"From Latin sequi 'to follow': any order of one after another, which need not be based on time.","definitionCN":"来自拉丁 sequi「跟随」：任何先后顺序，不一定以时间为依据。"},{"word":"timeline","ipa":"/ˈtaɪmlaɪn/","tag":"the visual form","definition":"A graphic line marked with dates; it displays chronological order rather than being the principle itself.","definitionCN":"标有日期的图示直线；它展示时间顺序，而非顺序原则本身。"},{"word":"thematic order","ipa":"/θiˈmætɪk ˈɔːdə/","tag":"the deliberate contrast","definition":"Arrangement by topic instead of date; exhibitions and essays often choose it over chronology.","definitionCN":"按主题而非日期排列；展览与文章常选它而非时间顺序。"},{"word":"order of events","ipa":"/ˈɔːdər əv ɪˈvents/","tag":"plain description","definition":"The everyday phrase for what happened first; chronological order is its technical, formal label.","definitionCN":"指「先发生了什么」的日常说法；chronological order 是其技术化、正式的名称。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real set phrases and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Chronos is time, logos is account, so chronological is 'time-account' ordering.","cn":"chronos 是时间，logos 是叙述，因此 chronological 就是「依时间叙述」的排序。"},{"en":"The fixed phrase is 'in chronological order'; the preposition in marks the arrangement being used.","cn":"固定说法是 in chronological order，介词 in 标记正在采用的排列方式。"},{"en":"Reverse chronological order is the feed convention: newest first.","cn":"倒序时间排列是信息流的惯例：最新在前。"},{"en":"Keep chronology the noun apart from chronological the adjective.","cn":"把名词 chronology 与形容词 chronological 分开。"},{"en":"A timeline is the picture of chronological order, not the order itself.","cn":"timeline 是时间顺序的图示，而不是顺序本身。"}],"abstract":[{"en":"Picture cards laid left to right with rising year numbers.","cn":"想象纸牌从左到右排开，年份数字依次递增。"},{"en":"Picture a stack of letters bound after being sorted by date.","cn":"想象一叠信件按日期分好之后被装订起来。"},{"en":"Picture a staircase where each step is one day.","cn":"想象一道楼梯，每一级是一天。"}]},"examples":[{"en":"List the sources in chronological order so that the argument's development is visible.","cn":"按时间顺序列出资料，使论证的发展过程可见。"},{"en":"The logs are kept in reverse chronological order, newest entry first.","cn":"日志按倒序时间保存，最新一条在最前。"},{"en":"Relative chronological order can be established without any absolute dates.","cn":"无需任何绝对年代，也能建立相对的时间顺序。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「chrono（时间）+ logical（逻辑）+ order（顺序）」——按时间讲逻辑 → 时间顺序","word":"chronological order"},"root":"chronological = 希腊 chronos「时间」+ logos「言词、叙述」+ -ical；order 来自拉丁 ordo「行列、次序」。chronos 与 ordo 的更深来源均不确定。英语短语 chronological order。","sensesIntro":{"en":"Eight meanings follow one rule of arrangement from the plain time sequence to narrative, scientific dating, case records, the reverse convention, relative chronology, non-temporal contrast and finally the logic of steps.","cn":"八个义项沿同一条排列规则展开：从纯时间序列到叙事、科学测年、案件记录、倒序惯例、相对年代、非时间对照，最后是步骤的逻辑。"},"semanticMap":{"core":{"en":"CORE IMAGE: cards laid out by rising year numbers from left to right.","cn":"核心意象：纸牌按递增年份从左到右排开。"},"chain":["TIME","ACCOUNT","ORDER","SEQUENCE RECORDED","REVERSED","STEP LOGIC"],"branches":[{"senses":"S1 · S2","en":"TIME AS RULE: narration and arrangement both obey the clock unless they choose not to.","cn":"以时间为规则：叙述与排列都服从时钟，除非刻意不服从。"},{"senses":"S3 · S4","en":"EVIDENCE ORDER: layers and case files prove completeness by their sequence.","cn":"证据顺序：地层与案卷靠先后证明没有遗漏。"},{"senses":"S5","en":"REVERSAL: the same rule run backwards serves readers who want the newest first.","cn":"反向：同一规则倒着运行，服务想先看最新内容的读者。"},{"senses":"S6 · S7","en":"WHAT IT EXCLUDES: relative dating and thematic shows are understood against this default.","cn":"它所排除的：相对测年与主题展正是对照这一默认来理解。"},{"senses":"S8","en":"BORROWED LOGIC: step-by-step procedures borrow time's irreversibility.","cn":"借用的逻辑：分步流程借用了时间的不可逆性。"}]},"affixes":{"intro":{"en":"The phrase combines two Greek roots under one adjective ending with a Latin noun, so every piece can be read separately.","cn":"这个短语把一个希腊词根组合的形容词与一个拉丁名词放在一起，每一部分都可单独读出。"},"latinIntro":{"en":"Greek chronos gives chronology and chronometer; logos gives logic and -logy; Latin ordo gives order, ordinal and ordinary.","cn":"希腊 chronos 构成 chronology 与 chronometer；logos 构成 logic 与 -logy；拉丁 ordo 构成 order、ordinal 与 ordinary。"},"items":[{"word":"chronos","structure":"chronos (Greek noun, 'time')","meaning":"time","meaningCN":"时间","example":"Chronos is the first element.","exampleCN":"chronos 是第一个成分。"},{"word":"logos","structure":"logos (Greek noun, 'word, account, reason')","meaning":"account; reason","meaningCN":"叙述；理性","example":"Logos supplies the -logy ending.","exampleCN":"logos 提供 -logy 词尾。"},{"word":"-ical","structure":"-ikos + -alis (adjective ending)","meaning":"relating to","meaningCN":"与……有关的","example":"chronological means relating to time order.","exampleCN":"chronological 意为与时间次序有关。"},{"word":"chronology","structure":"chronos + -logia (study, account)","meaning":"a dated list or the science of dating","meaningCN":"年表；年代学","example":"The chronology runs to forty pages.","exampleCN":"这份年表长达四十页。"},{"word":"chronometer","structure":"chronos + metron (measure)","meaning":"a precise timekeeper","meaningCN":"精密计时器","example":"The chronometer survived the voyage.","exampleCN":"这只精密计时器经受住了航行。"},{"word":"order","structure":"ordo (Latin noun, 'row, series')","meaning":"arrangement in a series","meaningCN":"成系列的排列","example":"The order follows the dates.","exampleCN":"顺序依日期而定。"},{"word":"ordinal","structure":"ordo + -inal (relating to order)","meaning":"a number showing position","meaningCN":"序数词","example":"First and second are ordinals.","exampleCN":"first 与 second 是序数词。"},{"word":"ordinary","structure":"ordo + -arius (in order)","meaning":"regular, usual","meaningCN":"平常的；常规的","example":"An ordinary day follows its usual order.","exampleCN":"平常的一天按常规次序展开。"}],"latinEntries":[{"word":"ordo","structure":"ordo, ordinis (m., third declension)","meaning":"row, line, arrangement, rank","meaningCN":"行列；排列；等级"},{"word":"ordinare","structure":"ordinare, ordinavi, ordinatum (verb, first conjugation)","meaning":"to set in order, arrange","meaningCN":"整理；排列"},{"word":"chronologia","structure":"chronologia, chronologiae (f., first declension, Greek-Latin hybrid)","meaning":"the account of time, chronology","meaningCN":"时间记述；年代学"}]}},{"word":"civilization","ipa_uk":"/ˌsɪvɪlɪˈzeɪʃn/","ipa_us":"/ˌsɪvəlɪˈzeɪʃn/","definition_zh":"文明；文明社会；某一时期或地区的文明；（与野蛮相对的）开化状态","definition_en":"a society with developed cities, writing and organised institutions, or the condition of being so developed","core_image":"一条河边的泥砖城：城墙、水渠、书吏的泥板与集市同时出现在一幅剖面里","scene":"考古队在河谷发现城墙、灌溉渠与刻字的泥板，据此判断这里曾有一座早期文明。In the river valley the team found walls, irrigation channels and inscribed clay tablets, and concluded that an early civilization had stood there.","sceneCN":"这里 civilization 指「具备城市、文字与制度的高度发展社会」（第 1 个义项：成熟的聚落文明）；句意为考古队在河谷发现城墙、灌溉渠与刻字泥板，据此判断这里曾有一座早期文明。可辨识物件：泥砖城墙、灌溉渠、刻字泥板、集市摊位。","pos":[{"tag":"n.","zh":"文明；文明社会（可数指某一文明，不可数指开化状态或进程）"}],"collocations":[{"phrase":"ancient civilization","zh":"古代文明"},{"phrase":"the dawn of civilization","zh":"文明的黎明"},{"phrase":"Western civilization","zh":"西方文明"},{"phrase":"the collapse of a civilization","zh":"文明的崩溃"},{"phrase":"human civilization","zh":"人类文明"},{"phrase":"a civilization built on irrigation","zh":"以灌溉为基础的文明"}],"forms":[{"label":"复数","form":"civilizations"},{"label":"动词（使文明化）","form":"civilize（使开化）"},{"label":"形容词（文明的）","form":"civilized（文明的；有教养的）"},{"label":"形容词（公民的；民事的）","form":"civil（公民的；民事的；有礼的）"},{"label":"名词（公民）","form":"citizen（公民）"},{"label":"名词（礼貌；文明修养）","form":"civility（礼貌；谦恭）"}],"derivatives":[{"word":"civilize","pos":"v.","zh":"使开化；使文明"},{"word":"civilized","pos":"adj.","zh":"文明的；有教养的"},{"word":"civil","pos":"adj.","zh":"公民的；民事的；有礼的"},{"word":"civility","pos":"n.","zh":"礼貌；谦恭"},{"word":"civilian","pos":"n./adj.","zh":"平民（的）"}],"senses":[{"no":"01","title":"A society with cities, writing and institutions","titleCN":"具备城市、文字与制度的社会","definition":"a large organised society with cities, a written record and lasting institutions","definitionCN":"拥有城市、成文记录与持久制度的大型有组织社会","example":"The first civilization in the valley grew along the irrigation canals.","exampleCN":"该河谷最早的文明沿灌溉渠成长起来。","why":"the word was built to name urban, literate society, so its core is organisation rather than mere survival.","whyCN":"这个词是为命名城市化的、有文字的社会而造，核心在于组织形态，而非仅能生存。"},{"no":"02","title":"The condition of being civilized","titleCN":"开化状态（与野蛮相对）","definition":"the state of having orderly customs and laws rather than a supposed state of savagery","definitionCN":"拥有有序习俗与法律、而非所谓野蛮的状态","example":"Eighteenth-century writers treated civilization as a scale from savagery to refinement.","exampleCN":"18 世纪的作者把文明看作从野蛮到精致的标尺。","why":"the abstract noun marks a condition, and the scale behind it was an Enlightenment assumption rather than a measurement.","whyCN":"这个抽象名词标记一种状态，其背后的标尺是启蒙时代的假设，而非实测。"},{"no":"03","title":"A particular civilization","titleCN":"某一具体文明","definition":"one named society or tradition, such as the Egyptian, Maya or Indus civilization","definitionCN":"某个有名有姓的社会或传统，如埃及、玛雅或印度河文明","example":"The Maya civilization built observatories aligned with the sun.","exampleCN":"玛雅文明建造了与太阳对齐的观测台。","why":"as archaeology named its finds, the countable form became standard for a bounded tradition.","whyCN":"当考古学开始为发现物命名，可数形式便成为指一个有界传统的标准说法。"},{"no":"04","title":"Modern comfort as we know it","titleCN":"我们所习惯的现代生活","definition":"the familiar conditions of settled modern life, used in phrases such as 'the end of civilization as we know it'","definitionCN":"熟悉的现代稳定生活条件，见于「我们所知的文明就此终结」等说法","example":"A week without electricity felt like the end of civilization.","exampleCN":"停水停电一周，感觉像是文明的终结。","why":"the hyperbolic use takes the abstract sense and ties it to plumbing, power and shops.","whyCN":"夸张用法取抽象义，并把它绑在自来水、电力与商店上。"},{"no":"05","title":"The civilising process","titleCN":"文明化进程","definition":"the long process by which manners, law and state control became more orderly","definitionCN":"礼仪、法律与国家控制变得更有序的漫长过程","example":"Historians describe table manners as part of civilization, not its ornament.","exampleCN":"历史学家把餐桌礼仪视为文明进程的一部分，而非其装饰。","why":"sociology turned the noun toward process, asking how restraint and predictability were learned.","whyCN":"社会学把这个名词转向过程，追问克制与可预期性是如何习得的。"},{"no":"06","title":"City life as a form of society","titleCN":"以城市生活为形态的社会","definition":"a way of life organised around dense settlement, division of labour and public space","definitionCN":"围绕密集定居、劳动分工与公共空间组织起来的生活方式","example":"The excavation showed civilization arriving with the first paved street.","exampleCN":"发掘显示，文明是随第一条铺石街道一起到来的。","why":"the Latin root is the citizen, so the word keeps an urban core even when it means a whole tradition.","whyCN":"拉丁词根是「公民」，因此即使指整个传统，这个词仍保有城市内核。"},{"no":"07","title":"Human civilization as a whole","titleCN":"作为整体的人类文明","definition":"the accumulated achievement of humanity, often used in singular as a shared inheritance","definitionCN":"人类积累的成就，常用单数表示共同遗产","example":"The library sees itself as a guardian of civilization, not only of books.","exampleCN":"这家图书馆把自己视为文明的守护者，而不只是图书的守护者。","why":"the singular collective sense treats many traditions as one inheritance worth protecting.","whyCN":"单数集合义把许多传统视为一份值得保护的共同遗产。"},{"no":"08","title":"Abstract: ordered social life and shared norms","titleCN":"抽象义：有序的社会生活与共同规范","definition":"the shared norms and restraints that make dense social life possible","definitionCN":"使密集社会生活成为可能的共同规范与克制","example":"Queueing quietly is a small piece of civilization that nobody legislates.","exampleCN":"安静排队是无人立法的一小块文明。","why":"the abstract use reduces the word to its function: predictable behaviour that lets strangers share space.","whyCN":"抽象用法把这个词还原为其功能：让陌生人共享空间的、可预期的行为。"}],"etymology":{"intro":{"en":"Civilization comes from Latin civis 'citizen' through civilis 'of citizens' and civitas 'citizen body'. The noun was formed in French in the eighteenth century. Dates are approximate.","cn":"civilization 由拉丁 civis「公民」经 civilis「公民的」与 civitas「公民全体」而来，名词在 18 世纪由法语构成。年代均为约数。"},"items":[{"era":"LATIN CIVIS","en":"Civis meant 'citizen'; its deeper origin is not established, and a link to a root meaning 'to lie down, settle' is only a hypothesis.","cn":"civis 意为「公民」；其更远来源未得到证明，与表示「躺下、定居」的词根相联系只是假说。"},{"era":"LATIN CIVILIS","en":"Civilis meant 'of citizens, civic, polite', and already carried the contrast with what was considered rude or uncultivated.","cn":"civilis 意为「公民的、城邦的、有礼的」，已带有与粗野无文相对的意思。"},{"era":"LATIN CIVITAS","en":"Civitas named the body of citizens and, by extension, the city they formed.","cn":"civitas 指公民全体，并引申指他们所构成的城市。"},{"era":"FRENCH CIVILISATION","en":"French civilisation first named the process of becoming civil, then a civilized society itself.","cn":"法语 civilisation 先指「变得有礼」的过程，继而指文明社会本身。"},{"era":"ENGLISH AND WORLD HISTORY","en":"English adopted the word in the late eighteenth century; nineteenth-century world histories used it for a stage that societies were said to pass through.","cn":"英语于 18 世纪后期采用该词；19 世纪的世界史把它用作社会据说必经的一个阶段。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): the earliest English citation is not fixed, the pre-Latin origin of civis is unsettled, and the ranking of societies implied by the older sense is now treated as an assumption rather than a fact.","cn":"来源不确定（首见年代与更深词源）：英语最早书证尚无定论，civis 在拉丁语之前的来源亦未确定；旧义所隐含的社会高低排序，如今被视为假设而非事实。"}]},"similar":{"note":{"en":"Group one holds words from the same citizen root that are easily confused; group two holds neighbouring terms for a society or its refinement.","cn":"第一组是同出「公民」词根、易混的词；第二组是与社会或其精致化相邻的术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"civil","ipa":"/ˈsɪvl/","tag":"adjective, civic","definition":"Of citizens or of non-military matters, and also polite; it is the adjective, while civilization is the society.","definitionCN":"指公民的、非军事的，也指有礼的；它是形容词，而 civilization 是社会本身。"},{"word":"civility","ipa":"/ˌsɪˈvɪləti/","tag":"politeness only","definition":"The quality of being polite in small dealings; it names behaviour, not cities or institutions.","definitionCN":"在小事上保持礼貌的品质；指行为，而非城市或制度。"},{"word":"citizen","ipa":"/ˈsɪtɪzn/","tag":"the person","definition":"A member of a state with rights and duties; the root person behind the whole family.","definitionCN":"拥有权利与义务的国家成员；是整个词族的词根所指之人。"},{"word":"civilian","ipa":"/sɪˈvɪliən/","tag":"not a soldier","definition":"A person who is not in the armed forces; it divides society by role, not by development.","definitionCN":"不在武装部队中的人；它按角色划分社会，而非按发展程度。"}]},{"heading":"NEAR MEANING","entries":[{"word":"culture","ipa":"/ˈkʌltʃə/","tag":"shared ways, not cities","definition":"From Latin colere 'to cultivate': the learned ways of a group, which every society has, whether or not it has cities.","definitionCN":"来自拉丁 colere「耕种」：一个群体习得的生活方式，任何社会都有，无论是否有城市。"},{"word":"society","ipa":"/səˈsaɪəti/","tag":"the association","definition":"From Latin socius 'companion': people living together under shared rules, a neutral term without a development scale.","definitionCN":"来自拉丁 socius「同伴」：在共同规则下共同生活的人，中性词，不含发展标尺。"},{"word":"barbarism","ipa":"/ˈbɑːbərɪzəm/","tag":"the old opposite","definition":"The supposed opposite of civilization in old schemes; the contrast is now treated as a value judgement.","definitionCN":"旧框架中假想的文明对立面；如今这种对立被视为价值判断。"},{"word":"civic","ipa":"/ˈsiːvɪk/","tag":"of the city as a unit","definition":"Relating to a city and its duties; it points at institutions and participation, not at a whole tradition.","definitionCN":"与城市及其义务有关；指向制度与参与，而非整个传统。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real set phrases and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The root is civis, a citizen, so civilization begins with people living together under law.","cn":"词根是 civis「公民」，所以文明始于在共同法律下生活的人。"},{"en":"The family runs civil, civilian, civility, civilize, civilized and civilization.","cn":"同族词包括 civil、civilian、civility、civilize、civilized 与 civilization。"},{"en":"Fixed phrases mark the scale: ancient civilization, the dawn of civilization, human civilization.","cn":"固定搭配标出尺度：古代文明、文明的黎明、人类文明。"},{"en":"Keep civilization the society apart from civility the politeness.","cn":"把指社会的 civilization 与指礼貌的 civility 分开。"},{"en":"Culture is the learned way of life; civilization adds cities, writing and institutions.","cn":"culture 是习得的生活方式；civilization 另加城市、文字与制度。"}],"abstract":[{"en":"Picture a mud-brick wall, an irrigation ditch and a written tablet in one cut-away view.","cn":"想象一幅剖面图里同时有泥砖墙、灌溉沟与刻字泥板。"},{"en":"Picture a queue that forms without anyone giving an order.","cn":"想象无人下令却自动排起的队伍。"},{"en":"Picture a library treating itself as the keeper of a shared inheritance.","cn":"想象一家图书馆把自己当作共同遗产的守护者。"}]},"examples":[{"en":"Irrigation made the first civilization in the valley possible.","cn":"灌溉使该河谷最早的文明成为可能。"},{"en":"The museum displays the civilization of the steppe alongside that of the river.","cn":"博物馆把草原文明与河谷文明并列展出。"},{"en":"Every civilization leaves its own kind of rubbish behind.","cn":"每一种文明都会留下自己那一类垃圾。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「civil（公民的）+ ization（化）」——把人变成有城有法的公民社会 → 文明","word":"civilization"},"root":"拉丁 civis「公民」→ civilis「公民的」→ civitas「公民全体」，加法语名词后缀 -isation 构成 civilisation。civis 的更深来源不确定。英语 civilization。","sensesIntro":{"en":"Eight meanings follow one word from a literate urban society to the supposed condition of being civil, a named tradition, modern comfort, the civilising process, city life, humanity's shared inheritance and finally shared norms.","cn":"八个义项沿同一个词展开：从有文字的城市社会，到假想的「开化」状态、具体传统、现代舒适生活、文明化进程、城市生活、人类共同遗产，最后是共同规范。"},"semanticMap":{"core":{"en":"CORE IMAGE: a mud-brick city showing walls, canals, tablets and a market at once.","cn":"核心意象：一座泥砖城同时露出城墙、水渠、泥板与集市。"},"chain":["CITIZEN","CITY","LITERATE SOCIETY","NAMED TRADITION","REFINEMENT SCALE","SHARED NORMS"],"branches":[{"senses":"S1 · S6","en":"CITY AT THE CENTRE: dense settlement and division of labour define the term.","cn":"城市在中心：密集定居与劳动分工界定这个词。"},{"senses":"S2 · S5","en":"PROCESS AND SCALE: the old ladder from savagery to refinement is now read as a process, not a ranking.","cn":"过程与标尺：从野蛮到精致的旧阶梯，如今被读作过程而非排序。"},{"senses":"S3 · S7","en":"BOUNDED AND COLLECTIVE: one tradition can be counted, all traditions can be inherited as one.","cn":"有界与集合：单个传统可计数，所有传统可作为一份遗产。"},{"senses":"S4","en":"MODERN COMFORT: hyperbole ties the word to power, plumbing and shops.","cn":"现代舒适：夸张用法把这个词绑在电力、自来水与商店上。"},{"senses":"S8","en":"QUIET NORMS: the abstraction reduces the word to predictable public behaviour.","cn":"无声的规范：抽象用法把这个词还原为可预期的公共行为。"}]},"affixes":{"intro":{"en":"Civilization is a Latin root with two suffixes, and the root also builds citizen, civil and civility.","cn":"civilization 是一个拉丁词根加两个后缀，该词根还构成 citizen、civil 与 civility。"},"latinIntro":{"en":"Latin civis and civitas build civil, civilian, civility and citizen; the suffix -ization marks a process or result.","cn":"拉丁 civis 与 civitas 构成 civil、civilian、civility 与 citizen；后缀 -ization 标记过程或结果。"},"items":[{"word":"civis","structure":"civis, civis (m./f., third declension)","meaning":"citizen","meaningCN":"公民","example":"Civis is the root person.","exampleCN":"civis 是词根所指的人。"},{"word":"civilis","structure":"civis + -ilis (relating to)","meaning":"of citizens, polite","meaningCN":"公民的；有礼的","example":"Civil law governs private disputes.","exampleCN":"民法处理私人纠纷。"},{"word":"civitas","structure":"civis + -itas (collective state)","meaning":"citizen body, city","meaningCN":"公民全体；城市","example":"Civitas named the whole body of citizens.","exampleCN":"civitas 指全体公民。"},{"word":"civil","structure":"civilis through French","meaning":"civic; polite","meaningCN":"公民的；有礼的","example":"The reply was civil but firm.","exampleCN":"答复有礼但坚定。"},{"word":"civilian","structure":"civil + -ian (person)","meaning":"one not in the military","meaningCN":"平民","example":"Civilians bore the loss.","exampleCN":"平民承受了损失。"},{"word":"civility","structure":"civil + -ity (quality)","meaning":"politeness","meaningCN":"礼貌","example":"He answered with civility.","exampleCN":"他礼貌地回答。"},{"word":"civilize","structure":"civil + -ize (make)","meaning":"to make civil","meaningCN":"使开化","example":"The mission tried to civilize the region.","exampleCN":"传教团试图使该地区开化。"},{"word":"-ization","structure":"-izare + -tion (process)","meaning":"the process of making","meaningCN":"使……化的过程","example":"civilization is the process or its result.","exampleCN":"civilization 就是过程或其结果。"}],"latinEntries":[{"word":"civis","structure":"civis, civis (m./f., third declension)","meaning":"citizen","meaningCN":"公民"},{"word":"civilis","structure":"civilis, civile (adj., third declension)","meaning":"of citizens, civic, polite","meaningCN":"公民的；城邦的；有礼的"},{"word":"civitas","structure":"civitas, civitatis (f., third declension)","meaning":"citizenship, the body of citizens, a city","meaningCN":"公民身份；公民全体；城市"}]}},{"word":"civilized","ipa_uk":"/ˈsɪvɪlaɪzd/","ipa_us":"/ˈsɪvəlaɪzd/","definition_zh":"文明的；有教养的；开化的；（口语）舒适宜人的","definition_en":"having a refined and orderly way of life, or showing polite behaviour; informally, pleasant and comfortable","core_image":"一张铺着白布的长桌，杯碟成行，人们压低声音交谈","scene":"晚餐时无人高声争执，主人把餐具摆得整整齐齐，客人称这里像文明世界的一角。No one raised a voice at dinner and the host laid every place neatly, so a guest called the house a corner of the civilized world.","sceneCN":"这里 civilized 指「举止有礼、生活有序的」（第 2 个义项：有教养的、讲礼的）；句意为晚餐时无人高声争执，主人把餐具摆得整齐，客人称这里像文明世界的一角。可辨识物件：白布长桌、成行杯碟、压低声音的客人、烛台。","pos":[{"tag":"adj.","zh":"文明的；有教养的；开化的；（口语）舒适宜人的"}],"collocations":[{"phrase":"civilized society","zh":"文明社会"},{"phrase":"civilized behaviour","zh":"有教养的行为"},{"phrase":"civilized world","zh":"文明世界"},{"phrase":"civilized conversation","zh":"有礼的交谈"},{"phrase":"a civilized hour","zh":"（口语）不算太晚的时刻"},{"phrase":"civilized treatment","zh":"人道对待"}],"forms":[{"label":"原级","form":"civilized"},{"label":"比较级","form":"more civilized"},{"label":"最高级","form":"most civilized"},{"label":"英式拼写","form":"civilised（英式拼写）"},{"label":"动词（使开化）","form":"civilize（使开化）"},{"label":"名词（文明）","form":"civilization（文明）"}],"derivatives":[{"word":"civilize","pos":"v.","zh":"使开化；使有教养"},{"word":"civilization","pos":"n.","zh":"文明"},{"word":"civil","pos":"adj.","zh":"公民的；民事的；有礼的"},{"word":"civility","pos":"n.","zh":"礼貌；谦恭"},{"word":"civilian","pos":"n.","zh":"平民"}],"senses":[{"no":"01","title":"Socially developed, with cities and institutions","titleCN":"拥有城市与制度的高度发展","definition":"belonging to a society with cities, writing and organised government","definitionCN":"属于拥有城市、文字与有组织政府的社会","example":"The river basin held a civilized order long before the first kingdom.","exampleCN":"早在第一个王国出现之前，这个流域已有文明秩序。","why":"the participle carries the process of civilization into an adjective, marking a society that has gone through it.","whyCN":"这个分词把「文明化」的过程带入形容词，标记已经走过这一过程的社会。"},{"no":"02","title":"Polite and considerate","titleCN":"有教养、讲礼的","definition":"behaving with restraint and courtesy toward others","definitionCN":"以克制与礼貌对待他人","example":"They disagreed for an hour and remained civilized throughout.","exampleCN":"他们争论了一个小时，全程仍保持有教养。","why":"the Latin adjective already meant 'polite', so the everyday sense is older than the archaeological one.","whyCN":"拉丁形容词本就有「有礼」之义，因此日常义比考古义更古老。"},{"no":"03","title":"Refined in taste and manner","titleCN":"品味与举止精致","definition":"showing cultivated taste in food, dress, speech or surroundings","definitionCN":"在饮食、穿着、言谈或环境上显示出修养","example":"The hotel served a civilized breakfast of fruit and strong coffee.","exampleCN":"这家酒店供应水果与浓咖啡，早餐颇为讲究。","why":"refinement is the visible trace of long training in restraint, which the adjective can mark.","whyCN":"精致是长期克制训练的可见痕迹，这个形容词可以标记它。"},{"no":"04","title":"Pleasant and comfortable, informally","titleCN":"口语中舒适宜人的","definition":"used lightly to mean agreeable, convenient or humane in ordinary arrangements","definitionCN":"轻松用法，指日常安排中令人愉快、方便或合乎人情","example":"A civilized wait of ten minutes beats an hour in the rain.","exampleCN":"等十分钟这种体面的等待，好过在雨里站一小时。","why":"the colloquial sense borrows the moral word for small comforts, which is why it sounds faintly humorous.","whyCN":"口语义把这个道德词借用于小舒适，因此听起来略带幽默。"},{"no":"05","title":"Humane treatment","titleCN":"人道的对待","definition":"showing that people or animals are treated with dignity rather than harshly","definitionCN":"显示人或动物受到有尊严的对待，而非粗暴对待","example":"The report demanded civilized conditions for the prisoners.","exampleCN":"报告要求为囚犯提供人道的条件。","why":"the word is used to set a floor of decency, implying that anything less is a lapse.","whyCN":"这个词被用来设定体面的下限，暗示低于此即为失格。"},{"no":"06","title":"Settled life rather than wilderness","titleCN":"定居生活而非荒野","definition":"describing settled, built landscapes as opposed to wild or frontier conditions","definitionCN":"描述已定居、已建设的环境，与荒野或边地相对","example":"Beyond the last fence the map stopped calling the land civilized.","exampleCN":"越过最后一道栅栏，地图便不再称这片土地为文明之地。","why":"the old contrast between town and wilderness survives in travel writing and maps.","whyCN":"城镇与荒野的古老对照在游记与地图中延续下来。"},{"no":"07","title":"A ranking of peoples, now contested","titleCN":"曾被用来给人排序（今有争议）","definition":"the older use that ranked peoples as more or less civilized, now avoided in careful writing","definitionCN":"旧用法把人按文明程度排序，如今在严谨写作中已被回避","example":"The old textbook called some peoples civilized and others savage.","exampleCN":"旧教科书把一些民族称为文明，另一些称为野蛮。","why":"the ranking was an imperial assumption, and modern usage treats it as a judgement rather than a description.","whyCN":"这种排序是帝国时代的假设，现代用法视其为判断而非描述。"},{"no":"08","title":"Abstract: acceptable and decent","titleCN":"抽象义：可接受、合体统的","definition":"used loosely of anything considered acceptable, orderly or decent","definitionCN":"宽泛地指任何被认为可接受、有序或体面的事物","example":"Ten in the morning is a civilized time to call, unlike six.","exampleCN":"上午十点打电话是体面的时间，六点则不是。","why":"the abstraction keeps only the approval: what is civilized is what a reasonable person would accept.","whyCN":"抽象用法只保留「认可」这一层：文明的就是通情达理者能接受的。"}],"etymology":{"intro":{"en":"Civilized is civil plus the verb ending -ize and the past-participle -ed, modelled on French civiliser. Civil goes back to Latin civis 'citizen'. Dates are approximate.","cn":"civilized 是 civil 加动词词尾 -ize 与过去分词 -ed，仿法语 civiliser 构成。civil 可回溯到拉丁 civis「公民」。年代均为约数。"},"items":[{"era":"LATIN CIVIS","en":"Civis 'citizen' is the root; its deeper origin is not established, and a connection with a root meaning 'to settle' is a hypothesis.","cn":"词根是 civis「公民」；其更远来源未得到证明，与表示「定居」的词根相联系只是假说。"},{"era":"LATIN CIVILIS","en":"Civilis 'of citizens, polite' already paired urbanity with courtesy, the two ideas the English word still joins.","cn":"civilis「公民的、有礼的」已把城市性与礼貌并置，英语词至今仍合着这两层。"},{"era":"GREEK AND LATIN -IZE","en":"Greek -izein and Latin -izare formed verbs meaning 'to make or become'; English -ize continues that pattern.","cn":"希腊 -izein 与拉丁 -izare 构成表示「使成为」的动词；英语 -ize 延续这一模式。"},{"era":"FRENCH CIVILISER","en":"French civiliser meant to bring someone into a polite, settled way of life, and English borrowed it in the sixteenth century.","cn":"法语 civiliser 意为使某人进入有礼、定居的生活方式，英语于 16 世纪借入。"},{"era":"NINETEENTH-CENTURY RANKING","en":"The participle was then used to rank peoples, a usage that later scholarship rejected as a value judgement.","cn":"这个分词随后被用于给民族排序，后来的学术研究将其视为价值判断而予拒斥。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): the earliest English citation is not fixed, and the pre-Latin origin of civis is unsettled, so any reconstructed root is a hypothesis.","cn":"来源不确定（首见年代与更深词源）：英语最早书证尚无定论，civis 在拉丁语之前的来源亦未确定，任何重构词根都是假说。"}]},"similar":{"note":{"en":"Group one holds the same-root forms that are frequently swapped with the participle; group two holds other words for refinement and courtesy.","cn":"第一组是常与该分词互换的同根形式；第二组是表示精致与礼貌的其他词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"civil","ipa":"/ˈsɪvl/","tag":"the base adjective","definition":"Means civic or polite, but makes no claim about social development; a civil reply is merely courteous.","definitionCN":"指公民的或有礼的，但不涉及社会发展程度；仅表礼貌时也只说 civil，与文明程度无关。"},{"word":"civilization","ipa":"/ˌsɪvɪlɪˈzeɪʃn/","tag":"the noun","definition":"The society or the process itself; civilized is the adjective describing what has gone through it.","definitionCN":"指社会或过程本身；civilized 是形容已走过这一过程之物的形容词。"},{"word":"civilised","ipa":"/ˈsɪvɪlaɪzd/","tag":"British spelling","definition":"The same word spelled with -s-, standard in British English; the meaning is identical.","definitionCN":"同一词的英式拼写，用 -s-，含义完全相同。"},{"word":"civic","ipa":"/ˈsiːvɪk/","tag":"of city institutions","definition":"Relating to a city's government and public duties, not to manners or development.","definitionCN":"与城市政府及公共职责有关，不涉及礼仪或发展程度。"}]},{"heading":"NEAR MEANING","entries":[{"word":"polite","ipa":"/pəˈlaɪt/","tag":"everyday courtesy","definition":"From Latin politus 'polished': the plain word for good manners, with no historical scale attached.","definitionCN":"来自拉丁 politus「打磨过的」：指有礼貌的日常词，不附带历史标尺。"},{"word":"cultured","ipa":"/ˈkʌltʃəd/","tag":"trained taste","definition":"Having learned taste in art and ideas; it stresses cultivation rather than social order.","definitionCN":"在艺术与思想上受过熏陶；强调修养，而非社会秩序。"},{"word":"refined","ipa":"/rɪˈfaɪnd/","tag":"purified by process","definition":"Literally purified, as sugar or oil, and by extension delicate in manner; it stresses the removal of coarseness.","definitionCN":"字面指被提纯，如糖或油，引申指举止细腻；强调去除粗糙。"},{"word":"urbane","ipa":"/ɜːˈbeɪn/","tag":"city-smooth","definition":"From Latin urbanus 'of the city': smooth and sophisticated in manner, the polish of city life.","definitionCN":"来自拉丁 urbanus「城市的」：举止圆熟老练，是城市生活的打磨。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real set phrases and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Civilized is civil plus -ize plus -ed: something that has been made civil.","cn":"civilized 是 civil 加 -ize 再加 -ed：已被使得有礼有序之物。"},{"en":"The Latin base already meant polite, which is why the everyday sense is the oldest.","cn":"拉丁词基本就有「有礼」之义，因此日常义是最古老的。"},{"en":"Fixed phrases mark the uses: civilized society, civilized behaviour, a civilized hour.","cn":"固定搭配标出用法：文明社会、有教养的行为、体面的时刻。"},{"en":"British spelling is civilised, with -s-, and the meaning does not change.","cn":"英式拼写为 civilised，用 -s-，含义不变。"},{"en":"Keep civil, civility and civilization apart: polite, politeness, and the society itself.","cn":"把 civil、civility、civilization 分开：有礼、礼貌、社会本身。"}],"abstract":[{"en":"Picture a long table with every glass placed at the same distance.","cn":"想象一张长桌，每只杯子摆在相同距离上。"},{"en":"Picture two people disagreeing in lowered voices.","cn":"想象两个人压低声音各持己见。"},{"en":"Picture a fence beyond which the map changes its word.","cn":"想象一道栅栏，越过它地图就换了一个词。"}]},"examples":[{"en":"A civilized argument leaves the other person's dignity intact.","cn":"有教养的争论会让对方的尊严完好无损。"},{"en":"The camp offered a civilized shower after ten days on the trail.","cn":"在野外走了十天后，营地提供了相当体面的淋浴。"},{"en":"Careful writers now avoid ranking peoples as more or less civilized.","cn":"严谨的作者如今避免把民族按文明程度排序。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「civil（有礼）+ ized（已……的）」——已经变得有礼有序 → 文明的","word":"civilized"},"root":"civil（拉丁 civilis「公民的、有礼的」，出自 civis「公民」）+ -ize + -ed，仿法语 civiliser。civis 的更深来源不确定。英语 civilized。","sensesIntro":{"en":"Eight meanings follow one adjective from the developed society to courtesy, cultivated taste, small comforts, humane treatment, settled land, the old ranking and finally everyday decency.","cn":"八个义项沿同一个形容词展开：从高度发展的社会，到礼貌、精致品味、小舒适、人道对待、定居之地、旧时排序，最后是日常体面。"},"semanticMap":{"core":{"en":"CORE IMAGE: a white-clothed table, evenly set, with voices kept low.","cn":"核心意象：铺白布的长桌，餐具整齐，说话压低。"},"chain":["CITIZEN","POLITE","CULTIVATED","COMFORTABLE","HUMANE","DECENT"],"branches":[{"senses":"S1 · S6","en":"SETTLED ORDER: cities and fenced land mark where the adjective applies.","cn":"定居秩序：城市与有栅栏的土地标出这个形容词的适用范围。"},{"senses":"S2 · S3","en":"VISIBLE REFINEMENT: courtesy and taste are the everyday traces of long training.","cn":"可见的精致：礼貌与品味是长期训练的日常痕迹。"},{"senses":"S4","en":"SMALL COMFORTS: the moral word is lent to showers and reasonable hours.","cn":"小舒适：这个道德词被借给淋浴与合理的时刻。"},{"senses":"S5","en":"A FLOOR OF DECENCY: humane treatment sets the minimum below which the word is refused.","cn":"体面下限：人道对待设定最低线，低于此便不配此词。"},{"senses":"S7 · S8","en":"FROM RANKING TO APPROVAL: the old scale is rejected, leaving only 'acceptable to a reasonable person'.","cn":"从排序到认可：旧标尺被拒斥，只剩「通情达理者可接受」。"}]},"affixes":{"intro":{"en":"Civilized is built from a Latin adjective, a verb ending and a participle ending, all three of which recur across English.","cn":"civilized 由一个拉丁形容词、一个动词词尾与一个分词词尾构成，三者在英语中都反复出现。"},"latinIntro":{"en":"Latin civis and civilis build civil, civilian, civility and civilize; the ending -ize comes from Greek -izein through Latin -izare.","cn":"拉丁 civis 与 civilis 构成 civil、civilian、civility 与 civilize；词尾 -ize 由希腊 -izein 经拉丁 -izare 而来。"},"items":[{"word":"civis","structure":"civis (Latin noun, 'citizen')","meaning":"citizen","meaningCN":"公民","example":"The root is the citizen.","exampleCN":"词根就是公民。"},{"word":"civilis","structure":"civis + -ilis","meaning":"of citizens, polite","meaningCN":"公民的；有礼的","example":"Civil manners came from the city.","exampleCN":"有礼的举止源自城市。"},{"word":"civil","structure":"civilis through French","meaning":"civic; courteous","meaningCN":"公民的；有礼的","example":"A civil answer costs nothing.","exampleCN":"有礼的回答不花分文。"},{"word":"-ize","structure":"-izein (Greek) through -izare (Latin)","meaning":"to make or become","meaningCN":"使成为","example":"civilize means to make civil.","exampleCN":"civilize 意为使有礼有序。"},{"word":"civilize","structure":"civil + -ize","meaning":"to bring into a settled polite order","meaningCN":"使进入有礼有序的状态","example":"The school tried to civilize the frontier.","exampleCN":"学校试图使边地开化。"},{"word":"-ed","structure":"-ed (past participle ending)","meaning":"having undergone","meaningCN":"已经经历……的","example":"civilized means having been made civil.","exampleCN":"civilized 意为已被使得有礼有序。"},{"word":"civility","structure":"civil + -ity","meaning":"politeness","meaningCN":"礼貌","example":"Civility keeps a meeting civil.","exampleCN":"礼貌使会议保持有礼。"},{"word":"civilization","structure":"civilize + -ation","meaning":"the process or its result","meaningCN":"文明化的过程或结果","example":"Civilization took centuries.","exampleCN":"文明化历经数百年。"}],"latinEntries":[{"word":"civis","structure":"civis, civis (m./f., third declension)","meaning":"citizen","meaningCN":"公民"},{"word":"civilis","structure":"civilis, civile (adj., third declension)","meaning":"of citizens, civic, polite","meaningCN":"公民的；城邦的；有礼的"},{"word":"civilitas","structure":"civilitas, civilitatis (f., third declension)","meaning":"citizenship; courteous conduct","meaningCN":"公民身份；有礼的行为"}]}},{"word":"antiquity","ipa_uk":"/ænˈtɪkwəti/","ipa_us":"/ænˈtɪkwəti/","definition_zh":"古代；远古时期；（总称）古代遗物；古老","definition_en":"the distant past, especially the ancient world before the Middle Ages, or the quality of being very old","core_image":"一尊断臂石像立在玻璃柜里，标签上写着公元前，旁边是一枚磨圆的铜钱","scene":"博物馆把断臂石雕与磨圆的钱币并置展出，说明它们来自地中海世界的古代。The museum placed the broken-armed statue beside worn coins and explained that both came from antiquity in the Mediterranean world.","sceneCN":"这里 antiquity 指「地中海世界的远古时期」（第 1 个义项：遥远的古代）；句意为博物馆把断臂石雕与磨圆的钱币并置展出，说明它们来自地中海世界的古代。可辨识物件：玻璃柜、断臂石像、磨圆铜钱、年代标签。","pos":[{"tag":"n.","zh":"古代；远古时期；古代遗物（复数 antiquities）；古老（不可数）"}],"collocations":[{"phrase":"in antiquity","zh":"在古代"},{"phrase":"since antiquity","zh":"自古以来"},{"phrase":"the antiquities of Egypt","zh":"埃及的古代文物"},{"phrase":"classical antiquity","zh":"古典古代（希腊罗马时期）"},{"phrase":"late antiquity","zh":"古代晚期"},{"phrase":"a city of great antiquity","zh":"一座非常古老的城市"}],"forms":[{"label":"复数（古代遗物）","form":"antiquities"},{"label":"形容词（古代的；古老的）","form":"ancient（古代的）"},{"label":"形容词（古董的）","form":"antique（古董的；古式的）"},{"label":"形容词（过时的）","form":"antiquated（过时的）"},{"label":"名词（古物研究者）","form":"antiquarian（古物研究者）"},{"label":"相关名词（古物；古董）","form":"antique（古董；古物）"}],"derivatives":[{"word":"antique","pos":"n./adj.","zh":"古董；古式的"},{"word":"ancient","pos":"adj.","zh":"古代的；古老的"},{"word":"antiquated","pos":"adj.","zh":"过时的；陈旧的"},{"word":"antiquarian","pos":"n./adj.","zh":"古物研究者（的）"},{"word":"antiquities","pos":"n.","zh":"古代文物（复数）"}],"senses":[{"no":"01","title":"The distant ancient past","titleCN":"遥远的古代","definition":"the far past, especially the period of the ancient Mediterranean and Near Eastern world","definitionCN":"遥远的过去，尤指古代地中海与近东世界的时期","example":"The harbour was already silted up in antiquity.","exampleCN":"这个港口在古代就已淤塞。","why":"antiquity names a period by its distance from us, not by any event that starts or ends it.","whyCN":"antiquity 以与我们的距离来命名一个时期，而非以某个起点或终点事件。"},{"no":"02","title":"The ancient world as a whole","titleCN":"作为整体的古代世界","definition":"ancient societies and their cultures taken together as a field of study","definitionCN":"把古代社会及其文化合为一个研究领域","example":"Scholars of antiquity compare Greek, Persian and Egyptian records.","exampleCN":"古代世界的研究者比较希腊、波斯与埃及的记录。","why":"the singular collective sense lets one word stand for many societies that never met.","whyCN":"单数集合义让一个词代表许多彼此未曾相遇的社会。"},{"no":"03","title":"Ancient objects and sites","titleCN":"古代遗物与遗址","definition":"physical remains of ancient life, usually in the plural, as in antiquities","definitionCN":"古代生活的实物遗存，通常用复数 antiquities","example":"The customs office stopped the export of antiquities without a permit.","exampleCN":"海关制止了无许可证的古代文物出口。","why":"the plural shifted the word from a period to the things that survive from it.","whyCN":"复数形式把这个词从「时期」转向「从该时期留存下来的物件」。"},{"no":"04","title":"The quality of being very old","titleCN":"古老这一属性","definition":"great age, measured by the distance between an object's origin and the present","definitionCN":"以物件起源与当下的距离来衡量的久远程度","example":"The oak's antiquity is measured in rings, not in dates.","exampleCN":"这棵橡树的古老程度以年轮而非年代来衡量。","why":"the abstract sense turns a period name into a measurable quality that any object can have.","whyCN":"抽象义把时期名称变成任何物件都可以拥有的可测属性。"},{"no":"05","title":"An object surviving from ancient times","titleCN":"一件古代遗存","definition":"a single old object or building treated as a relic of the ancient past","definitionCN":"被当作远古遗物的单件古物或建筑","example":"The carved seal is an antiquity of the first dynasty.","exampleCN":"这枚刻纹印章是第一王朝的一件古代遗存。","why":"the countable form lets curators speak of one relic, while the plural names a collection.","whyCN":"可数形式让策展人能说单件遗物，而复数则指一批收藏。"},{"no":"06","title":"Ancient style or appearance","titleCN":"古旧的风格与外观","definition":"the look or manner of something made long ago or made to seem so","definitionCN":"久远之物（或仿古之物）的外观或做法","example":"The room imitates the antiquity of a Roman courtyard.","exampleCN":"这个房间模仿罗马庭院的那种古意。","why":"design borrows the word for an effect, since age can be copied even when it cannot be owned.","whyCN":"设计借这个词指一种效果，因为年代可以被模仿，即使无法真正拥有。"},{"no":"07","title":"The classical tradition","titleCN":"古典传统","definition":"the Greek and Roman heritage as a continuing source for later art and thought","definitionCN":"作为后世艺术与思想持续源头的希腊罗马遗产","example":"The architect studied antiquity before drawing the museum's facade.","exampleCN":"建筑师在设计博物馆立面之前研究过古典传统。","why":"the Renaissance made a specific past into a permanent model, and that model kept the name.","whyCN":"文艺复兴把一段特定过去变成永久范本，这个范本沿用了这个词。"},{"no":"08","title":"Abstract: something long out of date","titleCN":"抽象义：早已过时之物","definition":"used loosely for ideas or practices felt to belong to a vanished age","definitionCN":"宽泛指让人觉得属于已逝时代的观念或做法","example":"The rule against left-handed desks is an antiquity of another era.","exampleCN":"禁止左手书桌的规定是另一个时代的古董。","why":"the abstraction keeps only the distance in time and drops the archaeology entirely.","whyCN":"抽象用法只保留时间上的距离，完全去掉考古内容。"}],"etymology":{"intro":{"en":"Antiquity comes from Latin antiquitas 'old age, the old times', from antiquus 'former, ancient', built on ante 'before'. It entered English through French. Dates are approximate.","cn":"antiquity 来自拉丁 antiquitas「老年、旧时」，出自 antiquus「先前的、古老的」，其词根为 ante「在……之前」。它经法语进入英语。年代均为约数。"},"items":[{"era":"LATIN ANTE","en":"Ante meant 'before, in front of'; it is generally taken to continue a Indo-European root for 'before', though the exact form is reconstructed.","cn":"ante 意为「在……之前、在前方」；一般被认为延续了印欧语中表示「在前」的词根，但确切形态属于重构。"},{"era":"LATIN ANTIQUUS","en":"Antiquus meant 'former, old, ancient', literally 'being before'; the suffix attached to ante is not fully explained.","cn":"antiquus 意为「先前的、旧的、古老的」，字面是「在前的存在」；加在 ante 上的词尾尚未得到完整解释。"},{"era":"LATIN ANTIQUITAS","en":"Antiquitas named old age and the old times, used of both persons and periods.","cn":"antiquitas 指老年与旧时，既可用于人，也可用于时期。"},{"era":"FRENCH ANTIQUITÉ","en":"Old French antiquité brought the word into English in the fourteenth century, first as 'oldness' and then as 'the old times'.","cn":"古法语 antiquité 于 14 世纪把该词带入英语，先指「古老」，继而指「旧时」。"},{"era":"ANTIQUITIES","en":"From the seventeenth century the plural was used for the objects and monuments surviving from ancient times.","cn":"自 17 世纪起，复数形式被用于指从古代留存下来的物件与遗迹。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and morphological detail): the earliest citation for the 'relics' sense is not fixed, and the formation of antiquus from ante is not fully explained, so the suffix analysis offered here is a reconstruction.","cn":"来源不确定（首见年代与形态细节）：「遗物」义的最早书证尚无定论；antiquus 由 ante 构成的方式未得到完整解释，此处对词尾的分析属于重构。"}]},"similar":{"note":{"en":"Group one holds the same-root words that are constantly confused; group two holds terms for the ancient world and for things that are merely old.","cn":"第一组是同根、极易混淆的词；第二组是古代世界与「只是旧」之物的术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ancient","ipa":"/ˈeɪnʃənt/","tag":"adjective, of the far past","definition":"From Latin ante through French ancien: it describes what belongs to the distant past, while antiquity names that period or its remains.","definitionCN":"经法语 ancien 来自拉丁 ante：形容属于遥远过去之物，而 antiquity 指那个时期或其遗存。"},{"word":"antique","ipa":"/ænˈtiːk/","tag":"an object, and its style","definition":"From the same antiquus: a decorative object of some age, or a style copied from the past; it does not name a historical period.","definitionCN":"同出 antiquus：指有一定年代的装饰性物件，或仿古风格；不指历史时期。"},{"word":"antiquated","ipa":"/ˈæntɪkweɪtɪd/","tag":"out of date","definition":"Made obsolete: it describes things judged old-fashioned rather than ancient, and often carries disapproval.","definitionCN":"指已废弃：描述被判定为老派而非古老之物，常含贬义。"},{"word":"antiquarian","ipa":"/ˌæntɪˈkweəriən/","tag":"the person","definition":"One who collects or studies old objects; the person form, not the period or the relic.","definitionCN":"收藏或研究古物的人；指人，而非时期或遗物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"the ancient world","ipa":"/ði ˈeɪnʃənt wɜːld/","tag":"the plain phrase","definition":"The everyday term for the societies of antiquity, especially Greece and Rome; it names the same field without the formality.","definitionCN":"指古代社会的日常说法，尤指希腊与罗马；指同一领域，只是不那么正式。"},{"word":"prehistory","ipa":"/ˌpriːˈhɪstri/","tag":"before writing","definition":"The period before written records, which lies earlier than antiquity as usually defined.","definitionCN":"指成文记录之前的时期，按通常定义比古代更早。"},{"word":"heritage","ipa":"/ˈherɪtɪdʒ/","tag":"what is passed down","definition":"What is inherited from the past and valued now; it includes antiquities but also later buildings and customs.","definitionCN":"从过去继承并被珍视之物；包含古代文物，也包含更晚的建筑与习俗。"},{"word":"relic","ipa":"/ˈrelɪk/","tag":"one surviving object","definition":"A single object that survives from an earlier time; it is one item, while antiquities is a category.","definitionCN":"从更早时代留存下来的单件物品；它是一件，而 antiquities 是一个类别。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real set phrases and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The root is ante, before, so antiquity is literally the time before.","cn":"词根是 ante「在前」，所以 antiquity 字面上就是「之前的时间」。"},{"en":"The family runs ancient, antique, antiquated, antiquarian and antiquities.","cn":"同族词包括 ancient、antique、antiquated、antiquarian 与 antiquities。"},{"en":"Fixed phrases mark the uses: in antiquity, classical antiquity, late antiquity.","cn":"固定搭配标出用法：在古代、古典古代、古代晚期。"},{"en":"Plural antiquities means objects; the singular usually means the period.","cn":"复数 antiquities 指文物；单数通常指时期。"},{"en":"Keep antique for a valuable old object and antiquated for something merely out of date.","cn":"把 antique 用于有价值的旧物，antiquated 用于单纯过时之物。"}],"abstract":[{"en":"Picture a glass case holding a statue with a missing arm.","cn":"想象玻璃柜里立着一尊缺臂的石像。"},{"en":"Picture a coin worn smooth by centuries of hands.","cn":"想象一枚被无数双手磨得光滑的钱币。"},{"en":"Picture a rule still posted on a wall that no longer applies.","cn":"想象一条仍贴在墙上、却已不适用的规定。"}]},"examples":[{"en":"The city's walls have stood since antiquity.","cn":"这座城的城墙自古代起就矗立至今。"},{"en":"Trade in antiquities is restricted by international agreement.","cn":"古代文物的交易受国际协定限制。"},{"en":"Late antiquity saw the slow end of the classical city.","cn":"在古代晚期，古典城市缓慢走向终结。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「anti（前）+ quity（古）」——在我们之前的久远年代 → 古代","word":"antiquity"},"root":"拉丁 antiquitas「老年、旧时」，出自 antiquus「先前的、古老的」，词根 ante「在……之前」；antiquus 由 ante 构成的具体方式未完全解释。英语 antiquity。","sensesIntro":{"en":"Eight meanings follow one word from the distant period to the ancient world as a field, its surviving objects, the quality of age, a single relic, an antique look, the classical tradition and finally anything out of date.","cn":"八个义项沿同一个词展开：从遥远时期，到作为研究领域的古代世界、留存文物、古老属性、单件遗存、仿古外观、古典传统，最后是任何过时之物。"},"semanticMap":{"core":{"en":"CORE IMAGE: a glass case with a broken-armed statue and a worn coin.","cn":"核心意象：玻璃柜中一尊断臂石像与一枚磨圆的钱币。"},"chain":["BEFORE","DISTANT TIME","ANCIENT WORLD","SURVIVING OBJECTS","GREAT AGE","OUT OF DATE"],"branches":[{"senses":"S1 · S2","en":"PERIOD AND FIELD: the same distance in time becomes a subject of study.","cn":"时期与领域：同一段时间距离变成一门研究对象。"},{"senses":"S3 · S5","en":"THINGS LEFT: plural and singular divide a collection from one relic.","cn":"留下之物：复数与单数把一批收藏与单件遗存分开。"},{"senses":"S4","en":"MEASURED AGE: any object can carry the quality the period name implies.","cn":"可测的年龄：任何物件都能带上时期名称所暗示的属性。"},{"senses":"S6 · S7","en":"STYLE AND MODEL: age can be imitated, and a specific past can become a permanent example.","cn":"风格与范本：年代可被模仿，某段特定过去可成为永久范例。"},{"senses":"S8","en":"SLIGHTLY COMIC DISTANCE: anything obsolete borrows the word for a laugh.","cn":"略带戏谑的距离：任何过时之物都借这个词开玩笑。"}]},"affixes":{"intro":{"en":"Antiquity is a Latin noun with an abstract ending, and its root ante also builds words about position and priority.","cn":"antiquity 是一个带抽象词尾的拉丁名词，其词根 ante 还构成表示位置与先后的一些词。"},"latinIntro":{"en":"Latin ante and antiquus build ancient, antique, antiquities and ante itself appears in antecedent and anterior.","cn":"拉丁 ante 与 antiquus 构成 ancient、antique、antiquities，ante 本身出现在 antecedent 与 anterior 中。"},"items":[{"word":"ante","structure":"ante (Latin preposition, 'before')","meaning":"before, in front of","meaningCN":"在……之前；在前方","example":"The root places the past before us.","exampleCN":"词根把过去置于我们之前。"},{"word":"antiquus","structure":"ante + suffix (former, ancient)","meaning":"old, former","meaningCN":"旧的；先前的","example":"Antiquus described what came before.","exampleCN":"antiquus 描述先于现在之物。"},{"word":"antiquitas","structure":"antiquus + -itas (abstract quality)","meaning":"old age; the old times","meaningCN":"古老；旧时","example":"Antiquitas named the distant period.","exampleCN":"antiquitas 指遥远的时期。"},{"word":"antiquity","structure":"antiquitas through French","meaning":"the ancient past; a relic","meaningCN":"古代；古物","example":"The statue dates from antiquity.","exampleCN":"这尊石像属古代。"},{"word":"ancient","structure":"ante through French ancien","meaning":"of the far past","meaningCN":"远古的","example":"Ancient walls surround the site.","exampleCN":"古墙环绕遗址。"},{"word":"antique","structure":"antiquus through French","meaning":"an old decorative object","meaningCN":"古董；古式的","example":"The shop sells antique coins.","exampleCN":"这家店出售古钱币。"},{"word":"antiquated","structure":"antique + -ated (made old)","meaning":"out of date","meaningCN":"过时的","example":"The rule is antiquated.","exampleCN":"这条规定已过时。"},{"word":"antiquarian","structure":"antiquity + -arian (person)","meaning":"a student of old objects","meaningCN":"古物研究者","example":"The antiquarian catalogued the seals.","exampleCN":"古物研究者为印章编目。"},{"word":"antecedent","structure":"ante- + cedere (go before)","meaning":"something that came before","meaningCN":"前事；先行项","example":"The antecedent of the pronoun is unclear.","exampleCN":"该代词的前指对象不清楚。"}],"latinEntries":[{"word":"ante","structure":"ante (preposition with accusative)","meaning":"before, in front of","meaningCN":"在……之前；在前方"},{"word":"antiquus","structure":"antiquus, antiqua, antiquum (adj.)","meaning":"former, old, ancient","meaningCN":"先前的；旧的；古老的"},{"word":"antiquitas","structure":"antiquitas, antiquitatis (f., third declension)","meaning":"old age, the old times","meaningCN":"老年；旧时"}]}}]);
